import React, { useEffect, useState, useRef } from 'react';
import { LanguageProvider, useLanguage } from './contexts/LanguageContext';
import { BrowserRouter as Router, Routes, Route, Link, useLocation, Navigate } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import { motion, AnimatePresence } from 'framer-motion';
import { Home, History, User, Globe, Bot, ShieldAlert, Check, Menu, Crown, Film, Building } from 'lucide-react';
import { Dashboard } from './pages/Dashboard';
import { Wallet } from './pages/Wallet';
import { Account } from './pages/Account';
import { Affiliate } from './pages/Affiliate';
import { BindAccount } from './pages/BindAccount';
import { Login } from './pages/Login';
import { Transactions } from './pages/Transactions';
import { Trading } from './pages/Trading';
import { Security } from './pages/Security';
import { Notifications } from './pages/Notifications';
import { VIP } from './pages/VIP';
import { MyBots } from './pages/MyBots';
import { About } from './pages/About';
import { Event } from './pages/Event';
import { Withdraw } from './pages/Withdraw';
import { Admin } from './pages/Admin';
import { FAQ } from './pages/FAQ';
import { Spin } from './pages/Spin';
import { Assets } from './pages/Assets';
import { Market } from './pages/Market';
import { Movies } from './pages/Movies';
import { Wealth } from './pages/Wealth';
import { ChatEarn } from './pages/ChatEarn';
import { Support } from './pages/Support';
import { AdminSupport } from './pages/AdminSupport';
import { useCurrency } from './hooks/useCurrency';
import { AuthProvider, useAuth } from './contexts/AuthContext';
import { App as CapApp } from '@capacitor/app';
import { setupPushNotifications } from './services/pushNotifications';
import { NetworkOverlay } from './components/NetworkOverlay';
import { FloatingSupport } from './components/FloatingSupport';
import './index.css'; 

const PrivateRoute = ({ children }) => {
  const { currentUser } = useAuth();
  return currentUser ? children : <Navigate to="/login" />;
};

const HardwareBackButton = () => {
  const location = useLocation();

  useEffect(() => {
    const handleBackButton = ({ canGoBack }) => {
      // If we are at the root or login page, let the app close natively
      if (location.pathname === '/' || location.pathname === '/login') {
        CapApp.exitApp();
      } else {
        // Otherwise, navigate back in the React Router history
        window.history.back();
      }
    };

    CapApp.addListener('backButton', handleBackButton);

    return () => {
      CapApp.removeAllListeners();
    };
  }, [location]);

  return null;
};

const BottomNav = () => {
  const location = useLocation();
  const { t } = useLanguage();
  
  const isActive = (path) => location.pathname === path ? "active" : "";

  return (
    <nav className="bottom-nav">
      <Link to="/" className={isActive('/')}>
        <Home size={20} />
        <span>{t('home')}</span>
      </Link>
      <Link to="/market" className={isActive('/market')}>
        <Globe size={20} />
        <span>Market</span>
      </Link>
      <Link to="/transactions" className={isActive('/transactions')}>
        <History size={20} />
        <span>History</span>
      </Link>
      <Link to="/assets" className={isActive('/assets')}>
        <History size={20} />
        <span>Assets</span>
      </Link>
      <Link to="/account" className={isActive('/account')}>
        <User size={20} />
        <span>{t('me')}</span>
      </Link>
    </nav>
  );
};

const Sidebar = ({ isSidebarOpen, setSidebarOpen }) => {
  return (
    <aside className={`sidebar ${isSidebarOpen ? 'open' : ''}`}>
      <div className="brand-header" style={{ padding: '24px', borderBottom: '1px solid var(--border-light)' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <img src="/logo.png" alt="QTX Coin Logo" style={{ height: '32px', width: 'auto', objectFit: 'contain' }} />
          <h2 style={{ color: 'var(--primary)', letterSpacing: '1px', margin: 0, fontSize: '1.2rem' }}>QTX Coin</h2>
        </div>
      </div>
      <div style={{ padding: '16px 0', display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <Link to="/transactions" onClick={() => setSidebarOpen(false)} style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '12px 24px', color: 'var(--text-secondary)', textDecoration: 'none', fontSize: '1rem' }} className="hover:bg-panel-hover">
          <History size={20} />
          <span>History</span>
        </Link>
        <Link to="/vip" onClick={() => setSidebarOpen(false)} style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '12px 24px', color: 'var(--text-secondary)', textDecoration: 'none', fontSize: '1rem' }} className="hover:bg-panel-hover">
          <Crown size={20} color="var(--warning)" />
          <span>VIP Bots</span>
        </Link>
        <Link to="/my-bots" onClick={() => setSidebarOpen(false)} style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '12px 24px', color: 'var(--text-secondary)', textDecoration: 'none', fontSize: '1rem' }} className="hover:bg-panel-hover">
          <Bot size={20} color="var(--primary)" />
          <span>My Bots</span>
        </Link>
        <Link to="/movies" onClick={() => setSidebarOpen(false)} style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '12px 24px', color: 'var(--text-secondary)', textDecoration: 'none', fontSize: '1rem' }} className="hover:bg-panel-hover">
          <Film size={20} color="#ef4444" />
          <span>Watch &amp; Earn</span>
        </Link>
        <Link to="/assets" onClick={() => setSidebarOpen(false)} style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '12px 24px', color: 'var(--text-secondary)', textDecoration: 'none', fontSize: '1rem' }} className="hover:bg-panel-hover">
          <Crown size={20} color="var(--warning)" />
          <span>Assets</span>
        </Link>
        <Link to="/about" onClick={() => setSidebarOpen(false)} style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '12px 24px', color: 'var(--text-secondary)', textDecoration: 'none', fontSize: '1rem' }} className="hover:bg-panel-hover">
          <Building size={20} />
          <span>About</span>
        </Link>
        <Link to="/market" onClick={() => setSidebarOpen(false)} style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '12px 24px', color: 'var(--text-secondary)', textDecoration: 'none', fontSize: '1rem' }} className="hover:bg-panel-hover">
          <Globe size={20} color="var(--primary)" />
          <span>Market</span>
        </Link>
      </div>
    </aside>
  );
};

const COUNTRIES = [
  { code: 'KE', name: 'Kenya' },
  { code: 'MZ', name: 'Mozambique' },
  { code: 'TZ', name: 'Tanzania' },
  { code: 'UG', name: 'Uganda' },
  { code: 'BW', name: 'Botswana' },
  { code: 'CD', name: 'Congo (DRC)' },
  { code: 'ZM', name: 'Zambia' },
  { code: 'BI', name: 'Burundi' },
  { code: 'GH', name: 'Ghana' },
  { code: 'UN', name: 'Global/Other' }
];

const Topbar = ({ setSidebarOpen }) => {
  const { balance, isAdmin, userData } = useAuth();
  const { t, language, changeLanguage } = useLanguage();
  const { formatCurrency, convertAndFormatCurrency } = useCurrency();
  const [langOpen, setLangOpen] = useState(false);
  const langRef = useRef(null);

  useEffect(() => {
    const handler = (e) => { if (langRef.current && !langRef.current.contains(e.target)) setLangOpen(false); };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);
  
  const userCountryObj = userData?.country ? COUNTRIES.find(c => c.name === userData.country) : null;
  const countryCode = userCountryObj ? userCountryObj.code : null;

  return (
    <header className="topbar" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
        <button className="menu-btn" onClick={() => setSidebarOpen(true)} style={{ color: 'var(--text-primary)', padding: '4px', display: 'flex' }}>
          <Menu size={24} />
        </button>
        <img src="/logo.png" alt="QTX Coin Logo" style={{ height: '28px', width: 'auto', objectFit: 'contain' }} />
        {countryCode && countryCode !== 'UN' ? (
          <img 
            src={`https://flagcdn.com/w40/${countryCode.toLowerCase()}.png`} 
            alt="Country Flag" 
            style={{ width: '28px', height: '20px', borderRadius: '4px', objectFit: 'cover', boxShadow: '0 2px 5px rgba(0,0,0,0.2)' }} 
          />
        ) : (
          <Globe size={24} color="var(--primary)" />
        )}
      </div>
      <div className="topbar-right" style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
        {isAdmin && (
          <Link to="/admin" className="btn" style={{ background: 'var(--danger)', color: '#fff', padding: '6px 12px', fontSize: '0.8rem', display: 'flex', alignItems: 'center', gap: '4px', border: 'none' }}>
            <ShieldAlert size={14} /> Admin
          </Link>
        )}
        {/* Balance */}
        <div style={{ textAlign: 'right', flexShrink: 0 }}>
          <div className="topbar-balance-label" style={{ fontSize: '0.75rem', color: 'var(--text-muted)', whiteSpace: 'nowrap' }}>{t('liveBalance')}</div>
          <div style={{ fontWeight: 700, color: 'var(--success)', fontSize: '0.9rem', whiteSpace: 'nowrap' }}>{convertAndFormatCurrency(balance)}</div>
        </div>
        <div ref={langRef} style={{ position: 'relative' }}>
          <button
            onClick={() => setLangOpen(o => !o)}
            style={{
              display: 'flex', alignItems: 'center', gap: '5px',
              background: langOpen ? 'var(--primary-glow)' : 'var(--bg-dark)',
              border: `1px solid ${langOpen ? 'var(--primary)' : 'var(--border)'}`,
              borderRadius: '20px', padding: '5px 10px', cursor: 'pointer',
              color: 'var(--text-secondary)', fontSize: '12px', fontWeight: 600,
              transition: 'all 0.2s',
            }}
          >
            <Globe size={13} color="var(--primary)" />
            <span>{language === 'en' ? '🇬🇧' : '🇧🇷'}</span>
            <span style={{ fontSize: '9px', color: 'var(--text-muted)', transform: langOpen ? 'rotate(180deg)' : 'rotate(0deg)', transition: 'transform 0.2s', display: 'inline-block' }}>▾</span>
          </button>

          <AnimatePresence>
            {langOpen && (
              <motion.div
                initial={{ opacity: 0, y: -6, scale: 0.95 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, y: -6, scale: 0.95 }}
                transition={{ duration: 0.15 }}
                style={{
                  position: 'absolute', top: 'calc(100% + 6px)', right: 0,
                  background: 'var(--bg-panel)', border: '1px solid var(--border)',
                  borderRadius: '12px', minWidth: '150px', overflow: 'hidden',
                  boxShadow: '0 8px 24px rgba(0,0,0,0.4)', zIndex: 1000,
                }}
              >
                {[{ code: 'en', flag: '🇬🇧', label: t('langEnglish') }, { code: 'pt', flag: '🇧🇷', label: t('langPortuguese') }].map(lang => (
                  <button
                    key={lang.code}
                    onClick={() => { changeLanguage(lang.code); setLangOpen(false); }}
                    style={{
                      width: '100%', display: 'flex', alignItems: 'center', gap: '10px',
                      padding: '10px 14px',
                      background: language === lang.code ? 'rgba(16,185,129,0.08)' : 'transparent',
                      border: 'none', cursor: 'pointer',
                      color: language === lang.code ? 'var(--primary)' : 'var(--text-secondary)',
                      fontSize: '13px', fontWeight: language === lang.code ? 700 : 400,
                      borderBottom: lang.code === 'en' ? '1px solid var(--border)' : 'none',
                    }}
                  >
                    <span style={{ fontSize: '18px' }}>{lang.flag}</span>
                    <span style={{ flex: 1, textAlign: 'left' }}>{lang.label}</span>
                    {language === lang.code && <Check size={13} />}
                  </button>
                ))}
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        <Link to="/wallet" className="btn btn-primary topbar-deposit-btn" style={{ padding: '6px 12px', fontSize: '0.8rem', flexShrink: 0, gap: '4px' }}>
          <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 5v14M5 12l7 7 7-7"/></svg>
          <span className="topbar-deposit-text">{t('deposit')}</span>
        </Link>
      </div>
    </header>
  );
};

function AppContent() {
  const location = useLocation();
  const { currentUser } = useAuth();
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  useEffect(() => {
    if (currentUser) {
      setupPushNotifications(currentUser.uid);
    }
  }, [currentUser]);
  
  if (!currentUser && location.pathname !== '/login') {
    return <Navigate to="/login" />;
  }

  return (
    <div className="app-container">
      <Toaster position="top-center" toastOptions={{
        style: {
          background: '#1f2937',
          color: '#f3f4f6',
          border: '1px solid rgba(255, 255, 255, 0.1)',
        }
      }} />
      
      {currentUser && (
        <>
          <div 
            className={`sidebar-overlay ${isSidebarOpen ? 'open' : ''}`} 
            onClick={() => setSidebarOpen(false)} 
          />
          <Sidebar isSidebarOpen={isSidebarOpen} setSidebarOpen={setSidebarOpen} />
        </>
      )}
      
      <main className="main-content" style={{ width: currentUser ? 'auto' : '100%' }}>
        {currentUser && <Topbar setSidebarOpen={setSidebarOpen} />}
        <AnimatePresence mode="wait">
          <Routes location={location} key={location.pathname}>
            <Route path="/login" element={<Login />} />
            <Route path="/" element={<PrivateRoute><Dashboard /></PrivateRoute>} />
            <Route path="/wallet" element={<PrivateRoute><Wallet /></PrivateRoute>} />
            <Route path="/trading" element={<PrivateRoute><Trading /></PrivateRoute>} />
            <Route path="/transactions" element={<PrivateRoute><Transactions /></PrivateRoute>} />
            <Route path="/affiliate" element={<PrivateRoute><Affiliate /></PrivateRoute>} />
            <Route path="/bind-account" element={<PrivateRoute><BindAccount /></PrivateRoute>} />
            <Route path="/account" element={<PrivateRoute><Account /></PrivateRoute>} />
            <Route path="/security" element={<PrivateRoute><Security /></PrivateRoute>} />
            <Route path="/notifications" element={<PrivateRoute><Notifications /></PrivateRoute>} />
            <Route path="/vip" element={<PrivateRoute><VIP /></PrivateRoute>} />
            <Route path="/my-bots" element={<PrivateRoute><MyBots /></PrivateRoute>} />
            <Route path="/about" element={<PrivateRoute><About /></PrivateRoute>} />
            <Route path="/event" element={<PrivateRoute><Event /></PrivateRoute>} />
            <Route path="/withdraw" element={<PrivateRoute><Withdraw /></PrivateRoute>} />
            <Route path="/admin" element={<PrivateRoute><Admin /></PrivateRoute>} />
            <Route path="/faq" element={<PrivateRoute><FAQ /></PrivateRoute>} />
            <Route path="/spin" element={<PrivateRoute><Spin /></PrivateRoute>} />
            <Route path="/assets" element={<PrivateRoute><Assets /></PrivateRoute>} />
            <Route path="/market" element={<PrivateRoute><Market /></PrivateRoute>} />
            <Route path="/movies" element={<PrivateRoute><Movies /></PrivateRoute>} />
            <Route path="/chat-earn" element={<PrivateRoute><ChatEarn /></PrivateRoute>} />
            <Route path="/wealth" element={<PrivateRoute><Wealth /></PrivateRoute>} />
            <Route path="/support" element={<PrivateRoute><Support /></PrivateRoute>} />
            <Route path="/admin/support" element={<PrivateRoute><AdminSupport /></PrivateRoute>} />
          </Routes>
        </AnimatePresence>
      </main>
      {currentUser && <BottomNav />}
    </div>
  );
}

function App() {
  return (
    <Router>
      <HardwareBackButton />
      <AuthProvider>
        <LanguageProvider>
          <NetworkOverlay />
          <FloatingSupport />
          <AppContent />
        </LanguageProvider>
      </AuthProvider>
    </Router>
  );
}

export default App;

import React, { useEffect, useState } from 'react';

// Re-detect if cached as Global/Detecting (stale states should always be refreshed)
const STALE_STATES = ['Detecting...', 'Global', '', null, undefined];

export const useCountry = () => {
  const [countryData, setCountryData] = useState(() => {
    try {
      const cached = localStorage.getItem('eaglefx_country');
      if (cached) {
        const parsed = JSON.parse(cached);
        // Only use cache if it resolved to a real country
        if (parsed?.country && !STALE_STATES.includes(parsed.country)) {
          return parsed;
        }
      }
    } catch (_) {}
    return { country: 'Detecting...', countryCode: '', error: null };
  });

  useEffect(() => {
    // Always re-fetch if current state is stale
    if (!STALE_STATES.includes(countryData.country)) return;

    // Clear any stale cached Global so it doesn't block MZ detection
    localStorage.removeItem('eaglefx_country');

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 7000);

    fetch('https://get.geojs.io/v1/ip/geo.json', { signal: controller.signal })
      .then(res => {
        if (!res.ok) throw new Error('API Error');
        return res.json();
      })
      .then(data => {
        clearTimeout(timeoutId);
        const newData = {
          country: data.country || 'Global',
          countryCode: data.country_code || '',
          error: null
        };
        setCountryData(newData);
        // Only cache if we got a real country
        if (newData.country && newData.country !== 'Global') {
          localStorage.setItem('eaglefx_country', JSON.stringify(newData));
        }
      })
      .catch(err => {
        clearTimeout(timeoutId);
        const fallback = { country: 'Global', countryCode: 'GL', error: err.message };
        setCountryData(fallback);
        // Don't cache Global — always try again next time
      });

    return () => { clearTimeout(timeoutId); controller.abort(); };
  }, []);

  return countryData;
};

import React, { useEffect, useState } from 'react';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend, LineController, BarController } from 'chart.js';
import { Bar } from 'react-chartjs-2';
import { useAuth } from '../contexts/AuthContext';
import { db } from '../firebase';
import { collection, query, getDocs } from 'firebase/firestore';
import { useCurrency } from '../hooks/useCurrency';
import { useLanguage } from '../contexts/LanguageContext';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend, LineController, BarController);

export const DashboardCharts = () => {
  const { currentUser } = useAuth();
  const { symbol, formatCurrency, convertAndFormatCurrency } = useCurrency();
  const { t } = useLanguage();
  const [weeklyData, setWeeklyData] = useState({ earnings: [0,0,0,0,0,0,0], counts: [0,0,0,0,0,0,0] });
  const [yearlyData, setYearlyData] = useState({ earnings: [0,0,0,0,0], rates: [0,0,0,0,0] });

  // Generate labels for last 7 days
  const last7DaysLabels = Array.from({length: 7}, (_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - (6 - i));
    return d.toLocaleDateString('en-US', { weekday: 'short' });
  });

  const yearLabels = ["2022", "2023", "2024", "2025", new Date().getFullYear().toString()];

  useEffect(() => {
    if (!currentUser) return;

    const fetchAnalytics = async () => {
      try {
        const q = query(collection(db, 'users', currentUser.uid, 'transactions'));
        const querySnapshot = await getDocs(q);
        const txs = querySnapshot.docs.map(doc => doc.data());

        // Process Weekly Data
        const wEarnings = [0,0,0,0,0,0,0];
        const wCounts = [0,0,0,0,0,0,0];

        const today = new Date();
        today.setHours(23, 59, 59, 999);
        const sevenDaysAgo = new Date(today);
        sevenDaysAgo.setDate(today.getDate() - 6);
        sevenDaysAgo.setHours(0, 0, 0, 0);

        // Process Yearly Data
        const currentYear = new Date().getFullYear();
        const yEarningsMap = {
          "2022": 0, "2023": 0, "2024": 0, "2025": 0, [currentYear.toString()]: 0
        };

        txs.forEach(tx => {
          // We consider affiliate_reward, bot_profit, deposit, etc as "earnings" for the chart, 
          // or basically any transaction that adds to the user's balance.
          // For now, let's include affiliate_reward and bot_profit, and deposit if it's verified.
          const isEarning = tx.type === 'affiliate_reward' || tx.type === 'bot_profit' || tx.type === 'mining_reward' || tx.type === 'vip_profit';
          const amount = tx.amount || tx.expectedAmount || 0;
          
          if (!tx.createdAt) return;
          const txDate = tx.createdAt.toDate ? tx.createdAt.toDate() : new Date(tx.createdAt);

          // Weekly aggregation
          if (txDate >= sevenDaysAgo && txDate <= today) {
            // Find which day index (0-6)
            const diffTime = txDate.getTime() - sevenDaysAgo.getTime();
            const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
            if (diffDays >= 0 && diffDays <= 6) {
              if (isEarning) wEarnings[diffDays] += amount;
              wCounts[diffDays] += 1;
            }
          }

          // Yearly aggregation
          const y = txDate.getFullYear().toString();
          if (yEarningsMap[y] !== undefined && isEarning) {
            yEarningsMap[y] += amount;
          }
        });

        const yEarnings = [
          yEarningsMap["2022"],
          yEarningsMap["2023"],
          yEarningsMap["2024"],
          yEarningsMap["2025"],
          yEarningsMap[currentYear.toString()]
        ];

        // Calculate simple growth rate (mocking past years slightly if empty just to show the lines)
        const yRates = [0, 0, 0, 0, 0];
        for (let i = 1; i < yEarnings.length; i++) {
          if (yEarnings[i-1] > 0) {
            yRates[i] = ((yEarnings[i] - yEarnings[i-1]) / yEarnings[i-1]) * 100;
          }
        }

        setWeeklyData({ earnings: wEarnings, counts: wCounts });
        setYearlyData({ earnings: yEarnings, rates: yRates });
        
      } catch (error) {
        console.error("Failed to fetch analytics", error);
      }
    };

    fetchAnalytics();
  }, [currentUser]);

  const weeklyChartData = {
    labels: last7DaysLabels,
    datasets: [
      {
        type: "line",
        label: `${t('dailyEarnings')} (${symbol})`,
        data: weeklyData.earnings,
        borderColor: "#d4af37", // Primary gold
        backgroundColor: "rgba(212, 175, 55, 0.2)",
        tension: 0.4,
        yAxisID: "y",
        pointBackgroundColor: "#d4af37",
        pointRadius: 4,
        borderWidth: 2
      },
      {
        type: "bar",
        label: t('transactionCount'),
        data: weeklyData.counts,
        backgroundColor: "rgba(59, 130, 246, 0.6)", // Secondary blue
        yAxisID: "y1",
        borderRadius: 4
      }
    ]
  };

  const weeklyChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    interaction: {
      mode: 'index',
      intersect: false,
    },
    scales: {
      y: {
        beginAtZero: true,
        grid: { color: 'rgba(255, 255, 255, 0.05)' },
        ticks: { color: 'var(--text-secondary)', callback: val => convertAndFormatCurrency(val) }
      },
      y1: {
        beginAtZero: true,
        position: "right",
        grid: { drawOnChartArea: false },
        ticks: { color: 'var(--text-secondary)' }
      },
      x: {
        grid: { display: false },
        ticks: { color: 'var(--text-secondary)' }
      }
    },
    plugins: {
      legend: { labels: { color: 'var(--text-primary)', font: { size: 11 } } }
    }
  };

  const yearlyChartData = {
    labels: yearLabels,
    datasets: [
      {
        type: "bar",
        label: `${t('annualEarnings')} (${symbol})`,
        data: yearlyData.earnings,
        backgroundColor: "rgba(255, 255, 255, 0.1)",
        borderColor: "rgba(255, 255, 255, 0.2)",
        borderWidth: 1,
        borderRadius: 4,
        yAxisID: "y"
      },
      {
        type: "line",
        label: t('growthRate'),
