import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowDownLeft, ArrowUpRight } from 'lucide-react';
import { useCurrency } from '../hooks/useCurrency';
import { useLanguage } from '../contexts/LanguageContext';

const generateSingleMockTransaction = () => {
  const isDeposit = Math.random() > 0.4;
  const amount = (Math.random() * 1000 + 10);
  const userId = Math.floor(Math.random() * 9000) + 1000;
  return {
    id: Date.now() + Math.random(),
    userId,
    amount,
    isDeposit
  };
};

export const LiveTransactions = () => {
  const { formatCurrency } = useCurrency();
  const { t } = useLanguage();
  const [transactions, setTransactions] = useState(() => {
    return Array.from({ length: 4 }).map(() => generateSingleMockTransaction());
  });

  useEffect(() => {
    const interval = setInterval(() => {
      setTransactions(prev => {
        const next = [...prev];
        next.shift(); // Remove oldest (top)
        next.push(generateSingleMockTransaction()); // Add newest (bottom)
        return next;
      });
    }, 2500); // Slide a new one every 2.5s

    return () => clearInterval(interval);
  }, []);

  return (
    <div style={{ background: 'var(--bg-panel)', padding: '14px 16px', borderRadius: '12px', border: '1px solid var(--border)' }}>
      <div style={{ fontSize: '11px', fontWeight: 600, color: 'var(--text-secondary)', marginBottom: '12px', display: 'flex', alignItems: 'center', gap: '6px' }}>
        <span style={{ width: '6px', height: '6px', borderRadius: '50%', background: 'var(--success)', display: 'inline-block', boxShadow: '0 0 4px var(--success)' }} />
        {t('livePlatformActivity')}
      </div>

      <div style={{ height: '140px', overflow: 'hidden', position: 'relative' }}>
        {/* Top gradient mask for fading out */}
        <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: '20px', background: 'linear-gradient(to bottom, var(--bg-panel), transparent)', zIndex: 1 }} />
        
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <AnimatePresence mode="popLayout">
            {transactions.map((tx) => (
              <motion.div
                key={tx.id}
                layout
                initial={{ opacity: 0, y: 20, scale: 0.95 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, y: -20, scale: 0.95 }}
                transition={{ duration: 0.4, ease: "easeOut" }}
                style={{ 
                  background: 'var(--bg-dark)', 
                  padding: '8px 12px', 
                  borderRadius: '8px', 
                  display: 'flex', 
                  justifyContent: 'space-between',
                  alignItems: 'center', 
                  border: '1px solid rgba(255,255,255,0.05)',
                  fontSize: '11px' 
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <div style={{ 
                    width: '24px', height: '24px', borderRadius: '50%', 
                    background: tx.isDeposit ? 'rgba(46, 204, 113, 0.1)' : 'rgba(231, 76, 60, 0.1)', 
                    display: 'flex', alignItems: 'center', justifyContent: 'center' 
                  }}>
                    {tx.isDeposit ? <ArrowDownLeft size={14} color="var(--success)" /> : <ArrowUpRight size={14} color="var(--danger)" />}
                  </div>
                  <span style={{ color: 'var(--text-primary)', fontWeight: 500 }}>
                    {t('userDesc')} ***{tx.userId}
                  </span>
                </div>
                <div style={{ 
                  color: tx.isDeposit ? 'var(--success)' : 'var(--text-primary)', 
                  fontWeight: 600 
                }}>
                  {tx.isDeposit ? '+' : '-'}{formatCurrency(tx.amount)}
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>

        {/* Bottom gradient mask for fading in */}
        <div style={{ position: 'absolute', bottom: 0, left: 0, right: 0, height: '20px', background: 'linear-gradient(to top, var(--bg-panel), transparent)', zIndex: 1 }} />
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { WifiOff, Loader } from 'lucide-react';

export const NetworkOverlay = () => {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [reconnecting, setReconnecting] = useState(false);

  useEffect(() => {
    const handleOnline = () => {
      setReconnecting(true);
      setTimeout(() => {
        setIsOnline(true);
        setReconnecting(false);
        window.location.reload(); 
      }, 1500);
    };

    const handleOffline = () => {
      setIsOnline(false);
      setReconnecting(false);
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  return (
    <AnimatePresence>
      {!isOnline && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(15, 23, 42, 0.95)',
            backdropFilter: 'blur(10px)',
            zIndex: 9999,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            color: '#fff',
            padding: '20px'
          }}
        >
          <motion.div
            initial={{ scale: 0.8, y: 20 }}
            animate={{ scale: 1, y: 0 }}
            transition={{ type: 'spring', damping: 15 }}
            style={{
              background: 'var(--bg-panel)',
              padding: '40px',
              borderRadius: '24px',
              border: '1px solid var(--border)',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              boxShadow: '0 20px 40px rgba(0,0,0,0.4)',
              textAlign: 'center',
              maxWidth: '320px',
              width: '100%'
            }}
          >
            {reconnecting ? (
              <>
                <div style={{
                  width: '64px',
                  height: '64px',
                  borderRadius: '50%',
                  background: 'rgba(16, 185, 129, 0.1)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  marginBottom: '20px'
                }}>
                  <motion.div animate={{ rotate: 360 }} transition={{ repeat: Infinity, duration: 1, ease: "linear" }}>
                    <Loader size={32} color="var(--success)" />
                  </motion.div>
                </div>
                <h2 style={{ margin: '0 0 10px 0', fontSize: '20px', color: 'var(--success)' }}>Back Online!</h2>
                <p style={{ margin: 0, color: 'var(--text-muted)', fontSize: '14px' }}>Reconnecting and reloading data...</p>
              </>
            ) : (
              <>
                <div style={{
                  width: '64px',
                  height: '64px',
                  borderRadius: '50%',
                  background: 'rgba(239, 68, 68, 0.1)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  marginBottom: '20px'
                }}>
                  <WifiOff size={32} color="var(--danger)" />
                </div>
                <h2 style={{ margin: '0 0 10px 0', fontSize: '20px', color: 'var(--danger)' }}>Connection Lost</h2>
                <p style={{ margin: 0, color: 'var(--text-muted)', fontSize: '14px', lineHeight: '1.5' }}>
                  It seems you are offline. Please check your internet connection. We'll automatically reconnect when the network is available.
                </p>
                <div style={{ marginTop: '24px', display: 'flex', gap: '8px', alignItems: 'center' }}>
                  <motion.div animate={{ opacity: [1, 0.3, 1] }} transition={{ repeat: Infinity, duration: 1.5 }} style={{ width: '8px', height: '8px', borderRadius: '50%', background: 'var(--danger)' }} />
                  <span style={{ fontSize: '12px', color: 'var(--danger)', fontWeight: 600 }}>Waiting for network...</span>
                </div>
              </>
            )}
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

