import React, { createContext, useContext, useEffect, useState } from 'react';
import { auth, db } from '../firebase';
import { onAuthStateChanged, signInWithEmailAndPassword, createUserWithEmailAndPassword, signOut, RecaptchaVerifier, signInWithPhoneNumber } from 'firebase/auth';
import { doc, onSnapshot, setDoc, getDoc, updateDoc } from 'firebase/firestore';
import toast from 'react-hot-toast';

const AuthContext = createContext();

export function useAuth() {
  return useContext(AuthContext);
}

export function AuthProvider({ children }) {
  const [currentUser, setCurrentUser] = useState(null);
  const [balance, setBalance] = useState(0);
  const [qtxBalance, setQtxBalance] = useState(0);
  const [miningBalance, setMiningBalance] = useState(0);
  const [investmentBalance, setInvestmentBalance] = useState(0);
  const [welcomeBonus, setWelcomeBonus] = useState(0);
  const [userData, setUserData] = useState({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setCurrentUser(user);
      
      if (user) {
        // Listen to live balance
        const unsubDoc = onSnapshot(doc(db, 'users', user.uid), (docSnap) => {
          if (docSnap.exists()) {
            const data = docSnap.data();
            
            // Concurrent login check
            const localSession = localStorage.getItem('qtx coin_session');
            if (data.currentSessionToken && localSession && data.currentSessionToken !== localSession) {
              signOut(auth);
              localStorage.removeItem('qtx coin_session');
              toast.error('You have been logged out because your account was accessed from another device or browser.', { duration: 6000 });
              return;
            }

            setBalance(data.balance || 0);
            setQtxBalance(data.qtxBalance || 0);
            setMiningBalance(data.miningBalance || 0);
            setInvestmentBalance(data.investmentBalance || 0);
            setWelcomeBonus(data.welcomeBonus || 0);
            setUserData({
              photoURL: data.photoURL || null,
              lastPhotoUpdate: data.lastPhotoUpdate || null,
              country: data.country || 'Global',
              createdAt: data.createdAt || null,
              loginHistory: data.loginHistory || [],
              activatedBots: data.activatedBots || [],
              activatedCrypto: data.activatedCrypto || [],
              claimedVideos: data.claimedVideos || {},
              welcomeBonus: data.welcomeBonus !== undefined ? data.welcomeBonus : (15000 / 1700)
            });
          }
        });
        setLoading(false);
        return unsubDoc;
      } else {
        setBalance(0);
        setQtxBalance(0);
        setMiningBalance(0);
        setInvestmentBalance(0);
        setWelcomeBonus(0);
        setLoading(false);
      }
    });

    return unsubscribe;
  }, []);

  const generateReferralCode = () => {
    return Math.random().toString(36).substring(2, 8).toUpperCase();
  };

  const signup = async (email, password, country = 'Global', referredByCode = null) => {
    localStorage.removeItem('qtx coin_session');
    const userCredential = await createUserWithEmailAndPassword(auth, email, password);
    const sessionToken = Date.now().toString() + Math.random().toString(36).substring(2);
    
    // Create initial user document
    await setDoc(doc(db, 'users', userCredential.user.uid), {
      email: email,
      phone: null,
      balance: 0,
      welcomeBonus: 50,
      qtxBalance: 0,
      miningBalance: 0,
      investmentBalance: 0,
      country: country,
      referralCode: generateReferralCode(),
      referredByCode: referredByCode,
      firstDepositRewarded: false,
      welcomeBonus: 15000 / 1700,
      createdAt: new Date().toISOString(),
      currentSessionToken: sessionToken
    });
    localStorage.setItem('qtx coin_session', sessionToken);
    return userCredential;
  };

  const setupRecaptcha = (containerId) => {
    if (!window.recaptchaVerifier) {
      window.recaptchaVerifier = new RecaptchaVerifier(auth, containerId, {
        size: 'invisible',
        callback: (response) => {
          // reCAPTCHA solved
        }
      });
    }
    return window.recaptchaVerifier;
  };

  const sendOTP = async (phoneNumber, appVerifier) => {
    try {
      const confirmationResult = await signInWithPhoneNumber(auth, phoneNumber, appVerifier);
      window.confirmationResult = confirmationResult;
      return confirmationResult;
    } catch (error) {
      console.error('Error sending OTP', error);
      throw error;
    }
  };

  const verifyOTP = async (code, country = 'Global', referredByCode = null) => {
    try {
      const confirmationResult = window.confirmationResult;
      const result = await confirmationResult.confirm(code);
      const user = result.user;

      localStorage.removeItem('qtx coin_session');
      const sessionToken = Date.now().toString() + Math.random().toString(36).substring(2);

      // Check if user document exists
      const userRef = doc(db, 'users', user.uid);
      const userSnap = await getDoc(userRef);

      if (!userSnap.exists()) {
        // Initialize new phone user
        await setDoc(userRef, {
          email: null,
          phone: user.phoneNumber,
          balance: 0,
          welcomeBonus: 50,
          qtxBalance: 0,
          miningBalance: 0,
          investmentBalance: 0,
          country: country,
          referralCode: generateReferralCode(),
          referredByCode: referredByCode,
          firstDepositRewarded: false,
          welcomeBonus: 15000 / 1700,
          createdAt: new Date().toISOString(),
          currentSessionToken: sessionToken
        });
      } else {
        await updateDoc(userRef, { currentSessionToken: sessionToken });
        // Also log history
        await logLoginHistory(user.uid, userSnap);
      }
      localStorage.setItem('qtx coin_session', sessionToken);
      return result;
    } catch (error) {
      console.error('Error verifying OTP', error);
      throw error;
    }
  };

  const logLoginHistory = async (uid, userSnap) => {
    let ip = 'Unknown';
    let country = 'Unknown';
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 3000);
      const res = await fetch('https://get.geojs.io/v1/ip/geo.json', { signal: controller.signal });
      clearTimeout(timeoutId);
      const data = await res.json();
      ip = data.ip || 'Unknown';
      country = data.country || 'Unknown';
    } catch (e) {
      console.log("Could not fetch IP", e);
    }

    if (userSnap.exists()) {
      const currentHistory = userSnap.data().loginHistory || [];
      const currentNotifications = userSnap.data().notifications || [];
      
      const newEntry = {
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        ip,
        country,
        device: navigator.userAgent
      };
      const updatedHistory = [newEntry, ...currentHistory].slice(0, 10);
      
      const newNotification = {
        id: Date.now().toString() + '_notif',
        type: 'security',
        title: 'New Login Detected',
        message: `Account accessed from ${ip} (${country}). Device: ${navigator.userAgent.substring(0, 30)}...`,
        timestamp: new Date().toISOString(),
        read: false
      };
      const updatedNotifications = [newNotification, ...currentNotifications];
      
      await updateDoc(userSnap.ref, { 
        loginHistory: updatedHistory,
        notifications: updatedNotifications
      });
    }
  };

  const login = async (email, password) => {
    localStorage.removeItem('qtx coin_session');
    const userCredential = await signInWithEmailAndPassword(auth, email, password);
    const sessionToken = Date.now().toString() + Math.random().toString(36).substring(2);
    
    // Log login history to the main user doc array to avoid subcollection rule issues
    try {
      const userRef = doc(db, 'users', userCredential.user.uid);
      const userSnap = await getDoc(userRef);
      if (userSnap.exists()) {
        await updateDoc(userRef, { currentSessionToken: sessionToken });
        await logLoginHistory(userCredential.user.uid, userSnap);
      }
    } catch (err) {
      console.error("Error saving login history:", err);
    }
    
    localStorage.setItem('qtx coin_session', sessionToken);
    return userCredential;
  };

  const logout = () => {
    localStorage.removeItem('qtx coin_session');
    return signOut(auth);
  };

  const buyQTX = async (amountUSD, currentPrice) => {
    if (!currentUser) return false;
    const userRef = doc(db, 'users', currentUser.uid);
    try {
      const qtxAmount = amountUSD / currentPrice;
      const newNotif = {
        id: Date.now().toString() + '_buy',
        type: 'transaction',
        title: 'Bought QTX',
        message: `Purchased ${qtxAmount.toFixed(4)} QTX for $${amountUSD.toFixed(2)}`,
        timestamp: new Date().toISOString(),
        read: false
      };
      const updatedNotifs = [newNotif, ...(userData.notifications || [])].slice(0, 30);
      
      await updateDoc(userRef, {
        balance: balance - amountUSD,
        qtxBalance: qtxBalance + qtxAmount,
        notifications: updatedNotifs
      });
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  };

  const sellQTX = async (amountQTX, currentPrice) => {
    if (!currentUser) return false;
    const userRef = doc(db, 'users', currentUser.uid);
    try {
      const usdAmount = amountQTX * currentPrice;
      const newNotif = {
        id: Date.now().toString() + '_sell',
        type: 'transaction',
        title: 'Sold QTX',
        message: `Sold ${amountQTX.toFixed(4)} QTX for $${usdAmount.toFixed(2)}`,
        timestamp: new Date().toISOString(),
        read: false
      };
      const updatedNotifs = [newNotif, ...(userData.notifications || [])].slice(0, 30);
      
      await updateDoc(userRef, {
        balance: balance + usdAmount,
        qtxBalance: qtxBalance - amountQTX,
        notifications: updatedNotifs
      });
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  };

  const isAdmin = currentUser && currentUser.email === 'mackocks588@gmail.com';

  const value = {
    currentUser,
    isAdmin,
    balance,
    qtxBalance,
    miningBalance,
    investmentBalance,
    welcomeBonus,
    userData,
    signup,
    setupRecaptcha,
    sendOTP,
    verifyOTP,
    login,
    logout,
    buyQTX,
    sellQTX
  };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
}

import React, { useRef, useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { useAuth } from '../contexts/AuthContext';
import { useLanguage } from '../contexts/LanguageContext';
import { CreditCard, Wallet, Copy, Camera, CalendarDays, Globe } from 'lucide-react';
import { Link } from 'react-router-dom';
import toast from 'react-hot-toast';
import { db, auth } from '../firebase';
import { doc, updateDoc } from 'firebase/firestore';
import { signInWithEmailAndPassword } from 'firebase/auth';
import { ShieldCheck, Bell, ChevronLeft, HelpCircle, LogOut, Gift, Fingerprint, Smartphone, X, Eye, EyeOff } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { NativeBiometric } from '@capgo/capacitor-native-biometric';
import { PushNotifications } from '@capacitor/push-notifications';

const COUNTRIES = [
  { code: 'KE', name: 'Kenya' },
  { code: 'MZ', name: 'Mozambique' },
  { code: 'TZ', name: 'Tanzania' },
  { code: 'UG', name: 'Uganda' },
  { code: 'BW', name: 'Botswana' },
  { code: 'CD', name: 'Congo (DRC)' },
  { code: 'ZM', name: 'Zambia' },
  { code: 'BI', name: 'Burundi' },
  { code: 'GH', name: 'Ghana' },
  { code: 'UN', name: 'Global/Other' }
];

export const Account = () => {
  const { currentUser, userData, logout } = useAuth();
  const { t } = useLanguage();
  const navigate = useNavigate();
  const fileInputRef = useRef(null);
  const [uploading, setUploading] = useState(false);
  const [biometricEnabled, setBiometricEnabled] = useState(false);
  const [pushEnabled, setPushEnabled] = useState(false);
  const [showBiometricModal, setShowBiometricModal] = useState(false);
  const [biometricPassword, setBiometricPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  useEffect(() => {
    const checkSettings = async () => {
      try {
        const bioRes = await NativeBiometric.isCredentialsSaved({ server: 'qtx coin_auth' });
        setBiometricEnabled(bioRes.isSaved);
      } catch (e) {
        console.log('Biometric check failed', e);
      }
      
      try {
        const pushRes = await PushNotifications.checkPermissions();
        setPushEnabled(pushRes.receive === 'granted');
      } catch (e) {
        console.log('Push check failed', e);
      }
    };
    checkSettings();
  }, []);

  const handlePushToggle = async () => {
    try {
      if (pushEnabled) {
        toast('To disable notifications, please go to your device Settings.', { icon: 'ℹ️' });
        return;
      }
      
      const res = await PushNotifications.requestPermissions();
      if (res.receive === 'granted') {
        await PushNotifications.register();
        setPushEnabled(true);
        toast.success(t('successPushEnabled'));
      } else {
        toast.error(t('errPermissionDenied'));
      }
    } catch (e) {
      console.log('Push toggle error', e);
      toast.error(t('errCouldNotChangePush'));
    }
  };

  const handleBiometricToggle = async () => {
    if (biometricEnabled) {
      try {
        await NativeBiometric.deleteCredentials({ server: 'qtx coin_auth' });
        setBiometricEnabled(false);
        toast.success(t('successBiometricDisabled'));
      } catch (e) {
        toast.error(t('errFailedDisableBiometrics'));
      }
    } else {
      setBiometricPassword('');
      setShowPassword(false);
      setShowBiometricModal(true);
    }
  };

  const confirmEnableBiometric = async () => {
    if (!biometricPassword) return toast.error(t('errEnterPassword'));
    
    const loadingToast = toast.loading('Verifying password...');
    try {
      await signInWithEmailAndPassword(auth, currentUser?.email, biometricPassword);
      toast.dismiss(loadingToast);
    } catch (err) {
      toast.dismiss(loadingToast);
      return toast.error(t('errIncorrectPassword'));
    }

    try {
      await NativeBiometric.setCredentials({
        username: currentUser?.email || 'user',
        password: biometricPassword,
        server: 'qtx coin_auth'
      });
      setBiometricEnabled(true);
      setShowBiometricModal(false);
      toast.success(t('successBiometricEnabled'));
    } catch (e) {
      toast.error(t('errFailedEnableBiometrics'));
    }
  };

  const handleCopyUid = () => {
    if (currentUser?.uid) {
      navigator.clipboard.writeText(currentUser.uid);
      toast.success(t('uidCopied'));
    }
  };

  const handleAvatarClick = () => {
    if (uploading) return;
    
    // Check 30-day cooldown
    if (userData?.lastPhotoUpdate) {
      const lastUpdate = new Date(userData.lastPhotoUpdate).getTime();
      const thirtyDaysMs = 30 * 24 * 60 * 60 * 1000;
      const now = Date.now();
      
      if (now - lastUpdate < thirtyDaysMs) {
        const daysLeft = Math.ceil((thirtyDaysMs - (now - lastUpdate)) / (24 * 60 * 60 * 1000));
        return toast.error(t('errPhotoCooldown').replace('{n}', daysLeft));
      }
    }
    
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Validate file type
    if (!file.type.startsWith('image/')) {
      return toast.error(t('errSelectImageFile'));
    }

    // Validate size (max 5MB)
    if (file.size > 5 * 1024 * 1024) {
      return toast.error(t('errImageTooLarge'));
    }

    setUploading(true);
    const toastId = toast.loading('Processing profile picture...');

    try {
      // Compress image and convert to Base64 to bypass Firebase Storage restrictions
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = async () => {
          const canvas = document.createElement('canvas');
          const MAX_WIDTH = 200;
          const MAX_HEIGHT = 200;
          let width = img.width;
          let height = img.height;

          if (width > height) {
            if (width > MAX_WIDTH) {
              height *= MAX_WIDTH / width;
              width = MAX_WIDTH;
            }
          } else {
            if (height > MAX_HEIGHT) {
              width *= MAX_HEIGHT / height;
              height = MAX_HEIGHT;
            }
          }

          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0, width, height);

          // Get highly compressed base64 string
          const base64DataUrl = canvas.toDataURL('image/jpeg', 0.7);

          try {
            await updateDoc(doc(db, 'users', currentUser.uid), {
              photoURL: base64DataUrl,
              lastPhotoUpdate: new Date().toISOString()
            });
            toast.success(t('successProfileUpdated'), { id: toastId });
          } catch (err) {
            toast.error('Error saving image: ' + err.message, { id: toastId });
          } finally {
            setUploading(false);
          }
        };
        img.src = event.target.result;
      };
      reader.readAsDataURL(file);
    } catch (error) {
      toast.error('Processing failed: ' + error.message, { id: toastId });
      setUploading(false);
    }
  };

  return (
    <motion.div 
      className="page-content"
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      transition={{ duration: 0.3 }}
      style={{ padding: '16px' }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '16px' }}>
        <button 
          onClick={() => navigate(-1)}
          style={{ background: 'var(--bg-panel)', border: '1px solid var(--border)', borderRadius: '8px', padding: '6px', color: '#fff', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
        >
          <ChevronLeft size={20} />
        </button>
        <h2 className="mb-0" style={{ fontSize: '18px', margin: 0 }}>{t('myAccount')}</h2>
      </div>
      
      <div className="panel mb-4" style={{ padding: '16px', display: 'flex', flexDirection: 'column', gap: '16px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
          
          <div style={{ position: 'relative' }}>
            <div 
              onClick={handleAvatarClick}
              style={{ 
                width: '64px', height: '64px', borderRadius: '50%', 
                backgroundColor: 'var(--primary-glow)', border: '2px solid var(--primary)',
                display: 'flex', alignItems: 'center', justifyContent: 'center', 
                fontSize: '1.5rem', color: 'var(--primary)', fontWeight: 'bold',
                cursor: uploading ? 'wait' : 'pointer', overflow: 'hidden',
                position: 'relative'
              }}
            >
              {userData?.photoURL ? (
                <img src={userData.photoURL} alt="Profile" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
              ) : (
                currentUser?.email?.charAt(0).toUpperCase()
              )}
              
              <div style={{
                position: 'absolute', bottom: 0, left: 0, right: 0, background: 'rgba(0,0,0,0.6)', 
                height: '24px', display: 'flex', justifyContent: 'center', alignItems: 'center'
              }}>
                <Camera size={12} color="#fff" />
              </div>
            </div>
            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={handleFileChange} 
              accept="image/*" 
              style={{ display: 'none' }} 
            />
          </div>

          <div style={{ flex: 1, overflow: 'hidden' }}>
            <h3 style={{ margin: '0 0 4px 0', fontSize: '16px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
              {currentUser?.email || 'Loading...'}
            </h3>
            <div style={{ display: 'flex', alignItems: 'center', gap: '6px', background: 'rgba(255,255,255,0.05)', padding: '4px 8px', borderRadius: '4px', width: 'fit-content' }}>
              <span className="text-muted" style={{ fontSize: '11px', fontFamily: 'monospace' }}>
                UID: {currentUser?.uid ? currentUser.uid.slice(0, 10) : '...'}...
              </span>
              <button onClick={handleCopyUid} style={{ display: 'flex', alignItems: 'center', color: 'var(--primary)', padding: '2px' }}>
                <Copy size={12} />
              </button>
            </div>
          </div>
        </div>
        
        {/* Additional Details */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', background: 'var(--bg-dark)', padding: '12px', borderRadius: '8px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <Globe size={14} color="var(--text-secondary)" />
            <span style={{ fontSize: '12px', color: 'var(--text-secondary)', display: 'flex', alignItems: 'center', gap: '6px' }}>
              {t('region')} 
              {userData?.country && (() => {
                const countryObj = COUNTRIES.find(c => c.name === userData.country);
                return countryObj ? (
                  <>
                    <img src={`https://flagcdn.com/w20/${countryObj.code.toLowerCase()}.png`} alt="flag" style={{ width: '16px', borderRadius: '2px' }} />
                    <strong style={{ color: 'var(--text-primary)' }}>{userData.country}</strong>
                  </>
                ) : <strong style={{ color: 'var(--text-primary)' }}>{userData.country}</strong>;
              })()}
            </span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <CalendarDays size={14} color="var(--text-secondary)" />
            <span style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>{t('joined')} <strong style={{ color: 'var(--text-primary)' }}>{userData?.createdAt ? new Date(userData.createdAt).toLocaleDateString() : 'N/A'}</strong></span>
          </div>
        </div>

        {/* Settings & Security */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', background: 'var(--bg-dark)', padding: '8px', borderRadius: '8px' }}>
          <Link to="/security" style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '10px', textDecoration: 'none', color: 'var(--text-primary)', borderRadius: '6px', transition: 'var(--transition)' }} className="hover:bg-panel-hover">
            <div style={{ width: '28px', height: '28px', borderRadius: '6px', background: 'rgba(212, 175, 55, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <ShieldCheck size={14} color="var(--primary)" />
            </div>
            <span style={{ fontSize: '13px', flex: 1, fontWeight: 500 }}>{t('securityCenter')}</span>
            <span style={{ color: 'var(--text-muted)', fontSize: '16px' }}>›</span>
          </Link>
          
          <Link to="/notifications" style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '10px', textDecoration: 'none', color: 'var(--text-primary)', borderRadius: '6px', transition: 'var(--transition)' }} className="hover:bg-panel-hover">
            <div style={{ width: '28px', height: '28px', borderRadius: '6px', background: 'rgba(212, 175, 55, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center', position: 'relative' }}>
              <Bell size={14} color="var(--primary)" />
              {userData?.notifications?.some(n => !n.read) && (
                <div style={{ position: 'absolute', top: '6px', right: '6px', width: '6px', height: '6px', background: 'red', borderRadius: '50%' }} />
              )}
            </div>
            <span style={{ fontSize: '13px', flex: 1, fontWeight: 500 }}>{t('notifications')}</span>
            <span style={{ color: 'var(--text-muted)', fontSize: '16px' }}>›</span>
          </Link>

          <Link to="/event" style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '10px', textDecoration: 'none', color: 'var(--text-primary)', borderRadius: '6px', transition: 'var(--transition)' }} className="hover:bg-panel-hover">
            <div style={{ width: '28px', height: '28px', borderRadius: '6px', background: 'rgba(212, 175, 55, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <Gift size={14} color="#f472b6" />
            </div>
            <span style={{ fontSize: '13px', flex: 1, fontWeight: 500 }}>{t('eventCenter')}</span>
            <span style={{ color: 'var(--text-muted)', fontSize: '16px' }}>›</span>
          </Link>

          <Link to="/spin" style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '10px', textDecoration: 'none', color: 'var(--text-primary)', borderRadius: '6px', transition: 'var(--transition)' }} className="hover:bg-panel-hover">
            <div style={{ width: '28px', height: '28px', borderRadius: '6px', background: 'rgba(212, 175, 55, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <img src="/images/spin_icon.png" alt="spin" style={{ width: '18px', height: '18px' }} />
            </div>
            <span style={{ fontSize: '13px', flex: 1, fontWeight: 500, color: 'var(--warning)' }}>{t('luckySpin')}</span>
            <span style={{ color: 'var(--text-muted)', fontSize: '16px' }}>›</span>
          </Link>
          
          <Link to="/faq" style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '10px', textDecoration: 'none', color: 'var(--text-primary)', borderRadius: '6px', transition: 'var(--transition)' }} className="hover:bg-panel-hover">
            <div style={{ width: '28px', height: '28px', borderRadius: '6px', background: 'rgba(212, 175, 55, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <HelpCircle size={14} color="var(--primary)" />
            </div>
            <span style={{ fontSize: '13px', flex: 1, fontWeight: 500 }}>{t('faqSupport')}</span>
            <span style={{ color: 'var(--text-muted)', fontSize: '16px' }}>›</span>
          </Link>
        </div>

        {/* Device Settings */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', background: 'var(--bg-dark)', padding: '12px', borderRadius: '8px' }}>
          <h4 style={{ margin: '0 0 8px 0', fontSize: '13px', color: 'var(--text-secondary)' }}>{t('deviceSettings')}</h4>
          
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '8px 0' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
              <div style={{ width: '28px', height: '28px', borderRadius: '6px', background: 'rgba(212, 175, 55, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Fingerprint size={14} color="var(--primary)" />
              </div>
              <span style={{ fontSize: '13px', fontWeight: 500, color: 'var(--text-primary)' }}>{t('biometricLogin')}</span>
            </div>
            <div 
              onClick={handleBiometricToggle}
              style={{ width: '40px', height: '22px', background: biometricEnabled ? 'var(--primary)' : 'var(--border)', borderRadius: '11px', position: 'relative', cursor: 'pointer', transition: 'var(--transition)' }}
            >
              <div style={{ position: 'absolute', top: '2px', left: biometricEnabled ? '20px' : '2px', width: '18px', height: '18px', background: '#fff', borderRadius: '50%', transition: 'all 0.3s ease' }} />
            </div>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '8px 0', borderTop: '1px solid var(--border)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
              <div style={{ width: '28px', height: '28px', borderRadius: '6px', background: 'rgba(212, 175, 55, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Smartphone size={14} color="var(--primary)" />
              </div>
              <span style={{ fontSize: '13px', fontWeight: 500, color: 'var(--text-primary)' }}>{t('pushNotifications')}</span>
            </div>
            <div 
              onClick={handlePushToggle}
              style={{ width: '40px', height: '22px', background: pushEnabled ? 'var(--primary)' : 'var(--border)', borderRadius: '11px', position: 'relative', cursor: 'pointer', transition: 'var(--transition)' }}
            >
              <div style={{ position: 'absolute', top: '2px', left: pushEnabled ? '20px' : '2px', width: '18px', height: '18px', background: '#fff', borderRadius: '50%', transition: 'all 0.3s ease' }} />
            </div>
          </div>
        </div>
        
        {/* Top Action Bar */}
        <div style={{ display: 'flex', gap: '12px', borderTop: '1px solid var(--border)', paddingTop: '16px' }}>
          <Link to="/bind-account" style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px', padding: '10px', background: 'var(--bg-dark)', borderRadius: 'var(--radius-md)', color: 'var(--text-primary)', textDecoration: 'none', border: '1px solid var(--border)' }} className="hover:border-primary">
            <CreditCard size={16} color="var(--primary)" />
            <span style={{ fontWeight: 500, fontSize: '12px' }}>{t('bindAccount')}</span>
          </Link>
          <Link to="/wallet" style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px', padding: '10px', background: 'var(--bg-dark)', borderRadius: 'var(--radius-md)', color: 'var(--text-primary)', textDecoration: 'none', border: '1px solid var(--border)' }} className="hover:border-primary">
            <Wallet size={16} color="var(--primary)" />
            <span style={{ fontWeight: 500, fontSize: '12px' }}>{t('deposit')}</span>
          </Link>
        </div>

        {/* App Download Button */}
        <a 
          href="/QTXCoin1.apk" 
          download
          style={{ width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px', padding: '12px', background: 'linear-gradient(135deg, var(--primary), #0ea5e9)', border: 'none', borderRadius: '8px', color: '#fff', cursor: 'pointer', marginTop: '16px', textDecoration: 'none', boxShadow: '0 4px 15px rgba(56, 189, 248, 0.3)' }}
        >
          <Smartphone size={18} />
          <span style={{ fontWeight: 700, fontSize: '14px', letterSpacing: '0.3px' }}>Download Our Android App</span>
        </a>

        {/* Logout Button */}
        <button 
          onClick={async () => {
            try {
              await logout();
              navigate('/login');
            } catch (err) {
              toast.error(t('errFailedLogout'));
            }
          }}
          style={{ width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px', padding: '12px', background: 'rgba(239, 68, 68, 0.1)', border: '1px solid rgba(239, 68, 68, 0.3)', borderRadius: '8px', color: 'var(--danger)', cursor: 'pointer', marginTop: '8px', transition: 'var(--transition)' }}
        >
          <LogOut size={16} />
          <span style={{ fontWeight: 600, fontSize: '13px' }}>{t('signOut')}</span>
        </button>
      </div>

      {/* Biometric Password Modal */}
      {showBiometricModal && (
        <div style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(0,0,0,0.8)', zIndex: 100, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '20px' }}>
          <motion.div 
            initial={{ scale: 0.9, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            style={{ background: 'var(--bg-panel)', width: '100%', maxWidth: '340px', borderRadius: '16px', overflow: 'hidden', border: '1px solid var(--border)' }}
          >
            <div style={{ padding: '20px', borderBottom: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <h3 style={{ margin: 0, fontSize: '16px', color: 'var(--text-primary)' }}>{t('enableBiometrics')}</h3>
              <button onClick={() => setShowBiometricModal(false)} style={{ background: 'none', border: 'none', color: 'var(--text-muted)', cursor: 'pointer' }}>
                <X size={20} />
              </button>
            </div>
            <div style={{ padding: '20px' }}>
              <p style={{ margin: '0 0 16px 0', fontSize: '13px', color: 'var(--text-secondary)', lineHeight: '1.5' }}>
                {t('biometricDesc')}
              </p>
              
              <div className="input-group" style={{ marginBottom: '20px' }}>
                <label className="input-label">{t('password')}</label>
                <div style={{ position: 'relative' }}>
                  <input 
                    type={showPassword ? "text" : "password"} 
                    className="input-field"
                    value={biometricPassword} 
                    onChange={e => setBiometricPassword(e.target.value)} 
                    placeholder="Enter your password"
                    style={{ width: '100%', paddingRight: '40px', boxSizing: 'border-box' }}
                  />
                  <button 
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    style={{ position: 'absolute', right: '10px', top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', padding: '4px' }}
                  >
                    {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
              </div>
              
              <button 
                onClick={confirmEnableBiometric}
                className="btn btn-primary" 
                style={{ width: '100%', padding: '12px', fontWeight: 600, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px' }}
              >
                <Fingerprint size={18} /> {t('enable')}
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </motion.div>
  );
};

