import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { db, functions } from '../firebase';
import { collectionGroup, collection, query, where, orderBy, getDocs, doc, updateDoc, increment, deleteDoc, getDoc } from 'firebase/firestore';
import { httpsCallable } from 'firebase/functions';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import { storage } from '../firebase';
import { useAuth } from '../contexts/AuthContext';
import { ShieldAlert, CheckCircle2, XCircle, Trash2, Copy, Send, Activity, Users, ArrowDownToLine, ArrowUpFromLine, LayoutDashboard, ChevronRight, Edit2, Save, X, Search, MessageSquare, Eye, Bell } from 'lucide-react';
import toast from 'react-hot-toast';
import { useNavigate } from 'react-router-dom';

export const Admin = () => {
  const { currentUser, isAdmin } = useAuth();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('dashboard');
  
  const [stats, setStats] = useState({ totalUsers: 0, totalDeposits: 0, totalWithdrawals: 0 });
  const [withdrawals, setWithdrawals] = useState([]);
  const [deposits, setDeposits] = useState([]);
  const [usersList, setUsersList] = useState([]);
  const [loading, setLoading] = useState(true);

  // Search state
  const [userSearchQuery, setUserSearchQuery] = useState('');
  const [depositSearchQuery, setDepositSearchQuery] = useState('');

  // Edit user state
  const [editingUser, setEditingUser] = useState(null);
  const [editForm, setEditForm] = useState({ balance: 0, miningBalance: 0 });

  // Follow-up state
  const [followUpModal, setFollowUpModal] = useState({ isOpen: false, transaction: null, history: [], note: '', notificationMsg: '', loading: false });

  // Push Notification state
  const [pushForm, setPushForm] = useState({ userId: 'all', title: '', body: '', loading: false });
  const [pushImageFile, setPushImageFile] = useState(null);

  // Binance Explore state
  const [binanceLoading, setBinanceLoading] = useState(false);
  const [allTxns, setAllTxns] = useState([]);
  const [allTxnsLoaded, setAllTxnsLoaded] = useState(false);
  const [txnSearchQuery, setTxnSearchQuery] = useState('');
  const [networkFilter, setNetworkFilter] = useState('all');

  const TRC20_ADDRESS = import.meta.env.VITE_USDT_ADDRESS || 'TBteWdQZAdWJzXCaa61dogDFVNH8pSA88J';
  const BSC_ADDRESS = import.meta.env.VITE_BSC_ADDRESS || '0x66922e6229f9501319aa4425f4cd53773fc66a91';

  const handleBinanceExplore = async () => {
    if (!binanceTxidSearch.trim()) return;
    setBinanceLoading(true);
    setBinanceResults([]);
    try {
      const q = query(collectionGroup(db, 'transactions'), where('txid', '==', binanceTxidSearch.trim()));
      const snapshot = await getDocs(q);
      const results = snapshot.docs.map(doc => {
        const userRef = doc.ref.parent.parent;
        return {
          id: doc.id,
          userId: userRef ? userRef.id : 'unknown',
          ref: doc.ref,
          ...doc.data()
        };
      });
      setBinanceResults(results);
    } catch (e) {
      console.error(e);
      toast.error('Failed to search TXID');
    }
    setBinanceLoading(false);
  };

  const handleAdminPush = async () => {
    if (!pushForm.title || !pushForm.body) {
      toast.error('Title and body are required');
      return;
    }
    setPushForm(prev => ({ ...prev, loading: true }));
    try {
      let imageUrl = null;
      if (pushImageFile) {
        const toastId = toast.loading('Uploading image...');
        const imageRef = ref(storage, `push_images/${Date.now()}_${pushImageFile.name}`);
        const snapshot = await uploadBytes(imageRef, pushImageFile);
        imageUrl = await getDownloadURL(snapshot.ref);
        toast.dismiss(toastId);
      }

      const sendPush = httpsCallable(functions, 'adminSendPushNotification');
      const result = await sendPush({ 
        userId: pushForm.userId, 
        title: pushForm.title, 
        body: pushForm.body,
        imageUrl: imageUrl 
      });
      
      if (result.data.success) {
        toast.success(`Push sent to ${result.data.sentCount} device(s)`);
        setPushForm({ userId: 'all', title: '', body: '', loading: false });
        setPushImageFile(null);
        // Reset file input element if needed
        const fileInput = document.getElementById('pushImageInput');
        if (fileInput) fileInput.value = '';
      } else {
        toast.error('Push dispatch returned false');
        setPushForm(prev => ({ ...prev, loading: false }));
      }
    } catch (error) {
      console.error(error);
      toast.error('Failed to send push notification');
      setPushForm(prev => ({ ...prev, loading: false }));
    }
  };

  useEffect(() => {
    if (isAdmin) {
      if (activeTab === 'dashboard') fetchStats();
      if (activeTab === 'withdrawals') fetchWithdrawals();
      if (activeTab === 'deposits') fetchDeposits();
      if (activeTab === 'users') fetchUsersList();
      if (activeTab === 'binance_explore' && !allTxnsLoaded) fetchAllTxns();
    }
  }, [isAdmin, activeTab]);

  const fetchAllTxns = async () => {
    setBinanceLoading(true);
    setAllTxns([]);
    try {
      const getBinanceFn = httpsCallable(functions, 'getBinanceDeposits', { timeout: 30000 });
      const result = await getBinanceFn();
      setAllTxns(result.data.deposits || []);
      setAllTxnsLoaded(true);
      toast.success(`Loaded ${result.data.deposits.length} Binance deposits`);
    } catch (e) {
      console.error(e);
      toast.error('Failed to fetch Binance deposits: ' + (e.message || 'Unknown error'));
    }
    setBinanceLoading(false);
  };

  const fetchStats = async () => {
    setLoading(true);
    try {
      const usersSnap = await getDocs(collection(db, 'users'));
      const depsSnap = await getDocs(query(collectionGroup(db, 'transactions'), where('type', '==', 'deposit')));
      const withsSnap = await getDocs(query(collectionGroup(db, 'transactions'), where('type', '==', 'withdrawal')));

      let tDeps = 0;
      depsSnap.forEach(d => { 
        if(d.data().status === 'SUCCESS' || d.data().status === 'success') {
          tDeps += (d.data().amount || d.data().expectedAmount || 0);
        }
      });
      
      let tWiths = 0;
      withsSnap.forEach(d => { 
        if(d.data().status === 'SUCCESS' || d.data().status === 'success') {
          tWiths += (d.data().amount || 0);
        }
      });

      setStats({ totalUsers: usersSnap.size, totalDeposits: tDeps, totalWithdrawals: tWiths });
    } catch (error) {
      console.error(error);
      toast.error('Failed to load stats');
    }
    setLoading(false);
  };

  const fetchUsersList = async () => {
    setLoading(true);
    try {
      const usersSnap = await getDocs(collection(db, 'users'));
      const data = usersSnap.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setUsersList(data);
    } catch (error) {
      toast.error('Failed to load users');
    }
    setLoading(false);
  };

  const fetchDeposits = async () => {
    setLoading(true);
    try {
      // First ensure we have users for cross-referencing emails
      let currentUsers = usersList;
      if (currentUsers.length === 0) {
        const usersSnap = await getDocs(collection(db, 'users'));
        currentUsers = usersSnap.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        setUsersList(currentUsers);
      }

      const q = query(
        collectionGroup(db, 'transactions'),
        where('type', '==', 'deposit'),
        orderBy('createdAt', 'desc')
      );
      const snapshot = await getDocs(q);
      const data = snapshot.docs.map(doc => {
        const userRef = doc.ref.parent.parent;
        const uid = userRef ? userRef.id : 'unknown';
        const userObj = currentUsers.find(u => u.id === uid);
        return {
          id: doc.id,
          userId: uid,
          email: userObj ? userObj.email : 'Unknown',
          ref: doc.ref,
          ...doc.data()
        };
      });
      setDeposits(data);
    } catch (error) {
      console.error(error);
      toast.error('Failed to load deposits');
    }
    setLoading(false);
  };

  const fetchWithdrawals = async () => {
    setLoading(true);
    try {
      const q = query(
        collectionGroup(db, 'transactions'),
        where('type', '==', 'withdrawal'),
        orderBy('createdAt', 'desc')
      );
      const snapshot = await getDocs(q);
      const data = snapshot.docs.map(doc => {
        const userRef = doc.ref.parent.parent;
        return {
          id: doc.id,
          userId: userRef ? userRef.id : 'unknown',
          ref: doc.ref,
          ...doc.data()
        };
      });
      setWithdrawals(data);
    } catch (error) {
      console.error("Failed to fetch withdrawals:", error);
      if (error.code === 'permission-denied') {
        toast.error('Admin rules error. Have you updated your Firestore Rules for collectionGroup?', { duration: 5000 });
      } else if (error.code === 'failed-precondition') {
        toast.error('Index building required. Check the console error for the index link.', { duration: 5000 });
      } else {
        toast.error('Error loading withdrawals');
      }
    }
    setLoading(false);
  };

  const handleCopy = (text) => {
    navigator.clipboard.writeText(text);
    toast.success('Copied to clipboard');
  };

  // User Handlers
  const handleEditClick = (user) => {
    setEditingUser(user);
    setEditForm({ balance: user.balance || 0, miningBalance: user.miningBalance || 0 });
  };

  const handleSaveUser = async () => {
    if (!editingUser) return;
    try {
      const userRef = doc(db, 'users', editingUser.id);
      await updateDoc(userRef, {
        balance: parseFloat(editForm.balance) || 0,
        miningBalance: parseFloat(editForm.miningBalance) || 0
      });
      setUsersList(prev => prev.map(u => 
        u.id === editingUser.id 
          ? { ...u, balance: parseFloat(editForm.balance) || 0, miningBalance: parseFloat(editForm.miningBalance) || 0 }
          : u
      ));
      toast.success('User updated successfully');
      setEditingUser(null);
    } catch (error) {
      toast.error('Failed to update user');
    }
  };

  // Follow Up Handlers
  const openFollowUp = async (transaction) => {
    setFollowUpModal({ isOpen: true, transaction, history: [], note: transaction.adminNote || '', notificationMsg: '', loading: true });
    try {
      const q = query(collection(db, 'users', transaction.userId, 'transactions'), orderBy('createdAt', 'desc'));
      const snap = await getDocs(q);
      const hist = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      setFollowUpModal(prev => ({ ...prev, history: hist, loading: false }));
    } catch (e) {
      console.error(e);
      setFollowUpModal(prev => ({ ...prev, loading: false }));
    }
  };

  const saveAdminNote = async () => {
    try {
      await updateDoc(followUpModal.transaction.ref, { adminNote: followUpModal.note });
      toast.success('Note saved securely');
      setDeposits(prev => prev.map(d => d.id === followUpModal.transaction.id ? { ...d, adminNote: followUpModal.note } : d));
    } catch (e) {
      toast.error('Failed to save note');
    }
  };

  const sendNotification = async () => {
    if (!followUpModal.notificationMsg) return;
    if (!followUpModal.transaction?.userId || followUpModal.transaction.userId === 'unknown') {
      toast.error('Cannot send notification: User ID is unknown');
      return;
    }
    
    try {
      const userRef = doc(db, 'users', followUpModal.transaction.userId);
      const uSnap = await getDoc(userRef);
      if(uSnap.exists()) {
        let notifs = uSnap.data().notifications;
        if (!Array.isArray(notifs)) {
          notifs = [];
        }
        
        const newNotif = {
          id: Date.now().toString(),
          type: 'system',
          title: 'Update regarding your transaction',
          message: followUpModal.notificationMsg,
          timestamp: new Date().toISOString(),
          read: false
        };
        await updateDoc(userRef, { notifications: [newNotif, ...notifs].slice(0, 30) });
        toast.success('Notification sent to user');
        setFollowUpModal(prev => ({ ...prev, notificationMsg: '' }));
      } else {
        toast.error('User document not found in database');
      }
    } catch (e) {
      console.error("Notification sending error:", e);
      toast.error(`Error: ${e.message}`);
    }
  };


  // Withdrawal Handlers
  const handleApproveWithdrawal = async (withdrawal) => {
    try {
      await updateDoc(withdrawal.ref, { status: 'SUCCESS' });
      toast.success('Withdrawal Approved');
      setWithdrawals(prev => prev.map(w => w.id === withdrawal.id ? { ...w, status: 'SUCCESS' } : w));
    } catch (error) {
      toast.error('Failed to approve');
    }
  };

  const handleRejectWithdrawal = async (withdrawal) => {
    const confirmReject = window.confirm('Are you sure you want to reject this and refund the user?');
    if (!confirmReject) return;
    try {
      await updateDoc(withdrawal.ref, { status: 'failed', failureReason: 'Rejected by Admin' });
      const userRef = doc(db, 'users', withdrawal.userId);
      await updateDoc(userRef, { balance: increment(withdrawal.amount) });
      toast.success('Rejected and refunded successfully');
      setWithdrawals(prev => prev.map(w => w.id === withdrawal.id ? { ...w, status: 'failed' } : w));
    } catch (error) {
      toast.error('Failed to reject');
    }
  };

  const handleDeleteWithdrawal = async (withdrawal) => {
    const confirmDelete = window.confirm('WARNING: This completely deletes the record. Proceed?');
    if (!confirmDelete) return;
    try {
      await deleteDoc(withdrawal.ref);
      toast.success('Record deleted');
      setWithdrawals(prev => prev.filter(w => w.id !== withdrawal.id));
    } catch (error) {
      toast.error('Failed to delete');
    }
  };

  // Deposit Handlers
  const handleApproveDeposit = async (deposit) => {
    try {
      // ── Detect Mozambique Mobile deposit by any available signal
      const isMZDeposit = 
        deposit.network === 'MozambiqueMobile' ||
        deposit.currency === 'MT' ||
        (deposit.txid && deposit.txid.startsWith('MZ-'));

      console.log('[Admin] Approving deposit:', { id: deposit.id, network: deposit.network, currency: deposit.currency, txid: deposit.txid, isMZDeposit });

      if (isMZDeposit) {
        const amountMT = deposit.expectedAmount || deposit.amount || 0;
        const approveMZ = httpsCallable(functions, 'approveMozambiqueDeposit');
        const result = await approveMZ({ userId: deposit.userId, transactionId: deposit.id, amountMZN: amountMT });
        console.log('[Admin] MZ approval result:', result.data);
        toast.success(`MWK Deposit Approved — ${amountMT.toLocaleString()} MWK → $${(amountMT / 1700).toFixed(2)} USD credited`);
        setDeposits(prev => prev.map(d => d.id === deposit.id ? { ...d, status: 'SUCCESS' } : d));
        return;
      }

      const amount = deposit.expectedAmount || deposit.amount || 0;
      await updateDoc(deposit.ref, { status: 'SUCCESS', amount: amount });
      const userRef = doc(db, 'users', deposit.userId);
      await updateDoc(userRef, { balance: increment(amount) });

      // ── 3-Tier Affiliate Commission ──────────────────────────────────────
      const TIERS = [
        { pct: 0.10, label: 'Level 1 (Direct) Commission' },
        { pct: 0.03, label: 'Level 2 Commission' },
        { pct: 0.01, label: 'Level 3 Commission' },
      ];
      let currentUid = deposit.userId;
      for (let tier = 0; tier < TIERS.length; tier++) {
        const currentDoc = await getDoc(doc(db, 'users', currentUid));
        if (!currentDoc.exists()) break;
        const referredByCode = currentDoc.data().referredByCode;
        if (!referredByCode) break;

        const refSnap = await getDocs(query(collection(db, 'users'), where('referralCode', '==', referredByCode)));
        if (refSnap.empty) break;

        const referrerDoc = refSnap.docs[0];
        const referrerId = referrerDoc.id;
        const commission = parseFloat((amount * TIERS[tier].pct).toFixed(2));

        await updateDoc(doc(db, 'users', referrerId), { balance: increment(commission) });

        const { addDoc } = await import('firebase/firestore');
        await addDoc(collection(db, 'users', referrerId, 'transactions'), {
          type: 'affiliate_reward',
          title: TIERS[tier].label,
          amount: commission,
          fromUid: currentUid,
          status: 'SUCCESS',
          createdAt: new Date().toISOString(),
        });

        currentUid = referrerId;
      }
      // ─────────────────────────────────────────────────────────────────────

      if (amount >= 1000) {
        await updateDoc(userRef, { spinChances: increment(1) });
        const userDoc = await getDoc(userRef);
        if (userDoc.exists() && userDoc.data().referredByCode) {
          const refSnap = await getDocs(query(collection(db, 'users'), where('referralCode', '==', userDoc.data().referredByCode)));
          if (!refSnap.empty) {
            await updateDoc(doc(db, 'users', refSnap.docs[0].id), { spinChances: increment(1) });
          }
        }
      }

      toast.success('Deposit Approved and Credited');
      setDeposits(prev => prev.map(d => d.id === deposit.id ? { ...d, status: 'SUCCESS', amount: amount } : d));
    } catch (error) {
      console.error(error);
      toast.error('Failed to approve deposit: ' + (error.message || ''));
    }
  };

  const handleRejectDeposit = async (deposit) => {
    const confirmReject = window.confirm('Are you sure you want to reject this deposit?');
    if (!confirmReject) return;
    try {
      await updateDoc(deposit.ref, { status: 'failed', failureReason: 'Rejected by Admin' });
      toast.success('Deposit Rejected');
      setDeposits(prev => prev.map(d => d.id === deposit.id ? { ...d, status: 'failed' } : d));
    } catch (error) {
      toast.error('Failed to reject deposit');
    }
  };


  if (!currentUser) return <div className="p-4 text-center">Please login</div>;
  
  if (!isAdmin) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100vh', padding: '20px', textAlign: 'center' }}>
        <ShieldAlert size={64} color="var(--danger)" style={{ marginBottom: '16px' }} />
        <h2 style={{ color: 'var(--text-primary)', marginBottom: '8px' }}>Access Denied</h2>
        <p style={{ color: 'var(--text-muted)' }}>You do not have administrative privileges to view this page.</p>
        <button onClick={() => navigate('/')} className="btn btn-primary" style={{ marginTop: '20px' }}>
          Return to Dashboard
        </button>
      </div>
    );
  }

  const TabButton = ({ id, icon: Icon, label }) => (
    <button
      onClick={() => setActiveTab(id)}
      style={{
        display: 'flex', alignItems: 'center', gap: '12px', width: '100%', padding: '12px 16px',
        background: activeTab === id ? 'rgba(59, 130, 246, 0.1)' : 'transparent',
        border: 'none',
        borderLeft: activeTab === id ? '3px solid var(--primary)' : '3px solid transparent',
        color: activeTab === id ? 'var(--primary)' : 'var(--text-secondary)',
        cursor: 'pointer',
        textAlign: 'left',
        fontSize: '14px',
        fontWeight: activeTab === id ? 600 : 400,
        transition: 'all 0.2s'
      }}
    >
      <Icon size={18} />
      {label}
    </button>
  );

  // Filters
  const filteredUsers = usersList.filter(u => {
    if (!userSearchQuery) return true;
    const q = userSearchQuery.toLowerCase();
    return (
      u.id?.toLowerCase().includes(q) ||
      u.email?.toLowerCase().includes(q) ||
      u.referralCode?.toLowerCase().includes(q)
    );
  });

  const filteredDeposits = deposits.filter(d => {
    if (!depositSearchQuery) return true;
    const q = depositSearchQuery.toLowerCase();
    const dateStr = d.createdAt?.toDate ? new Date(d.createdAt.toDate()).toLocaleDateString() : '';
    const amtStr = (d.expectedAmount || d.amount || 0).toString();
    return (
      d.txid?.toLowerCase().includes(q) ||
      d.userId?.toLowerCase().includes(q) ||
      d.email?.toLowerCase().includes(q) ||
      amtStr.includes(q) ||
      dateStr.includes(q)
    );
  });

  return (
    <div style={{ display: 'flex', minHeight: 'calc(100vh - 60px)', background: 'var(--bg-dark)' }}>
      {/* Admin Sidebar */}
      <div style={{ width: '250px', background: 'var(--bg-panel)', borderRight: '1px solid var(--border)', display: 'flex', flexDirection: 'column', padding: '20px 0' }}>
        <div style={{ padding: '0 20px', marginBottom: '24px', display: 'flex', alignItems: 'center', gap: '8px' }}>
          <ShieldAlert size={20} color="var(--danger)" />
          <h2 style={{ fontSize: '16px', margin: 0, color: 'var(--danger)', fontWeight: 600 }}>Admin Portal</h2>
        </div>
        
        <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
          <TabButton id="dashboard" icon={LayoutDashboard} label="Overview" />
          <TabButton id="users" icon={Users} label="Users Management" />
          <TabButton id="deposits" icon={ArrowDownToLine} label="Deposits" />
          <TabButton id="withdrawals" icon={ArrowUpFromLine} label="Withdrawals" />
          <TabButton id="binance_explore" icon={Search} label="Binance Explore" />
          <TabButton id="push" icon={Bell} label="Push Notifications" />
          {/* Support Inbox — opens dedicated page */}
          <button
            onClick={() => navigate('/admin/support')}
            style={{ display: 'flex', alignItems: 'center', gap: '10px', padding: '10px 20px', borderRadius: '8px', cursor: 'pointer', background: 'linear-gradient(135deg, rgba(16,185,129,0.15), rgba(5,150,105,0.1))', border: '1px solid rgba(16,185,129,0.3)', color: '#10b981', fontWeight: 600, fontSize: '14px', margin: '8px 12px 0', width: 'calc(100% - 24px)', textAlign: 'left' }}
          >
            <MessageSquare size={16} />
            Support Inbox
          </button>
        </div>
      </div>

      {/* Admin Content Area */}
      <div style={{ flex: 1, padding: '24px', overflowY: 'auto', position: 'relative' }}>
        <AnimatePresence mode="wait">
          <motion.div
            key={activeTab}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.2 }}
          >
            {/* DASHBOARD TAB */}
            {activeTab === 'dashboard' && (
              <div>
                <h2 style={{ fontSize: '20px', marginBottom: '24px', display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <LayoutDashboard size={20} color="var(--primary)" /> Dashboard Overview
                </h2>
                {loading ? (
                  <div style={{ padding: '20px', textAlign: 'center', color: 'var(--text-muted)' }}>Loading stats...</div>
                ) : (
                  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '16px' }}>
                    <div className="panel" style={{ padding: '20px', textAlign: 'center' }}>
                      <div style={{ width: '48px', height: '48px', borderRadius: '50%', background: 'rgba(59, 130, 246, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 12px' }}>
                        <Users size={24} color="var(--primary)" />
                      </div>
                      <div style={{ fontSize: '24px', fontWeight: 700, color: 'var(--text-primary)' }}>{stats.totalUsers}</div>
                      <div style={{ fontSize: '13px', color: 'var(--text-muted)' }}>Total Users</div>
                    </div>
                    <div className="panel" style={{ padding: '20px', textAlign: 'center' }}>
                      <div style={{ width: '48px', height: '48px', borderRadius: '50%', background: 'rgba(16, 185, 129, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 12px' }}>
                        <ArrowDownToLine size={24} color="var(--success)" />
                      </div>
                      <div style={{ fontSize: '24px', fontWeight: 700, color: 'var(--text-primary)' }}>${stats.totalDeposits.toFixed(2)}</div>
                      <div style={{ fontSize: '13px', color: 'var(--text-muted)' }}>Total Verified Deposits</div>
                    </div>
                    <div className="panel" style={{ padding: '20px', textAlign: 'center' }}>
                      <div style={{ width: '48px', height: '48px', borderRadius: '50%', background: 'rgba(239, 68, 68, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 12px' }}>
                        <ArrowUpFromLine size={24} color="var(--danger)" />
                      </div>
                      <div style={{ fontSize: '24px', fontWeight: 700, color: 'var(--text-primary)' }}>${stats.totalWithdrawals.toFixed(2)}</div>
                      <div style={{ fontSize: '13px', color: 'var(--text-muted)' }}>Total Verified Withdrawals</div>
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* USERS TAB */}
            {activeTab === 'users' && (
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px', flexWrap: 'wrap', gap: '16px' }}>
                  <h2 style={{ fontSize: '20px', margin: 0, display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <Users size={20} color="var(--primary)" /> User Management
                  </h2>
                  <div style={{ display: 'flex', gap: '12px', flex: 1, maxWidth: '400px' }}>
                    <div style={{ position: 'relative', flex: 1 }}>
                      <Search size={16} color="var(--text-muted)" style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)' }} />
                      <input 
                        type="text" 
                        placeholder="Search by Email, UID, or Ref Code..." 
                        value={userSearchQuery}
                        onChange={(e) => setUserSearchQuery(e.target.value)}
                        style={{ width: '100%', padding: '8px 12px 8px 36px', background: 'var(--bg-panel)', border: '1px solid var(--border)', borderRadius: '8px', color: '#fff', fontSize: '13px' }}
                      />
                    </div>
                    <button onClick={fetchUsersList} className="btn" style={{ padding: '8px 12px', fontSize: '12px', display: 'flex', alignItems: 'center', gap: '6px' }}>
                      <Activity size={14} /> Refresh
                    </button>
                  </div>
                </div>
                {loading ? (
                  <div style={{ padding: '20px', textAlign: 'center', color: 'var(--text-muted)' }}>Loading users...</div>
                ) : (
                  <div className="panel" style={{ overflow: 'hidden' }}>
                    <div style={{ overflowX: 'auto' }}>
                      <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '13px' }}>
                        <thead>
                          <tr style={{ background: 'rgba(255,255,255,0.02)', borderBottom: '1px solid var(--border)' }}>
                            <th style={{ padding: '12px', textAlign: 'left', color: 'var(--text-muted)', fontWeight: 500 }}>User ID</th>
                            <th style={{ padding: '12px', textAlign: 'left', color: 'var(--text-muted)', fontWeight: 500 }}>Email</th>
                            <th style={{ padding: '12px', textAlign: 'left', color: 'var(--text-muted)', fontWeight: 500 }}>Ref Code</th>
                            <th style={{ padding: '12px', textAlign: 'right', color: 'var(--text-muted)', fontWeight: 500 }}>Main Bal.</th>
                            <th style={{ padding: '12px', textAlign: 'right', color: 'var(--text-muted)', fontWeight: 500 }}>Mining Bal.</th>
                            <th style={{ padding: '12px', textAlign: 'center', color: 'var(--text-muted)', fontWeight: 500 }}>Country</th>
                            <th style={{ padding: '12px', textAlign: 'center', color: 'var(--text-muted)', fontWeight: 500 }}>Actions</th>
                          </tr>
                        </thead>
                        <tbody>
                          {filteredUsers.length === 0 ? (
                            <tr><td colSpan="7" style={{ padding: '20px', textAlign: 'center', color: 'var(--text-muted)' }}>No users found matching "{userSearchQuery}"</td></tr>
                          ) : filteredUsers.map(u => (
                            <tr key={u.id} style={{ borderBottom: '1px solid rgba(255,255,255,0.05)', background: editingUser?.id === u.id ? 'rgba(59, 130, 246, 0.05)' : 'transparent' }}>
                              <td style={{ padding: '12px', fontFamily: 'monospace' }}>
                                {u.id.substring(0, 8)}... <Copy size={12} style={{cursor: 'pointer', color: 'var(--primary)'}} onClick={() => handleCopy(u.id)} />
                              </td>
                              <td style={{ padding: '12px' }}>{u.email}</td>
                              <td style={{ padding: '12px', color: 'var(--primary)', fontFamily: 'monospace' }}>{u.referralCode}</td>
                              
                              {editingUser?.id === u.id ? (
                                <>
                                  <td style={{ padding: '12px', textAlign: 'right' }}>
                                    <input 
                                      type="number" 
                                      value={editForm.balance} 
                                      onChange={(e) => setEditForm({...editForm, balance: e.target.value})}
                                      style={{ width: '80px', padding: '4px 8px', background: 'var(--bg-dark)', border: '1px solid var(--border)', color: '#fff', borderRadius: '4px', textAlign: 'right' }}
                                    />
                                  </td>
                                  <td style={{ padding: '12px', textAlign: 'right' }}>
                                    <input 
                                      type="number" 
                                      value={editForm.miningBalance} 
                                      onChange={(e) => setEditForm({...editForm, miningBalance: e.target.value})}
                                      style={{ width: '80px', padding: '4px 8px', background: 'var(--bg-dark)', border: '1px solid var(--border)', color: '#fff', borderRadius: '4px', textAlign: 'right' }}
                                    />
                                  </td>
                                  <td style={{ padding: '12px', textAlign: 'center' }}>{u.country || 'N/A'}</td>
                                  <td style={{ padding: '12px', textAlign: 'center' }}>
                                    <div style={{ display: 'flex', gap: '8px', justifyContent: 'center' }}>
                                      <button onClick={handleSaveUser} style={{ background: 'rgba(16, 185, 129, 0.1)', color: 'var(--success)', border: 'none', padding: '4px 8px', borderRadius: '4px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '4px' }}>
                                        <Save size={14} /> Save
                                      </button>
                                      <button onClick={() => setEditingUser(null)} style={{ background: 'rgba(239, 68, 68, 0.1)', color: 'var(--danger)', border: 'none', padding: '4px 8px', borderRadius: '4px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '4px' }}>
                                        <X size={14} /> Cancel
                                      </button>
                                    </div>
                                  </td>
                                </>
                              ) : (
                                <>
                                  <td style={{ padding: '12px', textAlign: 'right', fontWeight: 600, color: 'var(--success)' }}>
                                    {u.country === 'Malawi' ? `${((u.balance || 0) * 1700).toLocaleString(undefined, {maximumFractionDigits: 0})} MWK` : `${u.country === 'Tanzania' ? 'TZS' : '$'} ${(u.balance || 0).toLocaleString(undefined, { minimumFractionDigits: u.country === 'Tanzania' ? 0 : 2, maximumFractionDigits: u.country === 'Tanzania' ? 0 : 2 })}`}
                                  </td>
                                  <td style={{ padding: '12px', textAlign: 'right', fontWeight: 600, color: '#d4af37' }}>
                                    {u.country === 'Malawi' ? `${((u.miningBalance || 0) * 1700).toLocaleString(undefined, {maximumFractionDigits: 0})} MWK` : `${u.country === 'Tanzania' ? 'TZS' : '$'} ${(u.miningBalance || 0).toLocaleString(undefined, { minimumFractionDigits: u.country === 'Tanzania' ? 0 : 2, maximumFractionDigits: u.country === 'Tanzania' ? 0 : 2 })}`}
                                  </td>
                                  <td style={{ padding: '12px', textAlign: 'center' }}>{u.country || 'N/A'}</td>
                                  <td style={{ padding: '12px', textAlign: 'center' }}>
                                    <button onClick={() => handleEditClick(u)} style={{ background: 'transparent', border: '1px solid var(--border)', color: 'var(--text-secondary)', padding: '4px 8px', borderRadius: '4px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '4px', margin: '0 auto' }}>
                                      <Edit2 size={14} /> Edit
                                    </button>
                                  </td>
                                </>
                              )}
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* DEPOSITS TAB */}
            {activeTab === 'deposits' && (
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px', flexWrap: 'wrap', gap: '16px' }}>
                  <h2 style={{ fontSize: '20px', margin: 0, display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <ArrowDownToLine size={20} color="var(--success)" /> Deposits
                  </h2>
                  <div style={{ display: 'flex', gap: '12px', flex: 1, maxWidth: '450px' }}>
                    <div style={{ position: 'relative', flex: 1 }}>
                      <Search size={16} color="var(--text-muted)" style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)' }} />
                      <input 
                        type="text" 
                        placeholder="Search TXID, Email, Amount, Date..." 
                        value={depositSearchQuery}
                        onChange={(e) => setDepositSearchQuery(e.target.value)}
                        style={{ width: '100%', padding: '8px 12px 8px 36px', background: 'var(--bg-panel)', border: '1px solid var(--border)', borderRadius: '8px', color: '#fff', fontSize: '13px' }}
                      />
                    </div>
                    <button onClick={fetchDeposits} className="btn" style={{ padding: '8px 12px', fontSize: '12px', display: 'flex', alignItems: 'center', gap: '6px' }}>
                      <Activity size={14} /> Refresh
                    </button>
                  </div>
                </div>
                {loading ? (
                  <div style={{ padding: '20px', textAlign: 'center', color: 'var(--text-muted)' }}>Loading deposits...</div>
                ) : filteredDeposits.length === 0 ? (
                  <div style={{ padding: '20px', textAlign: 'center', color: 'var(--text-muted)' }}>
                    {depositSearchQuery ? `No deposits matching "${depositSearchQuery}"` : "No deposits found."}
                  </div>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
                    {filteredDeposits.map(d => (
                      <div key={d.id} className="panel" style={{ border: `1px solid ${d.status === 'pending' ? (d.network === 'MozambiqueMobile' ? 'rgba(251,191,36,0.8)' : 'var(--warning)') : 'var(--border)'}`, padding: '16px' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '12px' }}>
                          <div>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '2px' }}>
                              <div style={{ fontSize: '11px', color: 'var(--text-muted)' }}>User ({d.email})</div>
                              {d.network === 'MozambiqueMobile' && (
                                <span style={{ fontSize: '10px', background: 'rgba(16,185,129,0.15)', color: 'var(--success)', border: '1px solid rgba(16,185,129,0.3)', borderRadius: '4px', padding: '1px 6px', fontWeight: 700 }}>🇲🇿 e-MOLA</span>
                              )}
                            </div>
                            <div style={{ fontFamily: 'monospace', display: 'flex', alignItems: 'center', gap: '6px', fontSize: '13px' }}>
                              {d.userId} <Copy size={12} style={{cursor: 'pointer'}} onClick={() => handleCopy(d.userId)} />
                            </div>
                            <div style={{ fontSize: '10px', color: 'var(--text-muted)', marginTop: '4px' }}>
                              Date: {d.createdAt?.toDate ? new Date(d.createdAt.toDate()).toLocaleString() : 'N/A'}
                            </div>
                            {/* MZ-specific: show sender phone */}
                            {d.network === 'MozambiqueMobile' && (d.senderPhone || d.senderName) && (
                              <div style={{ fontSize: '11px', marginTop: '6px', color: '#fbbf24', display: 'flex', alignItems: 'center', gap: '4px' }}>
                                📱 Sender: <span style={{ fontFamily: 'monospace', fontWeight: 600 }}>{d.senderName ? `${d.senderName} (${d.senderPhone})` : d.senderPhone}</span>
                              </div>
                            )}
                            {d.network === 'MozambiqueMobile' && d.paymentTo && (
                              <div style={{ fontSize: '11px', color: 'var(--text-muted)' }}>
                                To: <span style={{ fontFamily: 'monospace' }}>{d.paymentTo}</span>
                              </div>
                            )}
                          </div>
                          <div style={{ textAlign: 'right' }}>
                            <div style={{ fontSize: '18px', fontWeight: 700, color: 'var(--success)' }}>
                              {(d.network === 'MozambiqueMobile' || d.currency === 'MWK' || (d.txid && d.txid.startsWith('MZ-'))) ? `${(d.expectedAmount || 0).toLocaleString()} MWK` : `${d.currency === 'TZS' ? 'TZS' : '$'} ${(d.expectedAmount || d.amount || 0).toLocaleString(undefined, { minimumFractionDigits: d.currency === 'TZS' ? 0 : 2, maximumFractionDigits: d.currency === 'TZS' ? 0 : 2 })}`}
                            </div>
                            <div style={{ fontSize: '11px', textTransform: 'uppercase', color: d.status === 'pending' ? 'var(--warning)' : d.status === 'SUCCESS' ? 'var(--success)' : 'var(--danger)' }}>
                              {d.status}
                            </div>
                            <button 
                              onClick={() => openFollowUp(d)}
                              style={{ marginTop: '8px', background: 'var(--primary)', border: 'none', padding: '4px 8px', borderRadius: '4px', color: '#fff', fontSize: '11px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '4px', float: 'right' }}
                            >
                              <MessageSquare size={12} /> Follow Up
                            </button>
                          </div>
                        </div>
                        <div style={{ fontSize: '13px', background: 'rgba(0,0,0,0.2)', padding: '8px', borderRadius: '4px', marginBottom: '12px', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                          <div>
                            <span style={{ color: 'var(--text-muted)' }}>Network: </span>
                            <span style={{ fontWeight: 600 }}>{d.network || 'N/A'}</span>
                            <span style={{ color: 'var(--text-muted)', marginLeft: '12px' }}>TXID: </span>
                            <span style={{ fontFamily: 'monospace' }}>{d.txid}</span>
                          </div>
                          <Copy size={14} style={{cursor: 'pointer', color: 'var(--primary)'}} onClick={() => handleCopy(d.txid)} />
                        </div>
                        {d.adminNote && (
                          <div style={{ fontSize: '12px', color: 'var(--text-secondary)', padding: '8px', background: 'rgba(255,255,255,0.02)', borderLeft: '3px solid var(--primary)', marginBottom: '12px' }}>
                            <strong>Note:</strong> {d.adminNote}
                          </div>
                        )}
                        {d.status === 'pending' && (
                          <div style={{ display: 'flex', gap: '8px' }}>
                            <button onClick={() => handleApproveDeposit(d)} style={{ flex: 1, padding: '8px', background: 'rgba(16, 185, 129, 0.1)', color: 'var(--success)', border: '1px solid rgba(16, 185, 129, 0.2)', borderRadius: '6px', cursor: 'pointer', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '4px', fontSize: '13px' }}>
                              <CheckCircle2 size={16} /> {(d.network === 'MozambiqueMobile' || d.currency === 'MWK' || (d.txid && d.txid.startsWith('MZ-'))) ? 'Approve MWK' : 'Approve & Credit'}
                            </button>
                            <button onClick={() => handleRejectDeposit(d)} style={{ flex: 1, padding: '8px', background: 'rgba(239, 68, 68, 0.1)', color: 'var(--danger)', border: '1px solid rgba(239, 68, 68, 0.2)', borderRadius: '6px', cursor: 'pointer', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '4px', fontSize: '13px' }}>
                              <XCircle size={16} /> Reject
                            </button>
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* WITHDRAWALS TAB */}
            {activeTab === 'withdrawals' && (
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
                  <h2 style={{ fontSize: '20px', margin: 0, display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <ArrowUpFromLine size={20} color="var(--danger)" /> Withdrawals
                  </h2>
                  <button onClick={fetchWithdrawals} className="btn" style={{ padding: '6px 12px', fontSize: '12px', display: 'flex', alignItems: 'center', gap: '6px' }}>
                    <Activity size={14} /> Refresh
                  </button>
                </div>
                {loading ? (
                  <div style={{ padding: '20px', textAlign: 'center', color: 'var(--text-muted)' }}>Loading withdrawals...</div>
                ) : withdrawals.length === 0 ? (
                  <div style={{ padding: '20px', textAlign: 'center', color: 'var(--text-muted)' }}>No withdrawals found.</div>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
                    {withdrawals.map(w => (
                      <div key={w.id} style={{ background: 'var(--bg-dark)', borderRadius: '8px', border: `1px solid ${w.status === 'pending' ? 'var(--warning)' : 'var(--border)'}`, overflow: 'hidden' }}>
                        
                        {/* Header */}
                        <div style={{ padding: '12px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'rgba(255,255,255,0.02)' }}>
                          <div>
                            <span style={{ fontSize: '11px', color: 'var(--text-muted)' }}>User ID:</span>
                            <div style={{ fontSize: '13px', fontFamily: 'monospace', color: '#fff', display: 'flex', alignItems: 'center', gap: '6px' }}>
                              {w.userId.substring(0,8)}... <Copy size={12} style={{cursor: 'pointer'}} onClick={() => handleCopy(w.userId)} />
                            </div>
                          </div>
                          <div style={{ textAlign: 'right' }}>
                            <div style={{ fontSize: '18px', fontWeight: 700, color: 'var(--primary)' }}>{w.currency === 'TZS' ? 'TZS' : '$'} {w.amount?.toLocaleString(undefined, { minimumFractionDigits: w.currency === 'TZS' ? 0 : 2, maximumFractionDigits: w.currency === 'TZS' ? 0 : 2 })}</div>
                            {w.accountDetails?.type === 'mobile' && w.currency !== 'TZS' && (
                              <div style={{ fontSize: '11px', color: 'var(--text-muted)' }}>
                                ≈ {(w.amount * 1700).toLocaleString()} MWK
                              </div>
                            )}
                            <div style={{ fontSize: '11px', textTransform: 'uppercase', color: w.status === 'pending' ? 'var(--warning)' : w.status === 'SUCCESS' ? 'var(--success)' : 'var(--danger)', marginTop: '4px' }}>
                              {w.status}
                            </div>
                          </div>
                        </div>

                        {/* Account Details */}
                        <div style={{ padding: '12px', borderTop: '1px solid var(--border)', borderBottom: '1px solid var(--border)', fontSize: '13px' }}>
                          {w.accountDetails ? (
                            <>
                              {w.accountDetails.type === 'binance_id' && (
                                <div>
                                  <span style={{ color: 'var(--text-muted)', fontSize: '11px' }}>Binance Pay ID:</span>
                                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 600 }}>
                                    {w.accountDetails.binanceId}
                                    <button onClick={() => handleCopy(w.accountDetails.binanceId)} style={{ background: 'none', border: 'none', color: 'var(--primary)', cursor: 'pointer' }}><Copy size={14} /></button>
                                  </div>
                                </div>
                              )}
                              {w.accountDetails.type === 'crypto_address' && (
                                <div>
                                  <span style={{ color: 'var(--text-muted)', fontSize: '11px' }}>{w.accountDetails.network} Address:</span>
                                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 600, wordBreak: 'break-all' }}>
                                    {w.accountDetails.address}
                                    <button onClick={() => handleCopy(w.accountDetails.address)} style={{ background: 'none', border: 'none', color: 'var(--primary)', cursor: 'pointer' }}><Copy size={14} /></button>
                                  </div>
                                </div>
                              )}
                              {w.accountDetails.type === 'mobile' && (
                                <div>
                                  <span style={{ color: 'var(--text-muted)', fontSize: '11px' }}>{w.accountDetails.network} Mobile:</span>
                                  <div style={{ display: 'flex', alignItems: 'center', gap: '6px', fontWeight: 600, flexWrap: 'wrap' }}>
                                    <span style={{ fontFamily: 'monospace', fontSize: '14px' }}>{w.accountDetails.accountNumber}</span>
                                    <button onClick={() => handleCopy(w.accountDetails.accountNumber)} style={{ background: 'rgba(56, 189, 248, 0.1)', border: '1px solid rgba(56, 189, 248, 0.2)', color: 'var(--primary)', cursor: 'pointer', padding: '2px 6px', borderRadius: '4px', display: 'flex', alignItems: 'center', gap: '4px', fontSize: '10px' }}><Copy size={12} /> Number</button>
                                    <span style={{ color: 'var(--text-muted)', margin: '0 4px' }}>|</span>
                                    <span>{w.accountDetails.accountName}</span>
                                    <button onClick={() => handleCopy(w.accountDetails.accountName)} style={{ background: 'rgba(56, 189, 248, 0.1)', border: '1px solid rgba(56, 189, 248, 0.2)', color: 'var(--primary)', cursor: 'pointer', padding: '2px 6px', borderRadius: '4px', display: 'flex', alignItems: 'center', gap: '4px', fontSize: '10px' }}><Copy size={12} /> Name</button>
                                  </div>
                                </div>
                              )}
                            </>
                          ) : (
                            <div style={{ color: 'var(--text-muted)' }}>No specific account details attached.</div>
                          )}
                          <div style={{ fontSize: '10px', color: 'var(--text-muted)', marginTop: '8px' }}>
                            Date: {w.createdAt?.toDate ? new Date(w.createdAt.toDate()).toLocaleString() : 'N/A'}
                          </div>
                        </div>

                        {/* Actions */}
                        <div style={{ padding: '8px', display: 'flex', gap: '8px' }}>
                          {w.status === 'pending' && (
                            <>
                              <button 
                                onClick={() => handleApproveWithdrawal(w)}
                                style={{ flex: 1, background: 'rgba(46, 204, 113, 0.1)', color: 'var(--success)', border: '1px solid rgba(46, 204, 113, 0.2)', padding: '8px', borderRadius: '6px', cursor: 'pointer', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '4px', fontSize: '12px', fontWeight: 600 }}
                              >
                                <CheckCircle2 size={16} /> Approve
                              </button>
                              <button 
                                onClick={() => handleRejectWithdrawal(w)}
                                style={{ flex: 1, background: 'rgba(231, 76, 60, 0.1)', color: 'var(--danger)', border: '1px solid rgba(231, 76, 60, 0.2)', padding: '8px', borderRadius: '6px', cursor: 'pointer', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '4px', fontSize: '12px', fontWeight: 600 }}
                              >
                                <XCircle size={16} /> Reject (Refund)
                              </button>
                            </>
                          )}
                          <button 
                            onClick={() => handleDeleteWithdrawal(w)}
                            style={{ background: 'none', border: '1px solid var(--border)', color: 'var(--text-muted)', padding: '8px', borderRadius: '6px', cursor: 'pointer', display: 'flex', justifyContent: 'center', alignItems: 'center' }}
                            title="Delete permanently"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>

                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* BINANCE EXPLORE TAB */}
            {activeTab === 'binance_explore' && (
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', flexWrap: 'wrap', gap: '12px' }}>
                  <h2 style={{ fontSize: '20px', margin: 0, display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <Search size={20} color="#F0B90B" /> Binance Deposit History
                  </h2>
                  <div style={{ fontSize: '12px', color: '#F0B90B', background: 'rgba(240,185,11,0.1)', border: '1px solid rgba(240,185,11,0.3)', borderRadius: '20px', padding: '4px 14px', fontWeight: 600 }}>
                    🟡 Last 90 days · {allTxns.length} deposits
                  </div>
                </div>

                {/* Search + Network Filter */}
                <div className="panel" style={{ padding: '12px 16px', marginBottom: '16px', display: 'flex', gap: '10px', alignItems: 'center', flexWrap: 'wrap' }}>
                  <Search size={16} color="var(--text-muted)" style={{ flexShrink: 0 }} />
                  <input type="text" value={txnSearchQuery} onChange={e => setTxnSearchQuery(e.target.value)}
                    placeholder="Search TXID, coin, network, address..."
                    style={{ flex: 1, minWidth: '160px', padding: '7px', background: 'var(--bg-dark)', border: '1px solid var(--border)', borderRadius: '8px', color: '#fff', fontSize: '13px' }} />
                  <div style={{ display: 'flex', gap: '6px' }}>
                    {['all', 'TRC20', 'BNB Smart Chain', 'ETH'].map(n => (
                      <button key={n} onClick={() => setNetworkFilter(n)}
                        style={{ padding: '5px 12px', borderRadius: '20px', fontSize: '11px', fontWeight: 600, cursor: 'pointer',
                          background: networkFilter === n ? '#F0B90B' : 'transparent',
                          color: networkFilter === n ? '#000' : 'var(--text-muted)',
                          border: `1px solid ${networkFilter === n ? '#F0B90B' : 'var(--border)'}` }}>
                        {n === 'all' ? 'All Networks' : n}
                      </button>
                    ))}
                  </div>
                  <button onClick={fetchAllTxns} disabled={binanceLoading}
                    style={{ padding: '7px 16px', fontSize: '12px', flexShrink: 0, background: '#F0B90B', color: '#000', border: 'none', borderRadius: '8px', fontWeight: 700, cursor: 'pointer', opacity: binanceLoading ? 0.7 : 1 }}>
                    {binanceLoading ? 'Loading...' : '↻ Refresh'}
                  </button>
                </div>

                {binanceLoading ? (
                  <div style={{ padding: '40px', textAlign: 'center', color: 'var(--text-muted)' }}>
                    <div style={{ fontSize: '2rem', marginBottom: '8px' }}>⏳</div>
                    Fetching from Binance API...
                  </div>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                    {allTxns
                      .filter(tx => {
                        const matchNet = networkFilter === 'all' || tx.network === networkFilter;
                        if (!txnSearchQuery) return matchNet;
                        const q = txnSearchQuery.toLowerCase();
                        return matchNet && (
                          tx.txid?.toLowerCase().includes(q) ||
                          tx.address?.toLowerCase().includes(q) ||
                          tx.coin?.toLowerCase().includes(q) ||
                          tx.network?.toLowerCase().includes(q) ||
                          String(tx.amount).includes(q)
                        );
                      })
                      .map((tx, i) => (
                        <div key={tx.txid || i} className="panel" style={{ padding: '12px 16px', borderLeft: `3px solid ${tx.status === 'Success' ? 'var(--success)' : tx.status === 'Pending' ? 'var(--warning)' : 'var(--danger)'}` }}>
                          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: '12px', flexWrap: 'wrap' }}>
                            <div style={{ flex: 1, minWidth: '200px' }}>
                              {/* Badges */}
                              <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '6px' }}>
                                <span style={{ fontSize: '10px', background: 'rgba(240,185,11,0.15)', color: '#F0B90B', borderRadius: '4px', padding: '2px 7px', fontWeight: 700 }}>{tx.network}</span>
                                <span style={{ fontSize: '10px', fontWeight: 700, color: tx.status === 'Success' ? 'var(--success)' : tx.status === 'Pending' ? 'var(--warning)' : 'var(--danger)' }}>{tx.status}</span>
                                {tx.confirmTimes && <span style={{ fontSize: '10px', color: 'var(--text-muted)' }}>✓ {tx.confirmTimes} confirms</span>}
                              </div>
                              {/* TXID */}
                              <div style={{ display: 'flex', alignItems: 'center', gap: '6px', background: 'var(--bg-dark)', borderRadius: '6px', padding: '5px 8px', marginBottom: '4px' }}>
                                <span style={{ fontSize: '10px', fontFamily: 'monospace', color: 'var(--text-secondary)', flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{tx.txid || '—'}</span>
                                {tx.txid && (
                                  <button onClick={() => { navigator.clipboard.writeText(tx.txid); toast.success('TXID copied!'); }}
                                    style={{ background: 'rgba(240,185,11,0.1)', border: '1px solid rgba(240,185,11,0.3)', borderRadius: '4px', cursor: 'pointer', color: '#F0B90B', padding: '2px 6px', fontSize: '10px', display: 'flex', alignItems: 'center', gap: '3px', flexShrink: 0 }}>
                                    <Copy size={9} /> Copy
                                  </button>
                                )}
                              </div>
                              {/* Address */}
                              <div style={{ fontSize: '11px', color: 'var(--text-muted)', display: 'flex', alignItems: 'center', gap: '4px' }}>
                                <span style={{ color: 'var(--text-secondary)' }}>To:</span>
                                <span style={{ fontFamily: 'monospace' }}>{tx.address?.substring(0, 22)}...</span>
                                <button onClick={() => { navigator.clipboard.writeText(tx.address); toast.success('Address copied'); }}
                                  style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--primary)', padding: 0 }}>
                                  <Copy size={10} />
                                </button>
                              </div>
                              <div style={{ fontSize: '10px', color: 'var(--text-muted)', marginTop: '3px' }}>{tx.date}</div>
                            </div>
                            {/* Amount */}
                            <div style={{ textAlign: 'right', flexShrink: 0 }}>
                              <div style={{ fontSize: '22px', fontWeight: 800, color: '#F0B90B' }}>{tx.amount}</div>
                              <div style={{ fontSize: '12px', color: 'var(--text-muted)', fontWeight: 600 }}>{tx.coin}</div>
                            </div>
                          </div>
                        </div>
                      ))
                    }
                    {!binanceLoading && allTxnsLoaded && allTxns.filter(tx => networkFilter === 'all' || tx.network === networkFilter).length === 0 && (
                      <div style={{ padding: '40px', textAlign: 'center', color: 'var(--text-muted)' }}>No Binance deposits found in the last 90 days.</div>
                    )}
                    {!allTxnsLoaded && !binanceLoading && (
                      <div style={{ padding: '40px', textAlign: 'center' }}>
                        <button onClick={fetchAllTxns}
                          style={{ background: '#F0B90B', color: '#000', border: 'none', borderRadius: '12px', padding: '12px 32px', fontWeight: 700, fontSize: '15px', cursor: 'pointer' }}>
                          Load Binance Deposits
                        </button>
                        <div style={{ fontSize: '12px', color: 'var(--text-muted)', marginTop: '8px' }}>Fetches last 90 days of USDT deposits via Binance API</div>
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}



                {/* Wallet addresses */}

            {/* PUSH NOTIFICATIONS TAB */}

            {activeTab === 'push' && (
              <div>
                <h2 style={{ fontSize: '20px', marginBottom: '24px', display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <Bell size={20} color="var(--primary)" /> Broadcast Push Notifications
                </h2>
                <div className="panel" style={{ padding: '24px', maxWidth: '600px' }}>
                  <div style={{ marginBottom: '16px' }}>
                    <label style={{ display: 'block', marginBottom: '8px', color: 'var(--text-secondary)' }}>Target Audience</label>
                    <select 
                      value={pushForm.userId} 
                      onChange={e => setPushForm(prev => ({...prev, userId: e.target.value}))}
                      style={{ width: '100%', padding: '10px', background: 'var(--bg-dark)', border: '1px solid var(--border)', borderRadius: '8px', color: '#fff' }}
                    >
                      <option value="all">All Users (Broadcast)</option>
                      {usersList.map(u => (
                        <option key={u.id} value={u.id}>{u.email} ({u.id.substring(0,8)})</option>
                      ))}
                    </select>
                  </div>
                  <div style={{ marginBottom: '16px' }}>
                    <label style={{ display: 'block', marginBottom: '8px', color: 'var(--text-secondary)' }}>Notification Title</label>
                    <input 
                      type="text" 
                      value={pushForm.title} 
                      onChange={e => setPushForm(prev => ({...prev, title: e.target.value}))}
                      placeholder="e.g. Special Bonus Event!"
                      style={{ width: '100%', padding: '10px', background: 'var(--bg-dark)', border: '1px solid var(--border)', borderRadius: '8px', color: '#fff' }}
                    />
                  </div>
                  <div style={{ marginBottom: '24px' }}>
                    <label style={{ display: 'block', marginBottom: '8px', color: 'var(--text-secondary)' }}>Notification Body</label>
                    <textarea 
                      value={pushForm.body} 
                      onChange={e => setPushForm(prev => ({...prev, body: e.target.value}))}
                      placeholder="Type your message here..."
                      style={{ width: '100%', padding: '10px', background: 'var(--bg-dark)', border: '1px solid var(--border)', borderRadius: '8px', color: '#fff', height: '100px', resize: 'none' }}
                    />
                  </div>
                  <div style={{ marginBottom: '24px' }}>
                    <label style={{ display: 'block', marginBottom: '8px', color: 'var(--text-secondary)' }}>Image Attachment (Optional)</label>
                    <input 
                      id="pushImageInput"
                      type="file" 
                      accept="image/*"
                      onChange={e => setPushImageFile(e.target.files[0] || null)}
                      style={{ width: '100%', padding: '10px', background: 'var(--bg-dark)', border: '1px solid var(--border)', borderRadius: '8px', color: '#fff' }}
                    />
                    <p style={{ fontSize: '11px', color: 'var(--text-muted)', marginTop: '6px' }}>The image will be securely uploaded to your storage and attached to the push notification.</p>
                  </div>
                  <button 
                    onClick={handleAdminPush} 
                    disabled={pushForm.loading}
                    className="btn btn-primary" 
                    style={{ width: '100%', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '8px', opacity: pushForm.loading ? 0.7 : 1 }}
                  >
                    <Send size={16} /> {pushForm.loading ? 'Sending...' : 'Send Push Notification'}
                  </button>
                </div>
              </div>
            )}
          </motion.div>
        </AnimatePresence>

        {/* FOLLOW UP MODAL */}
        <AnimatePresence>
          {followUpModal.isOpen && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0,0,0,0.8)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '20px', backdropFilter: 'blur(4px)' }}
            >
              <motion.div
                initial={{ scale: 0.95, opacity: 0, y: 20 }}
                animate={{ scale: 1, opacity: 1, y: 0 }}
                exit={{ scale: 0.95, opacity: 0, y: 20 }}
                style={{ background: 'var(--bg-panel)', padding: '24px', borderRadius: '12px', width: '100%', maxWidth: '600px', border: '1px solid var(--border)', maxHeight: '90vh', overflowY: 'auto' }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
                  <h3 style={{ margin: 0, fontSize: '18px', display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <MessageSquare size={18} color="var(--primary)" /> Transaction Follow-Up
                  </h3>
                  <button onClick={() => setFollowUpModal({ isOpen: false, transaction: null, history: [], note: '', notificationMsg: '', loading: false })} style={{ background: 'transparent', border: 'none', color: 'var(--text-muted)', cursor: 'pointer' }}>
                    <X size={20} />
                  </button>
                </div>

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px', marginBottom: '24px' }}>
                  {/* Note Section */}
                  <div>
                    <h4 style={{ fontSize: '13px', margin: '0 0 8px 0', color: 'var(--text-secondary)' }}>Admin Internal Note</h4>
                    <textarea 
                      value={followUpModal.note}
                      onChange={e => setFollowUpModal(prev => ({...prev, note: e.target.value}))}
                      placeholder="Add a note (only visible to admins)..."
                      style={{ width: '100%', height: '80px', padding: '10px', background: 'var(--bg-dark)', border: '1px solid var(--border)', borderRadius: '8px', color: '#fff', fontSize: '13px', resize: 'none' }}
                    />
                    <button onClick={saveAdminNote} className="btn btn-primary" style={{ marginTop: '8px', width: '100%', padding: '6px', fontSize: '12px' }}>Save Note</button>
                  </div>
                  
                  {/* Notification Section */}
                  <div>
                    <h4 style={{ fontSize: '13px', margin: '0 0 8px 0', color: 'var(--text-secondary)' }}>Send Notification to User</h4>
                    <textarea 
                      value={followUpModal.notificationMsg}
                      onChange={e => setFollowUpModal(prev => ({...prev, notificationMsg: e.target.value}))}
                      placeholder="Message to send to user's inbox..."
                      style={{ width: '100%', height: '80px', padding: '10px', background: 'var(--bg-dark)', border: '1px solid var(--border)', borderRadius: '8px', color: '#fff', fontSize: '13px', resize: 'none' }}
                    />
                    <button onClick={sendNotification} style={{ marginTop: '8px', width: '100%', padding: '6px', fontSize: '12px', background: 'rgba(59, 130, 246, 0.1)', color: 'var(--primary)', border: '1px solid rgba(59, 130, 246, 0.2)', borderRadius: '8px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px' }}>
                      <Bell size={14} /> Send Notification
                    </button>
                  </div>
                </div>

                {/* User History */}
                <div>
                  <h4 style={{ fontSize: '14px', margin: '0 0 12px 0', display: 'flex', alignItems: 'center', gap: '6px' }}><Eye size={16} /> User's Recent History</h4>
                  {followUpModal.loading ? (
                    <div style={{ color: 'var(--text-muted)', fontSize: '13px' }}>Loading history...</div>
                  ) : followUpModal.history.length === 0 ? (
                    <div style={{ color: 'var(--text-muted)', fontSize: '13px' }}>No previous transactions found.</div>
                  ) : (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', maxHeight: '250px', overflowY: 'auto', paddingRight: '8px' }}>
                      {followUpModal.history.map(h => (
                        <div key={h.id} style={{ background: 'var(--bg-dark)', padding: '10px', borderRadius: '8px', border: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                          <div>
                            <div style={{ fontSize: '12px', fontWeight: 600, textTransform: 'capitalize' }}>{h.type}</div>
                            <div style={{ fontSize: '10px', color: 'var(--text-muted)' }}>{h.createdAt?.toDate ? new Date(h.createdAt.toDate()).toLocaleDateString() : 'N/A'}</div>
                          </div>
                          <div style={{ textAlign: 'right' }}>
                            <div style={{ fontSize: '14px', fontWeight: 700, color: h.status === 'SUCCESS' || h.status === 'success' ? 'var(--success)' : h.status === 'pending' ? 'var(--warning)' : 'var(--text-primary)' }}>
                              ${(h.amount || h.expectedAmount || 0).toFixed(2)}
                            </div>
                            <div style={{ fontSize: '10px', color: 'var(--text-muted)', textTransform: 'uppercase' }}>{h.status}</div>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>

              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>

      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAuth } from '../contexts/AuthContext';
import { db, storage } from '../firebase';
import {
  collection, query, orderBy, onSnapshot,
  addDoc, doc, setDoc, serverTimestamp, updateDoc
} from 'firebase/firestore';
import { ref, uploadBytesResumable, getDownloadURL } from 'firebase/storage';
import {
  ChevronLeft, Send, Image, CheckCheck, Clock,
  Search, MessageSquare, Circle, X, User
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';

export const AdminSupport = () => {
  const { currentUser, isAdmin } = useAuth();
  const navigate = useNavigate();

  const [chats, setChats] = useState([]);          // list of all user chat rooms
  const [selectedChat, setSelectedChat] = useState(null); // { chatId, userName, userEmail }
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState('');
  const [sending, setSending] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(null);
  const [imageFile, setImageFile] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);
  const [search, setSearch] = useState('');
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const bottomRef = useRef(null);
  const fileInputRef = useRef(null);
  const msgUnsubRef = useRef(null);

  // Guard — admins only
  useEffect(() => {
    if (!isAdmin) { navigate('/'); }
  }, [isAdmin, navigate]);

  // ── Load all support chat rooms ──────────────────────────────────────
  useEffect(() => {
    const q = query(collection(db, 'supportChats'), orderBy('lastMessageAt', 'desc'));
    const unsub = onSnapshot(q, snap => {
      setChats(snap.docs.map(d => ({ chatId: d.id, ...d.data() })));
    }, err => console.error('Chat list error:', err));
    return () => unsub();
  }, []);

  // ── Load messages for selected chat ─────────────────────────────────
  useEffect(() => {
    if (msgUnsubRef.current) { msgUnsubRef.current(); msgUnsubRef.current = null; }
    if (!selectedChat) { setMessages([]); return; }

    const q = query(
      collection(db, 'supportChats', selectedChat.chatId, 'messages'),
      orderBy('createdAt', 'asc')
    );
    msgUnsubRef.current = onSnapshot(q, snap => {
      setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      // Mark as read
      setDoc(doc(db, 'supportChats', selectedChat.chatId), { unreadAdmin: 0 }, { merge: true });
    });
    return () => { if (msgUnsubRef.current) msgUnsubRef.current(); };
  }, [selectedChat]);

  // ── Auto scroll ──────────────────────────────────────────────────────
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // ── Send message ─────────────────────────────────────────────────────
  async function sendMessage() {
    if ((!text.trim() && !imageFile) || sending || !selectedChat) return;
    setSending(true);
    try {
      let imageUrl = null;
      if (imageFile) {
        const storageRef = ref(storage, `support/admin/${Date.now()}_${imageFile.name}`);
        const task = uploadBytesResumable(storageRef, imageFile);
        imageUrl = await new Promise((resolve, reject) => {
          task.on('state_changed',
            snap => setUploadProgress(Math.round((snap.bytesTransferred / snap.totalBytes) * 100)),
            reject,
            async () => resolve(await getDownloadURL(task.snapshot.ref))
          );
        });
        setUploadProgress(null);
      }

      await addDoc(collection(db, 'supportChats', selectedChat.chatId, 'messages'), {
        text: text.trim(),
        imageUrl,
        senderId: 'admin',
        senderName: 'QTX Support',
        senderRole: 'agent',
        createdAt: serverTimestamp(),
        status: 'sent',
      });

      await setDoc(doc(db, 'supportChats', selectedChat.chatId), {
        lastMessage: imageUrl ? '📷 Image' : text.trim(),
        lastMessageAt: serverTimestamp(),
        unreadUser: 1,
      }, { merge: true });

      setText('');
      clearImage();
    } catch (err) {
      console.error(err);
      toast.error('Failed to send');
    } finally {
      setSending(false);
    }
  }

  function handleKeyDown(e) {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendMessage(); }
  }

  function clearImage() {
    setImageFile(null);
    setImagePreview(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  }

  function handleImageSelect(e) {
    const file = e.target.files[0];
    if (!file) return;
    if (file.size > 10 * 1024 * 1024) { toast.error('Image must be under 10MB'); return; }
    setImageFile(file);
    setImagePreview(URL.createObjectURL(file));
  }

  function formatTime(ts) {
    if (!ts?.toDate) return '';
    return ts.toDate().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false });
  }

  function formatLastMsg(ts) {
    if (!ts?.toDate) return '';
    const d = ts.toDate();
    const now = new Date();
    if (d.toDateString() === now.toDateString()) {
      return d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false });
    }
    return d.toLocaleDateString('en-US', { day: 'numeric', month: 'short' });
  }

  function formatDate(ts) {
    if (!ts?.toDate) return '';
    const d = ts.toDate();
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);
    if (d.toDateString() === today.toDateString()) return 'Today';
    if (d.toDateString() === yesterday.toDateString()) return 'Yesterday';
    return d.toLocaleDateString('en-US', { day: 'numeric', month: 'short', year: 'numeric' });
  }

  const filteredChats = chats.filter(c =>
    (c.userName || '').toLowerCase().includes(search.toLowerCase()) ||
    (c.userEmail || '').toLowerCase().includes(search.toLowerCase())
  );

  // Group messages by date
  const grouped = messages.reduce((acc, msg) => {
    const key = msg.createdAt?.toDate ? msg.createdAt.toDate().toDateString() : 'now';
    if (!acc[key]) acc[key] = { label: formatDate(msg.createdAt), msgs: [] };
    acc[key].msgs.push(msg);
    return acc;
  }, {});

  const isMe = (msg) => msg.senderRole === 'agent';

  return (
    <div style={{ display: 'flex', height: '100dvh', background: '#0a0e1a', overflow: 'hidden' }}>

      {/* ── Left Panel: Chat List ── */}
      <div style={{
        width: isMobile ? (selectedChat ? '0' : '100%') : '320px',
        minWidth: isMobile ? (selectedChat ? '0' : '100%') : '320px',
        maxWidth: isMobile ? '100%' : '320px',
        borderRight: '1px solid rgba(255,255,255,0.07)',
        display: 'flex',
        flexDirection: 'column',
        background: '#0d1117',
        overflow: 'hidden',
        transition: 'all 0.3s',
        flexShrink: 0,
      }}>
        {/* Header */}
        <div style={{ padding: '16px', borderBottom: '1px solid rgba(255,255,255,0.07)', flexShrink: 0 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '14px' }}>
            <button onClick={() => navigate('/admin')} style={{ background: 'rgba(255,255,255,0.07)', border: 'none', borderRadius: '50%', width: '34px', height: '34px', cursor: 'pointer', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <ChevronLeft size={18} />
            </button>
            <div>
              <div style={{ fontWeight: 700, fontSize: '16px' }}>Support Inbox</div>
              <div style={{ fontSize: '11px', color: 'var(--text-muted)' }}>{chats.length} conversation{chats.length !== 1 ? 's' : ''}</div>
            </div>
          </div>
          {/* Search */}
          <div style={{ background: 'rgba(255,255,255,0.06)', borderRadius: '10px', padding: '8px 12px', display: 'flex', alignItems: 'center', gap: '8px', border: '1px solid rgba(255,255,255,0.06)' }}>
            <Search size={15} color="var(--text-muted)" />
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Search users..."
              style={{ background: 'transparent', border: 'none', outline: 'none', color: '#fff', fontSize: '13px', flex: 1 }}
            />
          </div>
        </div>

        {/* Chat list */}
        <div style={{ flex: 1, overflowY: 'auto' }}>
          {filteredChats.length === 0 && (
            <div style={{ textAlign: 'center', color: 'var(--text-muted)', fontSize: '13px', padding: '40px 20px' }}>
              <MessageSquare size={32} style={{ opacity: 0.3, marginBottom: '8px' }} />
              <div>No conversations yet</div>
            </div>
          )}
          {filteredChats.map(chat => (
            <div
              key={chat.chatId}
              onClick={() => setSelectedChat(chat)}
              style={{
                display: 'flex', alignItems: 'center', gap: '12px', padding: '14px 16px',
                cursor: 'pointer', borderBottom: '1px solid rgba(255,255,255,0.04)',
                background: selectedChat?.chatId === chat.chatId ? 'rgba(16,185,129,0.08)' : 'transparent',
                borderLeft: selectedChat?.chatId === chat.chatId ? '3px solid #10b981' : '3px solid transparent',
                transition: 'background 0.15s',
              }}
            >
              {/* Avatar */}
              <div style={{ width: '44px', height: '44px', borderRadius: '50%', background: 'linear-gradient(135deg, #10b981, #059669)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, position: 'relative' }}>
                <User size={20} color="#fff" />
                {chat.unreadAdmin > 0 && (
                  <span style={{ position: 'absolute', top: '-2px', right: '-2px', width: '16px', height: '16px', background: '#ef4444', borderRadius: '50%', border: '2px solid #0d1117', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '9px', fontWeight: 700, color: '#fff' }}>
                    {chat.unreadAdmin > 9 ? '9+' : chat.unreadAdmin}
                  </span>
                )}
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '3px' }}>
                  <div style={{ fontWeight: 600, fontSize: '14px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {chat.userName || 'Unknown User'}
                  </div>
                  <div style={{ fontSize: '10px', color: 'var(--text-muted)', flexShrink: 0 }}>
                    {formatLastMsg(chat.lastMessageAt)}
                  </div>
                </div>
                <div style={{ fontSize: '12px', color: 'var(--text-muted)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                  {chat.lastMessage || 'No messages yet'}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* ── Right Panel: Chat Window ── */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden', minWidth: 0 }}>
        {!selectedChat ? (
          /* Empty state */
          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', color: 'var(--text-muted)' }}>
            <MessageSquare size={52} style={{ opacity: 0.2, marginBottom: '16px' }} />
            <div style={{ fontSize: '16px', fontWeight: 600, marginBottom: '6px' }}>Select a conversation</div>
            <div style={{ fontSize: '13px' }}>Choose a user from the left to start chatting</div>
          </div>
        ) : (
          <>
            {/* Chat header */}
            <div style={{ padding: '12px 16px', borderBottom: '1px solid rgba(255,255,255,0.07)', display: 'flex', alignItems: 'center', gap: '12px', background: '#0d1117', flexShrink: 0 }}>
              <button onClick={() => setSelectedChat(null)} style={{ background: 'rgba(255,255,255,0.07)', border: 'none', borderRadius: '50%', width: '34px', height: '34px', cursor: 'pointer', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <ChevronLeft size={18} />
              </button>
              <div style={{ width: '38px', height: '38px', borderRadius: '50%', background: 'linear-gradient(135deg, #10b981, #059669)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <User size={18} color="#fff" />
              </div>
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 700, fontSize: '15px' }}>{selectedChat.userName || 'User'}</div>
                <div style={{ fontSize: '11px', color: 'var(--text-muted)' }}>{selectedChat.userEmail}</div>
              </div>
              <div style={{ fontSize: '10px', color: '#10b981', background: 'rgba(16,185,129,0.1)', padding: '3px 8px', borderRadius: '20px', fontWeight: 600 }}>
                Support Chat
              </div>
            </div>

            {/* Messages */}
            <div style={{ flex: 1, overflowY: 'auto', padding: '16px', background: `radial-gradient(circle at 20% 20%, rgba(16,185,129,0.03) 0%, transparent 50%), #0a0e1a`, WebkitOverflowScrolling: 'touch' }}>
              {Object.values(grouped).map((group, gi) => (
                <div key={gi}>
                  <div style={{ textAlign: 'center', marginBottom: '12px' }}>
                    <span style={{ background: 'rgba(255,255,255,0.06)', borderRadius: '20px', padding: '3px 12px', fontSize: '11px', color: 'var(--text-muted)' }}>{group.label}</span>
                  </div>
                  {group.msgs.map(msg => (
                    <motion.div
                      key={msg.id}
                      initial={{ opacity: 0, y: 6 }}
                      animate={{ opacity: 1, y: 0 }}
                      style={{ display: 'flex', justifyContent: isMe(msg) ? 'flex-end' : 'flex-start', marginBottom: '4px', alignItems: 'flex-end', gap: '8px' }}
                    >
                      {!isMe(msg) && (
                        <div style={{ width: '28px', height: '28px', borderRadius: '50%', background: 'linear-gradient(135deg, #10b981,#059669)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                          <User size={14} color="#fff" />
                        </div>
                      )}
                      <div style={{ maxWidth: '70%' }}>
                        {msg.imageUrl && (
                          <div style={{ borderRadius: isMe(msg) ? '18px 18px 4px 18px' : '18px 18px 18px 4px', overflow: 'hidden', marginBottom: msg.text ? '2px' : 0, background: isMe(msg) ? 'linear-gradient(135deg,#10b981,#059669)' : 'rgba(255,255,255,0.08)' }}>
                            <img src={msg.imageUrl} alt="img" style={{ width: '100%', maxWidth: '240px', display: 'block', cursor: 'pointer' }} onClick={() => window.open(msg.imageUrl, '_blank')} />
                          </div>
                        )}
                        {msg.text && (
                          <div style={{ background: isMe(msg) ? 'linear-gradient(135deg,#10b981,#059669)' : 'rgba(255,255,255,0.08)', color: '#fff', padding: '10px 14px', borderRadius: isMe(msg) ? '18px 18px 4px 18px' : '18px 18px 18px 4px', fontSize: '14px', lineHeight: 1.5, wordBreak: 'break-word', border: !isMe(msg) ? '1px solid rgba(255,255,255,0.06)' : 'none' }}>
                            {!isMe(msg) && <div style={{ fontSize: '10px', fontWeight: 700, color: '#10b981', marginBottom: '4px' }}>{msg.senderName || 'User'}</div>}
                            {msg.text}
                          </div>
                        )}
                        <div style={{ display: 'flex', alignItems: 'center', gap: '4px', justifyContent: isMe(msg) ? 'flex-end' : 'flex-start', marginTop: '3px', paddingRight: isMe(msg) ? '4px' : '0' }}>
                          <span style={{ fontSize: '10px', color: 'var(--text-muted)' }}>{msg.createdAt ? formatTime(msg.createdAt) : '...'}</span>
                          {isMe(msg) && (msg.status === 'read' ? <CheckCheck size={12} color="#10b981" /> : <CheckCheck size={12} color="rgba(255,255,255,0.3)" />)}
                        </div>
                      </div>
                    </motion.div>
                  ))}
                </div>
              ))}
              <div ref={bottomRef} />
            </div>

            {/* Image preview */}
            <AnimatePresence>
              {imagePreview && (
                <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }}
                  style={{ background: 'rgba(255,255,255,0.04)', borderTop: '1px solid rgba(255,255,255,0.07)', padding: '10px 16px', display: 'flex', alignItems: 'center', gap: '12px' }}>
                  <div style={{ position: 'relative' }}>
                    <img src={imagePreview} alt="preview" style={{ height: '56px', borderRadius: '8px', objectFit: 'cover' }} />
                    <button onClick={clearImage} style={{ position: 'absolute', top: '-6px', right: '-6px', background: '#ef4444', border: 'none', borderRadius: '50%', width: '18px', height: '18px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff' }}>
                      <X size={10} />
                    </button>
                  </div>
                  {uploadProgress !== null && (
                    <div style={{ flex: 1 }}>
                      <div style={{ fontSize: '11px', color: 'var(--text-muted)', marginBottom: '4px' }}>Uploading... {uploadProgress}%</div>
                      <div style={{ height: '3px', background: 'rgba(255,255,255,0.1)', borderRadius: '2px' }}>
                        <div style={{ height: '100%', width: `${uploadProgress}%`, background: 'var(--primary)', borderRadius: '2px', transition: 'width 0.3s' }} />
                      </div>
                    </div>
                  )}
                </motion.div>
              )}
            </AnimatePresence>

            {/* Input bar */}
            <div style={{ background: 'rgba(13,17,23,0.98)', borderTop: '1px solid rgba(255,255,255,0.07)', padding: '10px 12px', display: 'flex', alignItems: 'flex-end', gap: '8px', flexShrink: 0 }}>
              <input ref={fileInputRef} type="file" accept="image/*" style={{ display: 'none' }} onChange={handleImageSelect} />
              <button onClick={() => fileInputRef.current?.click()} style={{ background: 'rgba(255,255,255,0.07)', border: 'none', borderRadius: '50%', width: '40px', height: '40px', cursor: 'pointer', color: 'var(--text-muted)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                <Image size={18} />
              </button>
              <div style={{ flex: 1, background: 'rgba(255,255,255,0.07)', borderRadius: '22px', padding: '10px 16px', border: '1px solid rgba(255,255,255,0.08)', display: 'flex', alignItems: 'center' }}>
                <textarea
                  value={text}
                  onChange={e => setText(e.target.value)}
                  onKeyDown={handleKeyDown}
                  placeholder="Reply as QTX Support..."
                  rows={1}
                  style={{ background: 'transparent', border: 'none', outline: 'none', color: '#fff', fontSize: '14px', width: '100%', resize: 'none', lineHeight: 1.5, maxHeight: '100px', overflowY: 'auto', fontFamily: 'inherit' }}
                />
              </div>
              <motion.button
                whileTap={{ scale: 0.9 }}
                onClick={sendMessage}
                disabled={sending || (!text.trim() && !imageFile)}
                style={{ background: (text.trim() || imageFile) ? 'linear-gradient(135deg, #10b981, #059669)' : 'rgba(255,255,255,0.07)', border: 'none', borderRadius: '50%', width: '42px', height: '42px', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: (text.trim() || imageFile) ? 'pointer' : 'default', color: '#fff', flexShrink: 0, transition: 'background 0.2s' }}
              >
                <Send size={18} style={{ marginLeft: '2px' }} />
              </motion.button>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { useAuth } from '../contexts/AuthContext';
import { useLanguage } from '../contexts/LanguageContext';
import { db } from '../firebase';
import { collection, onSnapshot, doc, getDoc, updateDoc, getDocs } from 'firebase/firestore';
import { Copy, Users, CheckCircle2, ChevronLeft, Trophy, TrendingUp, Gift } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useCurrency } from '../hooks/useCurrency';
import toast from 'react-hot-toast';

const TIERS = [
  { level: 1, label: 'Direct Referral', pct: 10, color: 'var(--warning)', bg: 'rgba(212,175,55,0.1)', icon: Trophy },
  { level: 2, label: 'Level 2 Network', pct: 3, color: 'var(--primary)', bg: 'rgba(16,185,129,0.1)', icon: TrendingUp },
  { level: 3, label: 'Level 3 Network', pct: 1, color: '#a855f7', bg: 'rgba(168,85,247,0.1)', icon: Gift },
];

export const Affiliate = () => {
  const { currentUser } = useAuth();
  const { t } = useLanguage();
  const { convertAndFormatCurrency } = useCurrency();
  const navigate = useNavigate();
  const [totalEarned, setTotalEarned] = useState(0);
  const [referralsCount, setReferralsCount] = useState(0);
  const [copied, setCopied] = useState(false);
  const [referralCode, setReferralCode] = useState('');
  const [earningsByTier, setEarningsByTier] = useState({ 1: 0, 2: 0, 3: 0 });
  const [networkUsers, setNetworkUsers] = useState([]);
  const [activeReferralIds, setActiveReferralIds] = useState(new Set());
  const [loadingNetwork, setLoadingNetwork] = useState(true);
  const referralLink = `https://qtxcoin1.vercel.app/login?ref=${referralCode}`;
  useEffect(() => {
    if (!currentUser) return;

    const fetchReferralCode = async () => {
      const userDocRef = doc(db, 'users', currentUser.uid);
      const userDoc = await getDoc(userDocRef);
      if (userDoc.exists()) {
        let code = userDoc.data().referralCode;
        if (!code) {
          code = Math.random().toString(36).substring(2, 8).toUpperCase();
          await updateDoc(userDocRef, { referralCode: code });
        }
        setReferralCode(code);
      }
    };
    fetchReferralCode();

    const fetchNetwork = async (code) => {
      try {
        const usersSnap = await getDocs(collection(db, 'users'));
        const allUsers = usersSnap.docs.map(d => ({ id: d.id, ...d.data() }));

        const lvl1 = allUsers.filter(u => u.referredByCode === code);
        const lvl1Codes = new Set(lvl1.map(u => u.referralCode).filter(Boolean));
        
        const lvl2 = allUsers.filter(u => lvl1Codes.has(u.referredByCode));
        const lvl2Codes = new Set(lvl2.map(u => u.referralCode).filter(Boolean));

        const lvl3 = allUsers.filter(u => lvl2Codes.has(u.referredByCode));

        const mapped = [
          ...lvl1.map(u => ({ ...u, level: 1 })),
          ...lvl2.map(u => ({ ...u, level: 2 })),
          ...lvl3.map(u => ({ ...u, level: 3 }))
        ];
        
        // Sort by level ascending, then by creation date descending
        mapped.sort((a, b) => {
          if (a.level !== b.level) return a.level - b.level;
          const aTime = a.createdAt ? new Date(a.createdAt).getTime() : 0;
          const bTime = b.createdAt ? new Date(b.createdAt).getTime() : 0;
          return bTime - aTime;
        });

        setNetworkUsers(mapped);
      } catch (err) {
        console.error('Failed to fetch network:', err);
      }
      setLoadingNetwork(false);
    };

    if (referralCode) {
      fetchNetwork(referralCode);
    }

    // Listen to all transactions, filter in JS (avoids Firestore index requirement)
    const qRewards = collection(db, 'users', currentUser.uid, 'transactions');
    const unsubRewards = onSnapshot(qRewards, (snapshot) => {
      let earned = 0;
      const byTier = { 1: 0, 2: 0, 3: 0 };
      let count = 0;
      let activeSet = new Set();
      snapshot.forEach(d => {
        const data = d.data();
        if (data.type !== 'affiliate_reward') return;
        count++;
        if (data.fromUid) activeSet.add(data.fromUid);
        earned += data.amount || 0;
        if (data.title?.includes('Level 1')) byTier[1] += data.amount || 0;
        else if (data.title?.includes('Level 2')) byTier[2] += data.amount || 0;
        else if (data.title?.includes('Level 3')) byTier[3] += data.amount || 0;
      });
      setTotalEarned(earned);
      setEarningsByTier(byTier);
      setReferralsCount(count);
      setActiveReferralIds(activeSet);
    });

    return unsubRewards;
  }, [currentUser, referralCode]);

  const handleCopy = () => {
    navigator.clipboard.writeText(referralLink);
    setCopied(true);
    toast.success(t('successLinkCopied'));
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <motion.div
      className="page-content"
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      transition={{ duration: 0.3 }}
      style={{ padding: '16px', paddingBottom: '80px' }}
    >
      {/* HEADER */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '20px' }}>
        <button
          onClick={() => navigate(-1)}
          style={{ background: 'var(--bg-panel)', border: '1px solid var(--border)', borderRadius: '8px', padding: '6px', color: '#fff', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
        >
          <ChevronLeft size={20} />
        </button>
        <h2 style={{ margin: 0, fontSize: '18px', fontWeight: 700 }}>{t('affiliateTitle')}</h2>
      </div>

      {/* HERO CARD */}
      <div style={{ background: 'linear-gradient(135deg, rgba(212,175,55,0.15), rgba(16,185,129,0.08))', borderRadius: '20px', padding: '24px 20px', border: '1px solid rgba(212,175,55,0.3)', marginBottom: '20px', textAlign: 'center', boxShadow: '0 8px 30px rgba(0,0,0,0.3)' }}>
        <Users size={48} color="var(--warning)" style={{ margin: '0 auto 12px', display: 'block' }} />
        <h3 style={{ margin: '0 0 8px 0', fontSize: '22px', fontWeight: 800, color: 'var(--warning)' }}>{t('inviteEarn')}</h3>
        <p style={{ color: 'var(--text-secondary)', fontSize: '13px', margin: '0 0 20px 0', lineHeight: 1.6 }}>
          {t('affiliateDesc')}
        </p>

        {/* Referral Link */}
        <div style={{ background: 'var(--bg-dark)', padding: '12px 14px', borderRadius: '10px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', border: '1px solid var(--border)', gap: '8px' }}>
          <span style={{ fontSize: '11px', wordBreak: 'break-all', fontFamily: 'monospace', color: 'var(--text-secondary)', textAlign: 'left', flex: 1 }}>
            {referralCode ? referralLink : t('generatingLink')}
          </span>
          <button
            onClick={handleCopy}
            disabled={!referralCode}
            style={{ color: copied ? 'var(--success)' : 'var(--warning)', padding: '8px', background: 'rgba(212,175,55,0.1)', borderRadius: '8px', border: '1px solid rgba(212,175,55,0.2)', cursor: referralCode ? 'pointer' : 'not-allowed', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}
          >
            {copied ? <CheckCircle2 size={18} /> : <Copy size={18} />}
          </button>
        </div>
      </div>


      {/* STATS ROW */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px', marginBottom: '20px' }}>
        <div style={{ background: 'var(--bg-panel)', borderRadius: '14px', padding: '16px', textAlign: 'center', border: '1px solid var(--border)' }}>
          <p style={{ margin: '0 0 6px 0', fontSize: '11px', color: 'var(--text-muted)' }}>{t('totalEarned')}</p>
          <p style={{ margin: 0, fontSize: '22px', fontWeight: 800, color: 'var(--success)' }}>{convertAndFormatCurrency(totalEarned)}</p>
        </div>
        <div style={{ background: 'var(--bg-panel)', borderRadius: '14px', padding: '16px', textAlign: 'center', border: '1px solid var(--border)' }}>
          <p style={{ margin: '0 0 6px 0', fontSize: '11px', color: 'var(--text-muted)' }}>{t('commissions')}</p>
          <p style={{ margin: 0, fontSize: '22px', fontWeight: 800, color: 'var(--primary)' }}>{referralsCount}</p>
        </div>
      </div>

      {/* 3-TIER BREAKDOWN */}
      <h4 style={{ margin: '0 0 12px 0', fontSize: '14px', color: 'var(--text-secondary)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '1px' }}>{t('commissionStructure')}</h4>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', marginBottom: '20px' }}>
        {TIERS.map((tier) => {
          const Icon = tier.icon;
          return (
            <motion.div
              key={tier.level}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: tier.level * 0.08 }}
              style={{ background: 'var(--bg-panel)', borderRadius: '14px', padding: '16px', border: `1px solid ${tier.color}30`, display: 'flex', alignItems: 'center', gap: '14px' }}
            >
              <div style={{ width: '44px', height: '44px', borderRadius: '12px', background: tier.bg, border: `1px solid ${tier.color}50`, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                <Icon size={20} color={tier.color} />
              </div>
              <div style={{ flex: 1 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '4px' }}>
                  <span style={{ fontSize: '13px', fontWeight: 700, color: '#fff' }}>Level {tier.level} – {tier.label}</span>
                  <span style={{ fontSize: '18px', fontWeight: 900, color: tier.color }}>{tier.pct}%</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ fontSize: '11px', color: 'var(--text-muted)' }}>{t('perDepositApproved')}</span>
                  <span style={{ fontSize: '12px', fontWeight: 600, color: 'var(--success)' }}>{convertAndFormatCurrency(earningsByTier[tier.level])} {t('earned')}</span>
                </div>

                {/* progress bar */}
                <div style={{ marginTop: '8px', height: '3px', background: 'var(--bg-dark)', borderRadius: '2px', overflow: 'hidden' }}>
                  <div style={{ height: '100%', width: `${Math.min(100, (earningsByTier[tier.level] / Math.max(totalEarned, 1)) * 100)}%`, background: tier.color, borderRadius: '2px', transition: 'width 1s ease' }} />
                </div>
              </div>
            </motion.div>
          );
        })}
      </div>

      {/* HOW IT WORKS */}
      <div style={{ background: 'var(--bg-panel)', borderRadius: '16px', padding: '20px', border: '1px solid var(--border)' }}>
        <h4 style={{ margin: '0 0 14px 0', fontSize: '14px', fontWeight: 700 }}>{t('howItWorks')}</h4>
        {[
          { step: '1', text: t('affiliateStep1') },
          { step: '2', text: t('affiliateStep2') },
          { step: '3', text: t('affiliateStep3') },
          { step: '4', text: t('affiliateStep4') },
          { step: '5', text: t('affiliateStep5') },
        ].map((item) => (
          <div key={item.step} style={{ display: 'flex', gap: '12px', alignItems: 'flex-start', marginBottom: '12px' }}>
            <div style={{ width: '24px', height: '24px', borderRadius: '50%', background: 'rgba(212,175,55,0.15)', border: '1px solid rgba(212,175,55,0.3)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, fontSize: '11px', fontWeight: 700, color: 'var(--warning)' }}>
              {item.step}
            </div>
            <p style={{ margin: 0, fontSize: '13px', color: 'var(--text-secondary)', lineHeight: 1.5 }}>{item.text}</p>
          </div>
        ))}
      </div>

      {/* NETWORK USERS TABLE */}
      <h4 style={{ margin: '0 0 12px 0', fontSize: '14px', color: 'var(--text-secondary)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '1px' }}>{t('Referral Network')}</h4>
      <div style={{ background: 'var(--bg-panel)', borderRadius: '16px', border: '1px solid var(--border)', overflow: 'hidden', marginBottom: '20px' }}>
        {loadingNetwork ? (
           <div style={{ padding: '24px', textAlign: 'center', color: 'var(--text-muted)', fontSize: '13px' }}>Loading network data...</div>
        ) : networkUsers.length === 0 ? (
           <div style={{ padding: '24px', textAlign: 'center', color: 'var(--text-muted)', fontSize: '13px' }}>No referrals found in your network yet. Share your code!</div>
        ) : (
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '13px' }}>
            <thead>
              <tr style={{ background: 'rgba(255,255,255,0.02)', color: 'var(--text-muted)' }}>
                <th style={{ padding: '14px 16px', fontWeight: 600, borderBottom: '1px solid var(--border)', borderLeft: 'none', borderRight: 'none' }}>User</th>
                <th style={{ padding: '14px 16px', fontWeight: 600, borderBottom: '1px solid var(--border)', borderLeft: 'none', borderRight: 'none' }}>Level</th>
                <th style={{ padding: '14px 16px', fontWeight: 600, borderBottom: '1px solid var(--border)', borderLeft: 'none', borderRight: 'none', textAlign: 'right' }}>Status</th>
              </tr>
            </thead>
            <tbody>
              {networkUsers.map((u) => {
                const isActive = activeReferralIds.has(u.id);
                return (
                  <tr key={u.id} style={{ borderBottom: '1px solid var(--border)', transition: 'background-color 0.2s', ':hover': { backgroundColor: 'rgba(255,255,255,0.02)' } }}>
                    <td style={{ padding: '12px 16px', color: '#fff', maxWidth: '140px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', borderLeft: 'none', borderRight: 'none' }}>
                      {u.phone || u.email}
                    </td>
                    <td style={{ padding: '12px 16px', color: 'var(--text-secondary)', borderLeft: 'none', borderRight: 'none' }}>
                      Lvl {u.level}
                    </td>
                    <td style={{ padding: '12px 16px', textAlign: 'right', borderLeft: 'none', borderRight: 'none' }}>
                      <span style={{ 
                        background: isActive ? 'rgba(16,185,129,0.1)' : 'rgba(244,63,94,0.1)', 
                        color: isActive ? 'var(--success)' : 'var(--danger)', 
                        padding: '4px 8px', 
                        borderRadius: '6px', 
                        fontSize: '11px', 
                        fontWeight: 600 
                      }}>
                        {isActive ? 'Active' : 'Inactive'}
                      </span>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      {/* REFERRAL CHAIN DIAGRAM */}
      <div style={{ marginTop: '20px', borderRadius: '14px', overflow: 'hidden', border: '1px solid rgba(212,175,55,0.3)', boxShadow: '0 4px 20px rgba(0,0,0,0.4)' }}>
        <img src="/images/referral_chain.png" alt="3-Tier Referral Commission Chain" style={{ width: '100%', display: 'block' }} />
      </div>
    </motion.div>
  );
};

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import { ChevronLeft, Wallet, Database, Briefcase, Gem, ArrowRightLeft } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { useCurrency } from '../hooks/useCurrency';

export const Assets = () => {
  const navigate = useNavigate();
  const { balance, miningBalance, investmentBalance, qtxBalance } = useAuth();
  const { formatCurrency, convertAndFormatSmallCurrency, convertAndFormatCurrency, rate } = useCurrency();
  
  const [qtxPrice, setQtxPrice] = useState(0);
  const [loadingPrice, setLoadingPrice] = useState(true);

  useEffect(() => {
    const fetchPrice = async () => {
      try {
        const res = await fetch('https://api.coingecko.com/api/v3/simple/price?ids=quantumx&vs_currencies=usd');
        const data = await res.json();
        if (data.quantumx && data.quantumx.usd) {
          setQtxPrice(data.quantumx.usd);
        }
      } catch (err) {
        console.log('Error fetching price', err);
      } finally {
        setLoadingPrice(false);
      }
    };
    fetchPrice();
    const interval = setInterval(fetchPrice, 60000); // 1 min update
    return () => clearInterval(interval);
  }, []);

  const totalUSDWallets = (balance || 0) + (miningBalance || 0) + (investmentBalance || 0);
