                  <h3 style={{ margin: 0, fontSize: '15px', fontWeight: 600, color: '#fff' }}>{profile.name}</h3>
                  <ShieldCheck size={14} color="var(--primary)" />
                </div>
                <p style={{ margin: 0, fontSize: '11px', color: 'var(--text-secondary)', marginBottom: '8px' }}>
                  {profile.age} • {profile.location}
                </p>
                <div style={{ display: 'flex', gap: '10px' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '4px', background: 'var(--bg-dark)', padding: '4px 8px', borderRadius: '6px' }}>
                    <Clock size={12} color="var(--text-muted)" />
                    <span style={{ fontSize: '11px', color: 'var(--text-primary)', fontWeight: 500 }}>{profile.chatTime}</span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '4px', background: 'rgba(16,185,129,0.1)', padding: '4px 8px', borderRadius: '6px' }}>
                    <DollarSign size={12} color="var(--success)" />
                    <span style={{ fontSize: '11px', color: 'var(--success)', fontWeight: 700 }}>{formatCurrency(profile.rewardAmount)}</span>
                  </div>
                </div>
              </div>

            </div>

            <button 
              onClick={() => handleStartChatProcess(profile)}
              style={{ 
                width: '100%', border: 'none', borderTop: '1px solid var(--border)', 
                background: 'linear-gradient(135deg, #a855f7, #6366f1)', 
                color: '#fff', padding: '12px', fontSize: '13px', fontWeight: 700, cursor: 'pointer',
                display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px'
              }}
            >
              Start Chat
            </button>
          </div>
        ))}
      </div>

      <AnimatePresence>
        {selectedProfile && (
          <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', zIndex: 1000, display: 'flex', alignItems: 'flex-end', justifyContent: 'center', backdropFilter: 'blur(4px)' }} onClick={() => !loading && setSelectedProfile(null)}>
            <motion.div
              initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} transition={{ type: 'spring', damping: 25, stiffness: 300 }}
              onClick={e => e.stopPropagation()}
              style={{ background: 'var(--bg-panel)', borderRadius: '32px 32px 0 0', maxWidth: '500px', width: '100%', border: '1px solid var(--border)', overflow: 'hidden', boxShadow: '0 -10px 40px rgba(0,0,0,0.5)', paddingBottom: '20px' }}
            >
              <div style={{ padding: '12px 0', cursor: 'grab' }}>
                <div style={{ width: '40px', height: '4px', background: 'rgba(255,255,255,0.2)', borderRadius: '2px', margin: '0 auto' }} />
              </div>

              <div style={{ padding: '0 24px' }}>
                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', textAlign: 'center', marginBottom: '20px' }}>
                  <img src={selectedProfile.avatar} alt={selectedProfile.name} style={{ width: '80px', height: '80px', borderRadius: '50%', objectFit: 'cover', border: '3px solid var(--primary)', marginBottom: '12px' }} />
                  <h3 style={{ margin: '0 0 6px 0', fontSize: '1.4rem', fontWeight: 800, color: '#fff' }}>Chat with {selectedProfile.name}</h3>
                  <p style={{ margin: 0, color: 'var(--text-secondary)', fontSize: '0.95rem' }}>
                    Connect and chat for {selectedProfile.chatTime} to unlock your {formatCurrency(selectedProfile.rewardAmount)} reward.
                  </p>
                </div>

                <div style={{ background: 'var(--bg-dark)', padding: '16px', borderRadius: '16px', marginBottom: '24px', border: '1px solid rgba(255,255,255,0.05)' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.9rem', marginBottom: '12px' }}>
                    <span style={{ color: 'var(--text-secondary)' }}><Clock size={14} style={{ display: 'inline', verticalAlign: 'text-bottom', marginRight: '4px' }} /> Chat Requirement</span>
                    <strong style={{ color: '#fff' }}>{selectedProfile.chatTime}</strong>
                  </div>
                  <div style={{ height: '1px', background: 'rgba(255,255,255,0.06)', margin: '8px 0' }} />
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.9rem', marginTop: '12px' }}>
                    <span style={{ color: 'var(--text-secondary)' }}><DollarSign size={14} style={{ display: 'inline', verticalAlign: 'text-bottom', marginRight: '4px' }} /> Earning Reward</span>
                    <strong style={{ color: 'var(--success)', fontSize: '1.2rem', fontWeight: 800 }}>{formatCurrency(selectedProfile.rewardAmount)}</strong>
                  </div>
                </div>

                <div style={{ display: 'flex', gap: '12px' }}>
                  <button onClick={() => setSelectedProfile(null)} disabled={loading} style={{ flex: 1, padding: '16px', borderRadius: '16px', background: 'var(--bg-dark)', border: '1px solid var(--border)', color: 'var(--text-primary)', fontWeight: 600, cursor: 'pointer', fontSize: '1rem', opacity: loading ? 0.5 : 1 }}>
                    Cancel
                  </button>
                  <button 
                    onClick={confirmChatStart}
                    disabled={loading}
                    style={{ flex: 1, padding: '16px', borderRadius: '16px', border: 'none', background: 'linear-gradient(135deg, #a855f7, #6366f1)', color: '#fff', fontSize: '1rem', fontWeight: 700, cursor: 'pointer', boxShadow: '0 4px 15px rgba(168,85,247,0.3)', opacity: loading ? 0.7 : 1 }}
                  >
                    {loading ? 'Connecting...' : 'Initiate Chat'}
                  </button>
                </div>
              </div>
            </motion.div>
          </div>
        )}

        {/* --- Success Bottom Sheet --- */}
        {successData && (
          <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', zIndex: 2000, display: 'flex', alignItems: 'flex-end', backdropFilter: 'blur(4px)' }} onClick={() => setSuccessData(null)}>
            <motion.div
              initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} transition={{ type: 'spring', damping: 25, stiffness: 300 }}
              onClick={e => e.stopPropagation()}
              style={{ width: '100%', background: 'var(--bg-panel)', borderTop: '1px solid var(--border)', borderRadius: '32px 32px 0 0', padding: '24px 24px 40px', boxShadow: '0 -10px 40px rgba(0,0,0,0.5)' }}
            >
              <div style={{ width: '40px', height: '4px', background: 'rgba(255,255,255,0.2)', borderRadius: '2px', margin: '0 auto 24px' }} />

              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', textAlign: 'center', marginBottom: '24px' }}>
                <div style={{ width: '64px', height: '64px', borderRadius: '50%', background: 'rgba(16, 185, 129, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '16px' }}>
                  <CheckCircle2 size={32} color="var(--success)" />
                </div>
                <h3 style={{ margin: '0 0 6px 0', fontSize: '1.4rem', fontWeight: 800, color: '#fff' }}>{successData.title}</h3>
                <p style={{ margin: 0, color: 'var(--text-secondary)', fontSize: '0.95rem' }}>{successData.message}</p>
              </div>

              <div style={{ background: 'var(--bg-dark)', padding: '16px', borderRadius: '16px', marginBottom: '24px', border: '1px dashed rgba(255,255,255,0.1)' }}>
                <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '1px', marginBottom: '16px', fontWeight: 700 }}>Session Details</p>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
                  {successData.details.map((item, i) => (
                    <div key={i} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.9rem' }}>
                      <span style={{ color: 'var(--text-secondary)' }}>{item.label}</span>
                      <strong style={{ color: item.color || '#fff' }}>{item.value}</strong>
                    </div>
                  ))}
                  <div style={{ height: '1px', background: 'rgba(255,255,255,0.06)', margin: '4px 0' }} />
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.9rem' }}>
                    <span style={{ color: 'var(--text-secondary)' }}>Status</span>
                    <strong style={{ color: 'var(--warning)' }}>In Progress</strong>
                  </div>
                </div>
              </div>

              <button onClick={() => setSuccessData(null)} style={{ width: '100%', padding: '16px', borderRadius: '16px', border: 'none', background: 'linear-gradient(135deg, #10B981, #059669)', color: '#fff', fontSize: '1.05rem', fontWeight: 700, cursor: 'pointer', boxShadow: '0 4px 15px rgba(16,185,129,0.3)' }}>Go to Active Chats</button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useLanguage } from '../contexts/LanguageContext';
import { useCurrency } from '../hooks/useCurrency';
import { Bell, ArrowRight, ArrowDownToLine, Send, Crown, Gift, HelpCircle, UserPlus, Building, Smartphone, Globe, Bot, ShieldCheck, Check, MessageCircle, Coins, Gem, Loader2 } from 'lucide-react';
import { LiveTransactions } from '../components/LiveTransactions';
import { DashboardCharts } from '../components/DashboardCharts';
import { SpinPromoPopup } from '../components/SpinPromoPopup';

export const Dashboard = () => {
  const { currentUser, userData, balance, miningBalance, investmentBalance, qtxBalance, welcomeBonus } = useAuth();
  const { language, changeLanguage, t } = useLanguage();
  const { formatCurrency, convertAndFormatCurrency, rate } = useCurrency();
  const navigate = useNavigate();
  const [langOpen, setLangOpen] = useState(false);
  const langRef = useRef(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handler = (e) => {
      if (langRef.current && !langRef.current.contains(e.target)) {
        setLangOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const LANGUAGES = [
    { code: 'en', label: 'English', flag: '🇬🇧' },
    { code: 'pt', label: 'Português', flag: '🇧🇷' },
  ];

  // Wallet values mapped directly from Firestore
  const profitWallet = balance || 0;
  const miningWallet = miningBalance || 0;
  const CRYPTO_RATES = { doge: 6.25, ada: 6.5, matic: 7, xrp: 7.5, link: 8, dot: 8.5, avax: 9, sol: 10, eth: 11, btc: 12 };
  const activeCrypto = userData?.activatedCrypto?.filter(c => c.status === 'running') || [];
  const cryptoInvestments = activeCrypto.reduce((sum, c) => sum + parseFloat(c.price || 0), 0);
  const pendingPayout = activeCrypto.reduce((sum, c) => {
    const price = parseFloat(c.price || 0);
    const pct = CRYPTO_RATES[c.id] || parseFloat(c.dailyPercent || 0);
    return sum + (price * pct / 100);
  }, 0);
  const investmentWallet = (investmentBalance || 0) + cryptoInvestments;
  const totalAssets = profitWallet + miningWallet + investmentWallet;
  
  const unreadNotificationsCount = userData?.notifications?.filter(n => !n.read).length || 0;
  const hasRunningBots = userData?.activatedBots?.some(bot => bot.status === 'running');

  const currentLang = LANGUAGES.find(l => l.code === language) || LANGUAGES[0];

  return (
    <motion.div 
      className="page-content"
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      transition={{ duration: 0.3 }}
      style={{ padding: '8px 12px' }}
    >
      {/* Home-page promo popup — fires on every load */}
      <SpinPromoPopup />
      {/* HEADER */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }} onClick={() => navigate('/account')} className="cursor-pointer">
          <div style={{ 
            position: 'relative', 
            width: '48px', 
            height: '48px', 
            borderRadius: '50%', 
            display: 'flex', 
            alignItems: 'center', 
            justifyContent: 'center',
            boxShadow: hasRunningBots ? '0 0 15px rgba(16, 185, 129, 0.6)' : 'none'
          }}>
            {hasRunningBots && (
              <div style={{
                position: 'absolute',
                inset: 0,
                borderRadius: '50%',
                background: 'conic-gradient(from 0deg, transparent 0 160deg, rgba(16,185,129,0.4) 220deg, #10b981 310deg, #059669 360deg)',
                animation: 'spin 2s linear infinite',
                zIndex: 0
              }} />
            )}
            <div style={{ 
              width: '40px', 
              height: '40px', 
              borderRadius: '50%', 
              background: 'var(--primary)', 
              display: 'flex', 
              alignItems: 'center', 
              justifyContent: 'center', 
              overflow: 'hidden', 
              border: hasRunningBots ? '2px solid var(--bg-dark)' : '2px solid var(--primary)',
              zIndex: 1,
              position: 'relative'
            }}>
              {userData?.photoURL ? (
                <img src={userData.photoURL} alt="Profile" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
              ) : (
                <span style={{ color: '#000', fontWeight: 'bold', fontSize: '18px' }}>
                  {currentUser?.email?.charAt(0).toUpperCase() || 'M'}
                </span>
              )}
            </div>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
            <img src="/logo.png" alt="Logo" style={{ height: '24px', width: 'auto', objectFit: 'contain' }} />
            <h3 style={{ margin: 0, letterSpacing: '1px', fontSize: '18px', color: 'var(--text-primary)' }}>QTX Coin</h3>
            {/* Bell notification — placed next to company name */}
            <div onClick={() => navigate('/notifications')} style={{ position: 'relative', cursor: 'pointer', padding: '4px', marginLeft: '4px' }}>
              <Bell size={18} color="var(--primary)" />
              {unreadNotificationsCount > 0 && (
                <span style={{ position: 'absolute', top: 0, right: 0, background: 'red', color: 'white', borderRadius: '50%', width: '14px', height: '14px', fontSize: '9px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold' }}>
                  {unreadNotificationsCount}
                </span>
              )}
            </div>
          </div>
        </div>
        
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          {/* LANGUAGE SWITCHER only — Bell moved to left side next to logo */}

          {/* LANGUAGE SWITCHER */}
          <div ref={langRef} style={{ position: 'relative' }}>
            <div
              onClick={() => setLangOpen(prev => !prev)}
              style={{
                background: langOpen ? 'var(--primary-glow)' : 'var(--bg-panel)',
                padding: '6px 10px',
                borderRadius: '20px',
                fontSize: '12px',
                display: 'flex',
                alignItems: 'center',
                gap: '5px',
                border: `1px solid ${langOpen ? 'var(--primary)' : 'var(--border)'}`,
                cursor: 'pointer',
                transition: 'all 0.2s ease',
                userSelect: 'none'
              }}
            >
              <Globe size={13} color="var(--primary)" />
              <span style={{ fontWeight: 500 }}>{currentLang.flag} {currentLang.label}</span>
              <span style={{
                fontSize: '8px',
                color: 'var(--text-muted)',
                display: 'inline-block',
                transition: 'transform 0.2s',
                transform: langOpen ? 'rotate(180deg)' : 'rotate(0deg)'
              }}>▼</span>
            </div>

            <AnimatePresence>
              {langOpen && (
                <motion.div
                  initial={{ opacity: 0, y: -6, scale: 0.95 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={{ opacity: 0, y: -6, scale: 0.95 }}
                  transition={{ duration: 0.15 }}
                  style={{
                    position: 'absolute',
                    top: 'calc(100% + 6px)',
                    right: 0,
                    background: 'var(--bg-panel)',
                    border: '1px solid var(--border)',
                    borderRadius: '12px',
                    overflow: 'hidden',
                    minWidth: '150px',
                    zIndex: 1000,
                    boxShadow: '0 8px 24px rgba(0,0,0,0.45)'
                  }}
                >
                  <div style={{ padding: '8px 12px 4px', fontSize: '9px', color: 'var(--text-muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.5px' }}>
                    {t('selectLanguage')}
                  </div>
                  {LANGUAGES.map(lang => (
                    <div
                      key={lang.code}
                      onClick={() => { changeLanguage(lang.code); setLangOpen(false); }}
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        padding: '10px 12px',
                        cursor: 'pointer',
                        fontSize: '13px',
                        fontWeight: language === lang.code ? 600 : 400,
                        color: language === lang.code ? 'var(--primary)' : 'var(--text-primary)',
                        background: language === lang.code ? 'var(--primary-glow)' : 'transparent',
                        transition: 'background 0.15s'
                      }}
                    >
                      <span>{lang.flag} {lang.label}</span>
                      {language === lang.code && <Check size={12} color="var(--primary)" />}
                    </div>
                  ))}
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </div>
      </div>

      {/* ALERT */}
      <style>{`
        @keyframes dashSpin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
        @keyframes ringBell {
          0% { transform: rotate(0deg); }
          10% { transform: rotate(15deg); }
          20% { transform: rotate(-15deg); }
          30% { transform: rotate(10deg); }
          40% { transform: rotate(-10deg); }
          50% { transform: rotate(5deg); }
          60% { transform: rotate(-5deg); }
          70%, 100% { transform: rotate(0deg); }
        }
        @keyframes marqueeScroll {
          0% { transform: translateX(0); }
          100% { transform: translateX(-100%); }
        }
      `}</style>
      <div style={{ background: 'linear-gradient(90deg, #ff4d4d, #ff8c00)', padding: '8px 10px', borderRadius: '8px', marginBottom: '16px', fontSize: '11px', display: 'flex', alignItems: 'center', color: 'white', fontWeight: 500, boxShadow: '0 2px 8px rgba(255, 140, 0, 0.2)' }}>
        <Bell size={14} style={{ flexShrink: 0, marginRight: '8px' }} />
        <div style={{ flex: 1, overflow: 'hidden', whiteSpace: 'nowrap', position: 'relative' }}>
          <motion.div 
            animate={{ x: [ '100%', '-100%' ] }}
            transition={{ duration: 15, repeat: Infinity, ease: 'linear' }}
            style={{ display: 'inline-block', lineHeight: 1.1 }}
          >
            {t('certified')}
          </motion.div>
        </div>
      </div>

      {/* WELCOME BONUS SECTION */}
      <motion.div 
        animate={{ scale: [1, 1.015, 1], boxShadow: ['0 4px 15px rgba(168, 85, 247, 0.2)', '0 4px 20px rgba(168, 85, 247, 0.45)', '0 4px 15px rgba(168, 85, 247, 0.2)'] }}
        transition={{ duration: 3, repeat: Infinity, ease: 'easeInOut' }}
        style={{ background: 'linear-gradient(135deg, #a855f7, #ec4899)', borderRadius: '12px', padding: '14px 16px', marginBottom: '16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', color: '#fff' }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <div style={{ width: '36px', height: '36px', borderRadius: '50%', background: 'rgba(255,255,255,0.2)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <Gift size={20} color="#fff" />
          </div>
          <div>
            <h3 style={{ margin: 0, fontSize: '12px', fontWeight: 600, opacity: 0.9, letterSpacing: '0.5px', textTransform: 'uppercase' }}>Welcome Bonus</h3>
            <p style={{ margin: 0, fontSize: '10px', opacity: 0.8 }}>Available to withdraw</p>
          </div>
        </div>
        <div style={{ fontSize: '22px', fontWeight: 800, textShadow: '0 2px 10px rgba(0,0,0,0.2)', fontVariantNumeric: 'tabular-nums' }}>
          {formatCurrency(welcomeBonus || 0)}
        </div>
      </motion.div>

      {/* CARD */}
      <div style={{ 
        background: 'linear-gradient(135deg, #d4af37, #f5d98b)', 
        borderRadius: '14px', 
        padding: '2px', 
        marginBottom: '14px', 
        boxShadow: '0 8px 25px rgba(212,175,55,0.35)' 
      }}>
        <div style={{ 
          background: 'linear-gradient(135deg, #141414, #1f1f1f)', 
          borderRadius: '12px', 
          padding: '16px', 
          height: '100%' 
        }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
            <h2 style={{ fontSize: '12px', color: '#ccc', margin: 0, fontWeight: 500, display: 'flex', alignItems: 'center', gap: '6px' }}>
              <Wallet size={14} color="#f5d98b" /> {t('withdrawableBalance')}
            </h2>
            <div style={{ color: '#f5d98b', fontSize: '20px', fontWeight: 'bold', textShadow: '0 2px 10px rgba(212,175,55,0.4)' }}>
              {convertAndFormatCurrency(profitWallet)}
            </div>
          </div>

          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', margin: '6px 0', paddingBottom: '6px', borderBottom: '1px solid rgba(255,255,255,0.06)' }}>
            <span style={{ color: 'var(--text-secondary)', display: 'flex', alignItems: 'center', gap: '4px' }}>
              <Server size={11} /> {t('miningWallet')}
            </span>
            <span style={{ fontWeight: 600, color: '#fff' }}>{convertAndFormatCurrency(miningWallet)}</span>
          </div>

          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', margin: '6px 0', paddingBottom: '6px', borderBottom: '1px solid rgba(255,255,255,0.06)' }}>
            <span style={{ color: 'var(--text-secondary)', display: 'flex', alignItems: 'center', gap: '4px' }}>
              <TrendingUp size={11} /> {t('investmentWallet')}
            </span>
            <span style={{ fontWeight: 600, color: '#fff' }}>{convertAndFormatCurrency(investmentWallet)}</span>
          </div>

          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', margin: '6px 0 0 0', paddingTop: '2px' }}>
            <span style={{ color: 'var(--text-secondary)', display: 'flex', alignItems: 'center', gap: '4px' }}>
              <Gift size={11} color="var(--success)" /> Welcome Bonus
            </span>
            <span style={{ fontWeight: 700, color: 'var(--success)' }}>
              {userData?.country === 'Malawi' ? `${(userData.welcomeBonus * 1700).toLocaleString(undefined, { maximumFractionDigits: 0 })} MWK` : convertAndFormatCurrency(userData?.welcomeBonus || (15000 / 1700))}
            </span>
          </div>

          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', margin: '6px 0 0 0', paddingTop: '6px', borderTop: '1px solid rgba(255,255,255,0.06)' }}>
            <span style={{ color: 'var(--text-secondary)', display: 'flex', alignItems: 'center', gap: '4px' }}
            >
              {pendingPayout > 0 ? (
                <Loader2 size={11} color="#f59e0b" style={{ animation: 'dashSpin 2s linear infinite' }} />
              ) : (
                <Loader2 size={11} color="var(--text-muted)" />
              )}
               Pending Payout {pendingPayout > 0 && <span style={{ fontSize: '9px', color: '#f59e0b', animation: 'pulse 1.5s infinite' }}>(Running)</span>}
            </span>
            <span style={{ fontWeight: 700, color: pendingPayout > 0 ? '#f59e0b' : 'var(--text-muted)' }}>
              {pendingPayout > 0 ? `+${convertAndFormatCurrency(pendingPayout)}` : '—'}
            </span>
          </div>
        </div>
