import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAuth } from '../contexts/AuthContext';
import { useLanguage } from '../contexts/LanguageContext';
import { ChevronLeft, AlertCircle, Activity, Zap } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useCurrency } from '../hooks/useCurrency';
import { CRYPTO_PLANS } from './Wealth';
import toast from 'react-hot-toast';

const ACTION_MOVIES = [
  { id: 'yjRHZEUamCc', title: 'John Wick: Chapter 4', duration: '2:29' },
  { id: 'eoOaKN4qCKw', title: 'Fast X - Official Trailer', duration: '3:41' },
  { id: 'avz06PDqDbM', title: 'Mission: Impossible', duration: '2:30' },
  { id: 'Y274jZs5s7s', title: 'Extraction 2 | Official Trailer', duration: '2:38' },
  { id: 'mqqft2x_Aa4', title: 'The Batman - Main Trailer', duration: '2:38' },
  { id: 'xa_yFaLhiRE', title: 'Top Gun: Maverick', duration: '2:12' },
];

const LIVE_RATES = { doge: 6.0, ada: 6.8, matic: 7.4, xrp: 8.0, link: 8.8, dot: 9.6, avax: 10.4, sol: 11.0, eth: 12.0, btc: 14.0 };
const REQUIRED_WATCH_TIME = 30;
const MS_24H = 24 * 60 * 60 * 1000;

function parseRawPrice(price) {
  return parseFloat(String(price || '0').replace(/[^0-9.-]/g, '')) || 0;
}

function getLivePercent(id) {
  const p = CRYPTO_PLANS.find(p => p.id === id);
  return p ? p.dailyPercent : 0;
}

function fmtCountdown(ms) {
  const s = Math.max(0, Math.floor(ms / 1000));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`;
}

export const Movies = () => {
  const { userData } = useAuth();
  const { t } = useLanguage();
  const { convertAndFormatCurrency } = useCurrency();
  const navigate = useNavigate();

  const [nowTs, setNowTs] = useState(Date.now());

  useEffect(() => {
    const timer = setInterval(() => setNowTs(Date.now()), 1000);
    return () => clearInterval(timer);
  }, []);

  const activeCrypto = (userData?.activatedCrypto || []).filter(c => c.status === 'running');
  const hasInvestments = activeCrypto.length > 0;

  return (
    <motion.div
      className="page-content"
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      transition={{ duration: 0.3 }}
      style={{ paddingBottom: '100px' }}
    >
      <style>{`
        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
        .miner-ring {
          position: absolute;
          inset: -4px;
          border-radius: 50%;
          background: conic-gradient(from 0deg, transparent 0%, transparent 60%, rgba(16,185,129,0.8) 80%, #F59E0B 100%);
          animation: spin 2s linear infinite;
          z-index: 0;
        }
        .miner-core {
          position: relative;
          z-index: 1;
          width: 100%;
          height: 100%;
          background: var(--bg-panel);
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 8px;
        }
        .progress-bar-bg {
          height: 12px;
          background: var(--bg-darker);
          border-radius: 6px;
          overflow: hidden;
          margin-top: 12px;
        }
        .progress-bar-fill {
          height: 100%;
          background: linear-gradient(90deg, #10b981 0%, #f59e0b 100%);
          transition: width 1s linear;
        }
      `}</style>
      
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '20px' }}>
        <button onClick={() => navigate(-1)} style={{ background: 'var(--bg-panel)', border: '1px solid var(--border)', borderRadius: '8px', padding: '6px', color: '#fff', cursor: 'pointer', display: 'flex' }}>
          <ChevronLeft size={20} />
        </button>
        <h2 style={{ margin: 0 }}>Active Mining</h2>
      </div>

      {/* No investment warning */}
      {!hasInvestments && (
        <div style={{ background: 'rgba(245,158,11,0.1)', border: '1px solid rgba(245,158,11,0.3)', padding: '16px', borderRadius: '12px', display: 'flex', gap: '12px', marginBottom: '20px', alignItems: 'flex-start' }}>
          <AlertCircle size={22} color="#f59e0b" style={{ flexShrink: 0, marginTop: '2px' }} />
          <div>
            <div style={{ color: '#f59e0b', fontWeight: 700, fontSize: '14px', marginBottom: '4px' }}>No Active Investments</div>
            <div style={{ color: 'var(--text-muted)', fontSize: '12px', lineHeight: 1.5 }}>
              You need to activate a crypto mining plan in the Wealth dashboard to start generating daily income tracking.
            </div>
            <button onClick={() => navigate('/wealth')} style={{ background: '#f59e0b', color: '#000', border: 'none', padding: '8px 16px', borderRadius: '8px', fontSize: '13px', fontWeight: 700, marginTop: '12px', cursor: 'pointer' }}>
              Go to Wealth
            </button>
          </div>
        </div>
      )}

      {/* Active Mining Dashboard */}
      {hasInvestments && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          {activeCrypto.map(c => {
            const price = parseRawPrice(c.price);
            const pct = getLivePercent(c.id);
            const dailyReward = (price * pct / 100);
            
            // Calculate timing
            const activatedTime = c.activatedAt ? new Date(c.activatedAt).getTime() : Date.now();
            const lastPayout = c.lastPayoutAt ? new Date(c.lastPayoutAt).getTime() : activatedTime;
            
            const targetTime = lastPayout + MS_24H;
            const msLeft = Math.max(0, targetTime - nowTs);
            const elapsed = MS_24H - msLeft;
            const progressPct = Math.min(100, Math.max(0, (elapsed / MS_24H) * 100));

            return (
              <div key={c.id} className="panel" style={{ padding: '20px', border: '1px solid rgba(16,185,129,0.3)', position: 'relative', overflow: 'hidden' }}>
                
                {/* Background glow for running context */}
                <div style={{ position: 'absolute', top: 0, right: 0, width: '150px', height: '150px', background: 'radial-gradient(circle, rgba(16,185,129,0.1) 0%, transparent 70%)', transform: 'translate(30%, -30%)', zIndex: 0 }} />

                <div style={{ display: 'flex', alignItems: 'center', gap: '20px', position: 'relative', zIndex: 1 }}>
                  {/* Spinning Ring Avatar */}
                  <div style={{ position: 'relative', width: '64px', height: '64px', flexShrink: 0 }}>
                    <div className="miner-ring" />
                    <div className="miner-core">
                      <img src={c.logo} alt={c.name} style={{ width: '100%', height: '100%', objectFit: 'contain' }} onError={e => { e.target.style.display='none'; }} />
                    </div>
                  </div>

                  {/* Info */}
                  <div style={{ flex: 1 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '8px' }}>
                      <div>
                        <div style={{ fontWeight: 800, fontSize: '16px', color: 'var(--text-primary)', marginBottom: '2px' }}>{c.name} {t('miningContract') || 'Mining'}</div>
                        <div style={{ fontSize: '13px', color: 'var(--text-muted)' }}>Invested: <strong style={{ color: 'var(--text-primary)' }}>{convertAndFormatCurrency(price)}</strong></div>
                      </div>
                      <div style={{ background: 'rgba(16,185,129,0.1)', color: 'var(--success)', padding: '4px 8px', borderRadius: '12px', fontSize: '11px', fontWeight: 800, display: 'flex', alignItems: 'center', gap: '4px' }}>
                        <Activity size={12} style={{ animation: 'pulse 1.5s infinite' }} />
                        RUNNING
                      </div>
                    </div>

                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <div style={{ fontSize: '12px', color: 'var(--text-muted)' }}>Daily Return ({pct}%)</div>
                      <div style={{ color: 'var(--success)', fontWeight: 800, fontSize: '15px' }}>+{convertAndFormatCurrency(dailyReward)}</div>
                    </div>
                  </div>
                </div>

                {/* Progress Bar & Countdown */}
                <div style={{ position: 'relative', zIndex: 1, marginTop: '20px' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '6px' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px', fontSize: '12px', color: 'var(--text-secondary)' }}>
                      <Zap size={14} color="#f59e0b" /> Income Generating...
                    </div>
                    <div style={{ fontSize: '14px', fontWeight: 800, color: 'var(--primary)', fontFamily: 'monospace' }}>
                      {fmtCountdown(msLeft)}
                    </div>
                  </div>
                  <div className="progress-bar-bg">
                    <div className="progress-bar-fill" style={{ width: `${progressPct}%` }} />
                  </div>
                  {msLeft === 0 && (
                    <div style={{ textAlign: 'center', marginTop: '10px', fontSize: '12px', color: 'var(--success)', fontWeight: 700 }}>
                      Payout cycle completed! Waiting for automated distribution...
                    </div>
                  )}
                </div>

              </div>
            );
          })}
        </div>
      )}
    </motion.div>
  );
};

