import React, { useState, useEffect } from 'react';
import { motion, useAnimation } from 'framer-motion';
import { useAuth } from '../contexts/AuthContext';
import { useLanguage } from '../contexts/LanguageContext';
import { Shield, Key, History, MapPin, MonitorSmartphone, Clock, ChevronLeft } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { updatePassword, reauthenticateWithCredential, EmailAuthProvider } from 'firebase/auth';
import { auth } from '../firebase';
import toast from 'react-hot-toast';

export const Security = () => {
  const { currentUser, userData } = useAuth();
  const { t } = useLanguage();
  const navigate = useNavigate();
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [loginHistory, setLoginHistory] = useState([]);

  const controls = useAnimation();

  const triggerShake = () => {
    controls.start({
      x: [0, -10, 10, -10, 10, 0],
      transition: { duration: 0.4 }
    });
  };

  useEffect(() => {
    if (userData?.loginHistory) {
      setLoginHistory(userData.loginHistory);
    }
  }, [userData]);

  const handleChangePassword = async (e) => {
    e.preventDefault();
    if (!currentPassword || !newPassword || !confirmPassword) {
      triggerShake();
      return toast.error(t('errFillAllPasswords'));
    }
    if (newPassword !== confirmPassword) {
      triggerShake();
      return toast.error(t('errPasswordsMismatch'));
    }
    if (newPassword.length < 6) {
      triggerShake();
      return toast.error(t('errPasswordTooShort'));
    }

    setLoading(true);
    try {
      const credential = EmailAuthProvider.credential(currentUser.email, currentPassword);
      await reauthenticateWithCredential(auth.currentUser, credential);
      
      await updatePassword(auth.currentUser, newPassword);
      toast.success(t('successPasswordUpdated'));
      setCurrentPassword('');
      setNewPassword('');
      setConfirmPassword('');
    } catch (error) {
      triggerShake();
      if (error.code === 'auth/invalid-credential' || error.code === 'auth/wrong-password') {
        toast.error(t('errIncorrectPassword'));
      } else {
        toast.error(t('errPasswordTooShort').replace('6 characters', error.message));
      }
    } finally {
      setLoading(false);
    }
  };

  const getDeviceIcon = (userAgent) => {
    if (!userAgent) return <MonitorSmartphone size={14} />;
    const ua = userAgent.toLowerCase();
    if (ua.includes('mobile') || ua.includes('android') || ua.includes('iphone')) {
      return <MonitorSmartphone size={14} />;
    }
    return <MonitorSmartphone size={14} />;
  };

  return (
    <motion.div 
      className="page-content"
      initial={{ opacity: 0, y: 10 }}
      animate={controls}
      onViewportEnter={() => controls.start({ opacity: 1, y: 0 })}
      exit={{ opacity: 0, y: -10 }}
      transition={{ duration: 0.3 }}
      style={{ padding: '16px' }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '16px' }}>
        <button 
          onClick={() => navigate(-1)}
          style={{ background: 'var(--bg-panel)', border: '1px solid var(--border)', borderRadius: '8px', padding: '6px', color: '#fff', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
        >
          <ChevronLeft size={20} />
        </button>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <Shield size={20} color="var(--primary)" />
          <h2 style={{ fontSize: '18px', margin: 0 }}>{t('securitySettings')}</h2>
        </div>
      </div>
      
      {/* PASSWORD CHANGE */}
      <div className="panel mb-4" style={{ padding: '16px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '16px', borderBottom: '1px solid var(--border)', paddingBottom: '12px' }}>
          <Key size={16} color="var(--text-secondary)" />
          <h3 style={{ fontSize: '14px', margin: 0 }}>{t('changePassword')}</h3>
        </div>
        
        <form onSubmit={handleChangePassword} style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
          <div className="input-group">
            <label className="input-label" style={{ fontSize: '12px' }}>{t('currentPassword')}</label>
            <input 
              type="password" 
              className="input-field" 
              value={currentPassword} 
              onChange={e => setCurrentPassword(e.target.value)} 
              placeholder="Enter current password"
            />
          </div>
          <div className="input-group">
            <label className="input-label" style={{ fontSize: '12px' }}>{t('newPassword')}</label>
            <input 
              type="password" 
              className="input-field" 
              value={newPassword} 
              onChange={e => setNewPassword(e.target.value)} 
              placeholder="Enter new password"
            />
          </div>
          <div className="input-group">
            <label className="input-label" style={{ fontSize: '12px' }}>{t('confirmPassword')}</label>
            <input 
              type="password" 
              className="input-field" 
              value={confirmPassword} 
              onChange={e => setConfirmPassword(e.target.value)} 
              placeholder="Confirm new password"
            />
          </div>
          <button type="submit" className="btn btn-primary" style={{ width: '100%', fontSize: '12px', padding: '10px', marginTop: '8px' }} disabled={loading}>
            {loading ? t('updating') : t('updatePassword')}
          </button>
        </form>
      </div>

      {/* LOGIN HISTORY */}
      <div className="panel" style={{ padding: '16px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '16px', borderBottom: '1px solid var(--border)', paddingBottom: '12px' }}>
          <History size={16} color="var(--text-secondary)" />
          <h3 style={{ fontSize: '14px', margin: 0 }}>{t('recentLoginActivity')}</h3>
        </div>
        
        {loginHistory.length === 0 ? (
          <p className="text-center text-muted" style={{ fontSize: '12px' }}>{t('noRecentLogin')}</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            {loginHistory.map((log) => (
              <div key={log.id} style={{ background: 'var(--bg-dark)', padding: '12px', borderRadius: '8px', border: '1px solid var(--border)' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: 'var(--text-primary)' }}>
                    <MapPin size={12} color="var(--primary)" />
                    <span style={{ fontSize: '12px', fontWeight: 500 }}>{log.country || 'Unknown Location'}</span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '4px', color: 'var(--text-muted)' }}>
                    <Clock size={10} />
                    <span style={{ fontSize: '10px' }}>{new Date(log.timestamp).toLocaleString()}</span>
                  </div>
                </div>
                
                <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
                  <span style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>
                    <strong>IP:</strong> {log.ip || 'Unknown'}
                  </span>
                  <div style={{ display: 'flex', alignItems: 'flex-start', gap: '6px' }}>
                    <div style={{ marginTop: '2px', color: 'var(--text-muted)' }}>
                      {getDeviceIcon(log.device)}
                    </div>
                    <span style={{ fontSize: '10px', color: 'var(--text-muted)', lineHeight: 1.4, wordBreak: 'break-word' }}>
                      {log.device || 'Unknown Device'}
                    </span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </motion.div>
  );
};

import React, { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronLeft, Gift, Coins, Sparkles, AlertCircle } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { db } from '../firebase';
import { doc, updateDoc, collection, addDoc, increment } from 'firebase/firestore';
import toast from 'react-hot-toast';
import { useLanguage } from '../contexts/LanguageContext';
import { useCurrency } from '../hooks/useCurrency';

export const Spin = () => {
  const navigate = useNavigate();
  const { currentUser, userData } = useAuth();
  const { t } = useLanguage();
  const { formatCurrency, convertAndFormatCurrency } = useCurrency();
  const [isSpinning, setIsSpinning] = useState(false);
  const [rotation, setRotation] = useState(0);
  const [showReward, setShowReward] = useState(false);
  const [showInsufficientModal, setShowInsufficientModal] = useState(false);
  const [rewardAmount, setRewardAmount] = useState(0);
  
  // To avoid rapid clicks
  const spinTimeoutRef = useRef(null);

  const chances = userData?.spinChances || 0;

  const handleSpin = async () => {
    if (chances <= 0) {
      setShowInsufficientModal(true);
      return;
    }
    if (isSpinning) return;

    setIsSpinning(true);
    setShowReward(false);

    try {
      // 1. Deduct chance immediately in DB so they can't double-click exploit
      const userRef = doc(db, 'users', currentUser.uid);
      await updateDoc(userRef, { spinChances: increment(-1) });

      // 2. Calculate actual reward (Between $10 and $100, which is 1%-10% of 1000)
      const actualReward = Math.floor(Math.random() * (100 - 10 + 1)) + 10;
      setRewardAmount(actualReward);

      // 3. Visual Spin Logic (5 full rotations + random angle to land on a segment)
      // Since it's a generic wheel image, we just stop at a random angle.
      const randomExtraAngle = Math.floor(Math.random() * 360);
      const newRotation = rotation + 360 * 5 + randomExtraAngle;
      setRotation(newRotation);

      // 4. Wait for animation to finish (5 seconds)
      spinTimeoutRef.current = setTimeout(async () => {
        // Credit the user
        await updateDoc(userRef, { balance: increment(actualReward) });
        
        // Add transaction record
        await addDoc(collection(db, 'users', currentUser.uid, 'transactions'), {
          type: 'bonus',
          title: 'Lucky Spin Reward',
          amount: actualReward,
          status: 'SUCCESS',
          createdAt: new Date().toISOString()
        });

        setIsSpinning(false);
        setShowReward(true);
        toast.success(t('successSpinWon').replace('${amount}', convertAndFormatCurrency(actualReward)));
      }, 5000); // 5s matches CSS transition

    } catch (error) {
      console.error(error);
      toast.error(t('errSpinFailed'));
      setIsSpinning(false);
    }
  };

  // Cleanup timeout
  React.useEffect(() => {
    return () => {
      if (spinTimeoutRef.current) clearTimeout(spinTimeoutRef.current);
    };
  }, []);

  return (
    <motion.div 
      className="page-content"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      style={{ padding: '0', background: 'var(--bg-dark)', minHeight: '100vh', display: 'flex', flexDirection: 'column' }}
    >
      {/* HEADER */}
      <div style={{ padding: '16px', display: 'flex', alignItems: 'center', gap: '12px', background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(10px)', borderBottom: '1px solid var(--border)' }}>
        <button 
          onClick={() => navigate(-1)}
          style={{ background: 'var(--bg-panel)', border: '1px solid var(--border)', borderRadius: '8px', padding: '6px', color: '#fff', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
        >
          <ChevronLeft size={20} />
        </button>
        <h2 style={{ fontSize: '18px', margin: 0, fontWeight: 600, color: 'var(--warning)', display: 'flex', alignItems: 'center', gap: '8px' }}>
          <Sparkles size={18} /> Lucky Spin
        </h2>
      </div>

      <div style={{ padding: '24px 16px', flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
        
        {/* INFO CARD */}
        <div style={{ background: 'var(--bg-panel)', width: '100%', maxWidth: '400px', borderRadius: '16px', padding: '16px', border: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '32px', boxShadow: '0 4px 20px rgba(0,0,0,0.3)' }}>
          <div>
            <p style={{ margin: '0 0 4px 0', fontSize: '13px', color: 'var(--text-secondary)' }}>{t('availableSpins')}</p>
            <h3 style={{ margin: 0, fontSize: '24px', color: 'var(--warning)', display: 'flex', alignItems: 'center', gap: '8px' }}>
              <Gift size={24} /> {chances}
            </h3>
          </div>
          <div style={{ textAlign: 'right' }}>
            <p style={{ margin: '0 0 4px 0', fontSize: '11px', color: 'var(--text-muted)' }}>Deposit {convertAndFormatCurrency(100)}+</p>
            <p style={{ margin: 0, fontSize: '11px', color: 'var(--success)' }}>To earn chances</p>
          </div>
        </div>

        {/* WHEEL CONTAINER */}
        <div style={{ position: 'relative', width: '300px', height: '300px', margin: '0 auto', filter: 'drop-shadow(0 0 30px rgba(212,175,55,0.2))' }}>
          
          {/* POINTER */}
          <div style={{
            position: 'absolute',
            top: '-20px',
            left: '50%',
            transform: 'translateX(-50%)',
            zIndex: 10,
            width: '40px',
            height: '50px',
            background: 'linear-gradient(to bottom, #ff3b30, #990000)',
            clipPath: 'polygon(50% 100%, 0 0, 100% 0)',
            filter: 'drop-shadow(0 4px 6px rgba(0,0,0,0.5))'
          }}></div>

          {/* THE WHEEL */}
          <div 
            style={{ 
              width: '100%', 
              height: '100%', 
              borderRadius: '50%',
              overflow: 'hidden',
              transform: `rotate(${rotation}deg)`,
              transition: 'transform 5s cubic-bezier(0.25, 0.1, 0.25, 1)',
              background: 'var(--bg-panel)',
              border: '4px solid var(--warning)',
              boxShadow: 'inset 0 0 20px rgba(0,0,0,0.8)'
            }}
          >
            {/* The actual generated 3D wheel image */}
            <img src="/images/wheel_base.png" alt="Lucky Wheel" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
            
            {/* Overlay fake text labels if needed, or just let the raw image shine */}
            <div style={{ position: 'absolute', top: '15%', left: '50%', transform: 'translateX(-50%)', color: '#fff', fontWeight: 900, textShadow: '0 2px 4px rgba(0,0,0,0.8)', fontSize: '20px', zIndex: 5 }}>{convertAndFormatCurrency(5000)}</div>
            <div style={{ position: 'absolute', bottom: '15%', left: '50%', transform: 'translateX(-50%) rotate(180deg)', color: '#fff', fontWeight: 900, textShadow: '0 2px 4px rgba(0,0,0,0.8)', fontSize: '20px', zIndex: 5 }}>{convertAndFormatCurrency(1000)}</div>
            <div style={{ position: 'absolute', top: '50%', left: '15%', transform: 'translateY(-50%) rotate(-90deg)', color: '#fff', fontWeight: 900, textShadow: '0 2px 4px rgba(0,0,0,0.8)', fontSize: '20px', zIndex: 5 }}>{convertAndFormatCurrency(10000)}</div>
            <div style={{ position: 'absolute', top: '50%', right: '15%', transform: 'translateY(-50%) rotate(90deg)', color: '#fff', fontWeight: 900, textShadow: '0 2px 4px rgba(0,0,0,0.8)', fontSize: '20px', zIndex: 5 }}>iPhone</div>
          </div>
        </div>

        {/* SPIN BUTTON */}
        <button
          onClick={handleSpin}
          disabled={isSpinning}
          className={`btn ${isSpinning ? '' : 'hover:scale-105'}`}
          style={{
            marginTop: '40px',
            width: '100%',
            maxWidth: '300px',
            padding: '16px',
            fontSize: '18px',
            fontWeight: 800,
            textTransform: 'uppercase',
            letterSpacing: '2px',
            background: isSpinning ? 'var(--bg-panel)' : 'linear-gradient(90deg, #d4af37, #f5d98b, #d4af37)',
            color: isSpinning ? 'var(--text-muted)' : '#000',
            border: 'none',
            borderRadius: '50px',
            boxShadow: isSpinning ? 'none' : '0 10px 25px rgba(212,175,55,0.4)',
            cursor: isSpinning ? 'not-allowed' : 'pointer',
            transition: 'all 0.3s ease'
          }}
        >
          {isSpinning ? t('spinning') : t('spinNow')}
        </button>

        {/* REWARD POPUP */}
        <AnimatePresence>
          {showReward && (
            <motion.div 
              initial={{ opacity: 0, scale: 0.5, x: '-50%', y: '-30%' }}
              animate={{ opacity: 1, scale: 1, x: '-50%', y: '-50%' }}
              exit={{ opacity: 0, scale: 0.5, x: '-50%', y: '-30%' }}
              style={{
                position: 'fixed',
                top: '50%',
                left: '50%',
                background: 'linear-gradient(135deg, rgba(20,20,20,0.95), rgba(40,40,40,0.95))',
                border: '1px solid var(--warning)',
                padding: '32px',
                borderRadius: '24px',
                textAlign: 'center',
                boxShadow: '0 20px 50px rgba(0,0,0,0.8), 0 0 30px rgba(212,175,55,0.3)',
                zIndex: 100,
                width: '85%',
                maxWidth: '350px',
                backdropFilter: 'blur(10px)'
              }}
            >
              <div style={{ width: '80px', height: '80px', background: 'rgba(212,175,55,0.1)', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 20px', border: '2px solid var(--warning)' }}>
                <Coins size={40} color="var(--warning)" />
              </div>
              <h2 style={{ margin: '0 0 12px 0', color: '#fff', fontSize: '28px' }}>{t('youWon')}</h2>
              <p style={{ fontSize: '42px', fontWeight: 900, color: 'var(--success)', margin: '0 0 24px 0', textShadow: '0 2px 10px rgba(16,185,129,0.3)' }}>
                {convertAndFormatCurrency(rewardAmount)}
              </p>
              <p style={{ color: 'var(--text-secondary)', fontSize: '13px', marginBottom: '24px' }}>
                {t('bonusCredited')}
              </p>
              <button 
                onClick={() => setShowReward(false)}
                style={{ background: 'var(--primary)', color: '#fff', border: 'none', padding: '12px 32px', borderRadius: '50px', fontSize: '16px', fontWeight: 600, width: '100%', cursor: 'pointer' }}
              >
                {t('awesome')}
              </button>
            </motion.div>
          )}
        </AnimatePresence>

        {/* INSUFFICIENT CHANCES POPUP */}
        <AnimatePresence>
          {showInsufficientModal && (
            <motion.div 
              initial={{ opacity: 0, scale: 0.5, x: '-50%', y: '-30%' }}
              animate={{ opacity: 1, scale: 1, x: '-50%', y: '-50%' }}
              exit={{ opacity: 0, scale: 0.5, x: '-50%', y: '-30%' }}
              style={{
                position: 'fixed',
                top: '50%',
                left: '50%',
                background: 'var(--bg-panel)',
                border: '1px solid var(--border)',
                padding: '32px',
                borderRadius: '24px',
                textAlign: 'center',
                boxShadow: '0 20px 50px rgba(0,0,0,0.8)',
                zIndex: 100,
                width: '85%',
                maxWidth: '350px'
              }}
            >
              <div style={{ width: '60px', height: '60px', background: 'rgba(239,68,68,0.1)', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 20px' }}>
                <AlertCircle size={30} color="var(--danger)" />
              </div>
              <h2 style={{ margin: '0 0 12px 0', color: 'var(--text-primary)', fontSize: '22px' }}>{t('noSpinsLeft')}</h2>
              <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '24px', lineHeight: '1.5' }}>
                {t('noSpinsDesc')}
              </p>
              <div style={{ display: 'flex', gap: '12px', flexDirection: 'column' }}>
                <button 
                  onClick={() => navigate('/wallet')}
                  style={{ background: 'var(--primary)', color: '#fff', border: 'none', padding: '12px', borderRadius: '8px', fontSize: '14px', fontWeight: 600, width: '100%', cursor: 'pointer' }}
                >
                  {t('depositNow')}
                </button>
                <button 
                  onClick={() => navigate('/affiliate')}
                  style={{ background: 'transparent', color: 'var(--text-primary)', border: '1px solid var(--border)', padding: '12px', borderRadius: '8px', fontSize: '14px', fontWeight: 600, width: '100%', cursor: 'pointer' }}
                >
                  {t('inviteFriends')}
                </button>
                <button 
                  onClick={() => setShowInsufficientModal(false)}
                  style={{ background: 'transparent', color: 'var(--text-muted)', border: 'none', padding: '8px', fontSize: '13px', width: '100%', cursor: 'pointer', marginTop: '4px' }}
                >
                  {t('cancel')}
                </button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* OVERLAY FOR POPUPS */}
        <AnimatePresence>
          {(showReward || showInsufficientModal) && (
            <motion.div 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(0,0,0,0.7)', zIndex: 99 }}
              onClick={() => { setShowReward(false); setShowInsufficientModal(false); }}
            />
          )}
        </AnimatePresence>

      </div>
    </motion.div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAuth } from '../contexts/AuthContext';
import { db, storage } from '../firebase';
import {
  collection, addDoc, query, orderBy, onSnapshot,
  serverTimestamp, doc, setDoc, getDoc
} from 'firebase/firestore';
import { ref, uploadBytesResumable, getDownloadURL } from 'firebase/storage';
import { ChevronLeft, Send, Image, Check, CheckCheck, Clock, Paperclip, X } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';

export const Support = () => {
  const { currentUser, userData } = useAuth();
  const navigate = useNavigate();

  const [messages, setMessages] = useState([]);
  const [text, setText] = useState('');
  const [sending, setSending] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);
  const [imageFile, setImageFile] = useState(null);
  const [agentOnline] = useState(true);

  const bottomRef = useRef(null);
  const fileInputRef = useRef(null);
  const chatId = currentUser?.uid;

  // ── Load messages in real-time ──────────────────────────────────────
  useEffect(() => {
    if (!chatId) return;
    const q = query(
      collection(db, 'supportChats', chatId, 'messages'),
      orderBy('createdAt', 'asc')
    );
    const unsub = onSnapshot(q, snap => {
      setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    return () => unsub();
  }, [chatId]);

  // ── Auto scroll to bottom ────────────────────────────────────────────
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // ── Ensure chat room doc exists ──────────────────────────────────────
  useEffect(() => {
    if (!chatId) return;
    const chatRef = doc(db, 'supportChats', chatId);
    getDoc(chatRef).then(snap => {
      if (!snap.exists()) {
        setDoc(chatRef, {
          userId: chatId,
          userName: userData?.name || userData?.email || 'User',
          userEmail: userData?.email || '',
          createdAt: serverTimestamp(),
          lastMessage: '',
          lastMessageAt: serverTimestamp(),
          unreadAdmin: 0,
        });
      }
    });
  }, [chatId, userData]);

  // ── Handle image selection ───────────────────────────────────────────
  function handleImageSelect(e) {
    const file = e.target.files[0];
    if (!file) return;
    if (file.size > 10 * 1024 * 1024) {
      toast.error('Image must be under 10MB');
      return;
    }
    setImageFile(file);
    setImagePreview(URL.createObjectURL(file));
  }

  function clearImage() {
    setImageFile(null);
    setImagePreview(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  }

  // ── Send message ─────────────────────────────────────────────────────
  async function sendMessage() {
    if ((!text.trim() && !imageFile) || sending) return;
    setSending(true);

    try {
      let imageUrl = null;

      // Upload image if present
      if (imageFile) {
        const storageRef = ref(storage, `support/${chatId}/${Date.now()}_${imageFile.name}`);
        const task = uploadBytesResumable(storageRef, imageFile);
        imageUrl = await new Promise((resolve, reject) => {
          task.on('state_changed',
            snap => setUploadProgress(Math.round((snap.bytesTransferred / snap.totalBytes) * 100)),
            reject,
            async () => {
              const url = await getDownloadURL(task.snapshot.ref);
              resolve(url);
            }
          );
        });
        setUploadProgress(null);
      }

      const msgData = {
        text: text.trim(),
        imageUrl,
        senderId: chatId,
        senderName: userData?.name || 'User',
        senderRole: 'user',
        createdAt: serverTimestamp(),
        status: 'sent',
      };

      await addDoc(collection(db, 'supportChats', chatId, 'messages'), msgData);

      // Update chat room last message
      await setDoc(doc(db, 'supportChats', chatId), {
        lastMessage: imageUrl ? '📷 Image' : text.trim(),
        lastMessageAt: serverTimestamp(),
        unreadAdmin: 1,
      }, { merge: true });

      setText('');
      clearImage();
    } catch (err) {
      console.error(err);
      toast.error('Failed to send message');
    } finally {
      setSending(false);
    }
  }

  function handleKeyDown(e) {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  }

  // ── Group messages by date ───────────────────────────────────────────
  function formatDate(ts) {
    if (!ts?.toDate) return '';
    const d = ts.toDate();
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);
    if (d.toDateString() === today.toDateString()) return 'Today';
    if (d.toDateString() === yesterday.toDateString()) return 'Yesterday';
    return d.toLocaleDateString('en-US', { day: 'numeric', month: 'short', year: 'numeric' });
  }

  function formatTime(ts) {
    if (!ts?.toDate) return '';
    return ts.toDate().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false });
  }

  // Group messages by date
  const grouped = messages.reduce((acc, msg) => {
    const dateKey = msg.createdAt?.toDate
      ? msg.createdAt.toDate().toDateString()
      : 'now';
    if (!acc[dateKey]) acc[dateKey] = { label: formatDate(msg.createdAt), msgs: [] };
    acc[dateKey].msgs.push(msg);
    return acc;
  }, {});

  const isMe = (msg) => msg.senderId === chatId;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100dvh', background: '#0a0e1a', overflow: 'hidden' }}>

      {/* ── Header ── */}
      <div style={{
        background: 'linear-gradient(135deg, #0d1117 0%, #161b27 100%)',
        borderBottom: '1px solid rgba(255,255,255,0.08)',
        padding: '12px 16px',
        display: 'flex',
        alignItems: 'center',
        gap: '12px',
        flexShrink: 0,
        paddingTop: 'max(12px, env(safe-area-inset-top))',
      }}>
        <button
          onClick={() => navigate(-1)}
          style={{ background: 'rgba(255,255,255,0.07)', border: 'none', borderRadius: '50%', width: '36px', height: '36px', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: '#fff', flexShrink: 0 }}
        >
          <ChevronLeft size={20} />
        </button>

        {/* Agent avatar */}
        <div style={{ position: 'relative', flexShrink: 0 }}>
          <img
            src="https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=80&q=80"
            alt="Support Agent"
            style={{ width: '42px', height: '42px', borderRadius: '50%', objectFit: 'cover', border: '2px solid var(--primary)' }}
          />
          <span style={{ position: 'absolute', bottom: '1px', right: '1px', width: '11px', height: '11px', background: '#10b981', borderRadius: '50%', border: '2px solid #0d1117' }} />
        </div>

        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontWeight: 700, fontSize: '15px', color: '#fff' }}>QTX Support</div>
          <div style={{ fontSize: '12px', color: agentOnline ? '#10b981' : 'var(--text-muted)' }}>
            {agentOnline ? '● Online — typically replies instantly' : '● Away'}
          </div>
        </div>

        <div style={{ background: 'rgba(16,185,129,0.1)', border: '1px solid rgba(16,185,129,0.3)', borderRadius: '20px', padding: '4px 10px', fontSize: '11px', color: '#10b981', fontWeight: 600 }}>
          24/7
        </div>
      </div>

      {/* ── Chat Background Pattern ── */}
      <div style={{
        flex: 1,
        overflowY: 'auto',
        padding: '16px',
        background: `
          radial-gradient(circle at 20% 20%, rgba(16,185,129,0.03) 0%, transparent 50%),
          radial-gradient(circle at 80% 80%, rgba(99,102,241,0.03) 0%, transparent 50%),
          #0a0e1a
        `,
        WebkitOverflowScrolling: 'touch',
      }}>

        {/* Welcome bubble */}
        {messages.length === 0 && (
          <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} style={{ textAlign: 'center', marginBottom: '24px' }}>
            <div style={{ display: 'inline-block', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: '12px', padding: '12px 20px', fontSize: '12px', color: 'var(--text-muted)', maxWidth: '280px' }}>
              🔒 Messages are end-to-end encrypted. Start your conversation with our support team below.
            </div>
          </motion.div>
        )}

        {/* Messages grouped by date */}
        {Object.values(grouped).map((group, gi) => (
          <div key={gi}>
            {/* Date separator */}
            <div style={{ textAlign: 'center', marginBottom: '12px' }}>
              <span style={{ background: 'rgba(255,255,255,0.06)', borderRadius: '20px', padding: '3px 12px', fontSize: '11px', color: 'var(--text-muted)', fontWeight: 500 }}>
                {group.label}
              </span>
            </div>

            {group.msgs.map((msg, i) => {
              const mine = isMe(msg);
              return (
                <motion.div
                  key={msg.id}
                  initial={{ opacity: 0, y: 6, scale: 0.97 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  transition={{ duration: 0.2 }}
                  style={{
                    display: 'flex',
                    justifyContent: mine ? 'flex-end' : 'flex-start',
                    marginBottom: '4px',
                    alignItems: 'flex-end',
                    gap: '8px',
                  }}
                >
                  {/* Agent avatar for non-mine */}
                  {!mine && (
                    <img
                      src="https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=40&q=80"
                      alt=""
                      style={{ width: '28px', height: '28px', borderRadius: '50%', objectFit: 'cover', flexShrink: 0, marginBottom: '2px' }}
                    />
                  )}

                  <div style={{ maxWidth: '72%' }}>
                    {/* Image */}
                    {msg.imageUrl && (
                      <div style={{
                        background: mine ? 'linear-gradient(135deg, #10b981, #059669)' : 'rgba(255,255,255,0.08)',
                        borderRadius: mine ? '18px 18px 4px 18px' : '18px 18px 18px 4px',
                        overflow: 'hidden',
                        marginBottom: msg.text ? '2px' : '0',
                      }}>
                        <img
                          src={msg.imageUrl}
                          alt="sent"
                          style={{ width: '100%', maxWidth: '240px', display: 'block', cursor: 'pointer' }}
                          onClick={() => window.open(msg.imageUrl, '_blank')}
                        />
                      </div>
                    )}

                    {/* Text bubble */}
                    {msg.text && (
                      <div style={{
                        background: mine ? 'linear-gradient(135deg, #10b981, #059669)' : 'rgba(255,255,255,0.08)',
                        color: mine ? '#fff' : 'var(--text-primary)',
                        padding: '10px 14px',
                        borderRadius: mine ? '18px 18px 4px 18px' : '18px 18px 18px 4px',
                        fontSize: '14px',
                        lineHeight: 1.5,
                        wordBreak: 'break-word',
                        backdropFilter: !mine ? 'blur(10px)' : 'none',
                        border: !mine ? '1px solid rgba(255,255,255,0.06)' : 'none',
                      }}>
                        {msg.text}
                      </div>
                    )}

                    {/* Time + status */}
                    <div style={{ display: 'flex', alignItems: 'center', gap: '4px', justifyContent: mine ? 'flex-end' : 'flex-start', marginTop: '3px', paddingRight: mine ? '4px' : '0' }}>
                      <span style={{ fontSize: '10px', color: 'var(--text-muted)' }}>
                        {msg.createdAt ? formatTime(msg.createdAt) : 'sending...'}
                      </span>
                      {mine && (
                        msg.status === 'read'
                          ? <CheckCheck size={12} color="#10b981" />
                          : msg.createdAt
                          ? <CheckCheck size={12} color="rgba(255,255,255,0.4)" />
                          : <Clock size={11} color="rgba(255,255,255,0.3)" />
                      )}
                    </div>
                  </div>
                </motion.div>
              );
            })}
          </div>
        ))}

        <div ref={bottomRef} />
      </div>

      {/* ── Image Preview Strip ── */}
      <AnimatePresence>
        {imagePreview && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            style={{ background: 'rgba(255,255,255,0.04)', borderTop: '1px solid rgba(255,255,255,0.07)', padding: '10px 16px', display: 'flex', alignItems: 'center', gap: '12px', flexShrink: 0 }}
          >
            <div style={{ position: 'relative', display: 'inline-block' }}>
              <img src={imagePreview} alt="preview" style={{ height: '60px', borderRadius: '8px', objectFit: 'cover' }} />
              <button onClick={clearImage} style={{ position: 'absolute', top: '-6px', right: '-6px', background: '#ef4444', border: 'none', borderRadius: '50%', width: '18px', height: '18px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff' }}>
                <X size={10} />
              </button>
            </div>
            {uploadProgress !== null && (
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: '11px', color: 'var(--text-muted)', marginBottom: '4px' }}>Uploading... {uploadProgress}%</div>
                <div style={{ height: '3px', background: 'rgba(255,255,255,0.1)', borderRadius: '2px' }}>
                  <div style={{ height: '100%', width: `${uploadProgress}%`, background: 'var(--primary)', borderRadius: '2px', transition: 'width 0.3s' }} />
                </div>
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      {/* ── Input Bar ── */}
      <div style={{
        background: 'rgba(13,17,23,0.98)',
        borderTop: '1px solid rgba(255,255,255,0.07)',
        padding: '10px 12px',
        display: 'flex',
        alignItems: 'flex-end',
        gap: '8px',
        flexShrink: 0,
        paddingBottom: 'max(10px, env(safe-area-inset-bottom))',
      }}>
        {/* Image button */}
        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          style={{ display: 'none' }}
          onChange={handleImageSelect}
        />
        <button
          onClick={() => fileInputRef.current?.click()}
          style={{ background: 'rgba(255,255,255,0.07)', border: 'none', borderRadius: '50%', width: '40px', height: '40px', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: 'var(--text-muted)', flexShrink: 0 }}
        >
          <Image size={20} />
        </button>

        {/* Text input */}
        <div style={{ flex: 1, background: 'rgba(255,255,255,0.07)', borderRadius: '22px', padding: '10px 16px', border: '1px solid rgba(255,255,255,0.08)', minHeight: '40px', display: 'flex', alignItems: 'center' }}>
          <textarea
            value={text}
            onChange={e => setText(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Message..."
            rows={1}
            style={{
              background: 'transparent',
              border: 'none',
              outline: 'none',
              color: '#fff',
              fontSize: '14px',
              width: '100%',
              resize: 'none',
              lineHeight: 1.5,
              maxHeight: '100px',
              overflowY: 'auto',
              fontFamily: 'inherit',
            }}
          />
        </div>

        {/* Send button */}
        <motion.button
          whileTap={{ scale: 0.9 }}
          onClick={sendMessage}
          disabled={sending || (!text.trim() && !imageFile)}
          style={{
            background: (text.trim() || imageFile) ? 'linear-gradient(135deg, #10b981, #059669)' : 'rgba(255,255,255,0.07)',
            border: 'none',
            borderRadius: '50%',
            width: '42px',
            height: '42px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: (text.trim() || imageFile) ? 'pointer' : 'default',
            color: '#fff',
            flexShrink: 0,
            transition: 'background 0.2s',
          }}
        >
          <Send size={18} style={{ marginLeft: '2px' }} />
        </motion.button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { TradingChart } from '../components/TradingChart';
import { useNavigate } from 'react-router-dom';
import { ChevronLeft, TrendingUp } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { useCurrency } from '../hooks/useCurrency';
import toast from 'react-hot-toast';

export const Trading = () => {
  const navigate = useNavigate();
  const { balance, qtxBalance, buyQTX, sellQTX } = useAuth();
  const { formatCurrency, convertAndFormatSmallCurrency, symbol, rate } = useCurrency();
  
  const [qtxPrice, setQtxPrice] = useState(0.05); // Default fallback
  const localQtxPrice = qtxPrice * rate;
  const [loadingPrice, setLoadingPrice] = useState(true);
  
  const [buyAmount, setBuyAmount] = useState('');
  const [loadingTx, setLoadingTx] = useState(false);

  useEffect(() => {
    const fetchPrice = async () => {
      try {
        const res = await fetch('https://api.coingecko.com/api/v3/simple/price?ids=quantumx&vs_currencies=usd');
        const data = await res.json();
        if (data.quantumx && data.quantumx.usd) {
          setQtxPrice(data.quantumx.usd);
        }
      } catch (err) {
        console.log('Error fetching price, using fallback', err);
      } finally {
        setLoadingPrice(false);
      }
    };
    fetchPrice();
    const interval = setInterval(fetchPrice, 30000); // update every 30s
    return () => clearInterval(interval);
  }, []);

  const handleBuy = async () => {
    const amt = parseFloat(buyAmount);
    if (!amt || amt <= 0) return toast.error('Enter a valid amount');
    if (amt > balance) return toast.error('Insufficient balance');
    setLoadingTx(true);
    const success = await buyQTX(amt, localQtxPrice);
    setLoadingTx(false);
    if (success) {
      toast.success('Successfully bought QTX');
      setBuyAmount('');
    } else {
      toast.error('Transaction failed');
    }
  };

  return (
    <motion.div 
      className="page-content"
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      transition={{ duration: 0.3 }}
      style={{ paddingBottom: '80px' }}
    >
      <div className="flex justify-between items-center mb-4">
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <button 
            onClick={() => navigate(-1)}
            style={{ background: 'var(--bg-panel)', border: '1px solid var(--border)', borderRadius: '8px', padding: '6px', color: '#fff', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
          >
            <ChevronLeft size={20} />
          </button>
          <h2 className="mb-0" style={{ margin: 0, fontSize: '18px' }}>Trade QTX</h2>
        </div>
        <div className="flex gap-2">
          <div style={{ background: 'rgba(16, 185, 129, 0.1)', color: 'var(--success)', padding: '6px 12px', borderRadius: '8px', fontSize: '12px', fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: '4px' }}>
            <TrendingUp size={14} />
            {convertAndFormatSmallCurrency(qtxPrice, 6)}
          </div>
        </div>
      </div>
      
      <div className="panel" style={{ height: '280px', marginBottom: '16px', padding: '10px' }}>
        <TradingChart />
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr', gap: '12px' }}>
        {/* BUY BOX */}
        <div className="panel" style={{ padding: '16px', background: 'var(--bg-panel)' }}>
          <h3 style={{ fontSize: '14px', marginBottom: '12px', color: 'var(--success)', display: 'flex', alignItems: 'center', gap: '6px' }}>
            Buy QTX
          </h3>
          <div style={{ fontSize: '11px', color: 'var(--text-secondary)', marginBottom: '8px' }}>
            Avail: {formatCurrency(balance)}
          </div>
          <div className="input-group" style={{ marginBottom: '12px' }}>
            <div style={{ position: 'relative' }}>
              <input 
                type="number" 
                className="input-field" 
                placeholder="Amount" 
                value={buyAmount}
                onChange={e => setBuyAmount(e.target.value)}
                style={{ width: '100%', paddingRight: '40px', fontSize: '13px' }}
              />
              <span style={{ position: 'absolute', right: '12px', top: '12px', fontSize: '12px', color: 'var(--text-muted)' }}>{symbol}</span>
            </div>
          </div>
          <div style={{ fontSize: '11px', color: 'var(--text-muted)', marginBottom: '12px', textAlign: 'center' }}>
            ≈ {buyAmount ? (parseFloat(buyAmount) / localQtxPrice).toFixed(4) : '0.0000'} QTX
          </div>
          <button 
            className="btn btn-success" 
            style={{ width: '100%', padding: '10px', fontSize: '13px' }}
            onClick={handleBuy}
            disabled={loadingTx}
          >
            {loadingTx ? 'Processing...' : 'Buy'}
          </button>
        </div>
      </div>
    </motion.div>
  );
};

