/* ═══════════════ Main Page ═══════════════ */
export const VIP = () => {
  const { currentUser, balance, userData } = useAuth();
  const { t } = useLanguage();
  const { formatCurrency, rate } = useCurrency();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('bots');   // 'bots' | 'mybots'
  const [selectedBot, setSelectedBot] = useState(null);
  const [showInfo, setShowInfo] = useState(false);
  const [activating, setActivating] = useState(false);
  const [errorMsg, setErrorMsg] = useState(null);
  const [successData, setSuccessData] = useState(null);
  const activatedBots = userData?.activatedBots || [];

  const handleConfirm = async (bot, userAmount, errorMessage) => {
    if (errorMessage) {
      return setErrorMsg(errorMessage);
    }
    
    setActivating(true);
    try {
      const userRef = doc(db, 'users', currentUser.uid);
      const snap = await getDoc(userRef);
      if (!snap.exists()) throw new Error('User document not found');

      const liveBalance = parseFloat(snap.data().balance || 0);
      const usdCost = userAmount / rate;
      if (liveBalance < usdCost) throw new Error('Insufficient balance (live check).');

      const currentBots = snap.data().activatedBots || [];
      const record = {
        ...bot,
        userAmount: usdCost,
        activationId: Date.now().toString(),
        activatedAt: new Date().toISOString(),
        status: 'running',
      };

      const currentInvestment = snap.data().investmentBalance || 0;
      
      await updateDoc(userRef, {
        balance: liveBalance - usdCost,
        investmentBalance: currentInvestment + usdCost,
        activatedBots: [record, ...currentBots],
      });

      // Schedule local notifications for this specific bot's lifecycle
      scheduleBotNotifications(record, formatCurrency);

      const dailyProfit = ((userAmount * bot.dailyPercent) / 100).toFixed(2);
      
      setSuccessData({
        title: `${bot.name} Activated 🎉`,
        message: t('botActivated'),
        details: [
          { label: 'Bot Name', value: bot.name },
          { label: 'Amount Invested', value: formatCurrency(userAmount), color: '#fff' },
          { label: 'Daily Return', value: `${bot.dailyPercent}%`, color: 'var(--success)' },
          { label: 'Est. Daily Profit', value: formatCurrency(dailyProfit), color: 'var(--success)' }
        ]
      });
      setSelectedBot(null);
    } catch (err) {
      setErrorMsg(err.message || t('activationFailed'));
    } finally {
      setActivating(false);
    }
  };

  /* ── tab styles ── */
  const tabStyle = (tab) => ({
    flex: 1,
    padding: '11px',
    borderRadius: '10px',
    fontWeight: 700,
    fontSize: '13px',
    cursor: 'pointer',
    border: 'none',
    transition: 'all 0.25s',
    background: activeTab === tab
      ? 'linear-gradient(135deg, #d4af37, #f5d98b)'
      : 'transparent',
    color: activeTab === tab ? '#000' : 'var(--text-muted)',
    boxShadow: activeTab === tab ? '0 4px 12px rgba(212,175,55,0.35)' : 'none',
  });

  return (
    <motion.div
      className="page-content"
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      transition={{ duration: 0.3 }}
      style={{ padding: '16px' }}
    >
      {/* Page title */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '16px' }}>
        <button 
          onClick={() => navigate(-1)}
          style={{ background: 'var(--bg-panel)', border: '1px solid var(--border)', borderRadius: '8px', padding: '6px', color: '#fff', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
        >
          <ChevronLeft size={20} />
        </button>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <Crown size={22} color="var(--warning)" />
          <h2 style={{ fontSize: '18px', margin: 0 }}>{t('vipTitle')}</h2>
        </div>
      </div>

      {/* ── Golden tab switcher ── */}
      <div style={{ display: 'flex', background: 'var(--bg-dark)', padding: '4px', borderRadius: '14px', marginBottom: '20px', border: '1px solid rgba(212,175,55,0.25)', gap: '4px' }}>
        <button style={tabStyle('bots')}   onClick={() => setActiveTab('bots')}>
          {t('botMarketplace')}
        </button>
        <button style={tabStyle('mybots')} onClick={() => setActiveTab('mybots')}>
          {t('myActiveBots')} {activatedBots.length > 0 && `(${activatedBots.length})`}
        </button>
      </div>

      <AnimatePresence mode="wait">
        {/* ── Marketplace tab ── */}
        {activeTab === 'bots' && (
          <motion.div key="bots" initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 10 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
              <p style={{ fontSize: '12px', color: 'var(--text-secondary)', margin: 0, lineHeight: 1.5, flex: 1 }}>
                {t('chooseBot')}
              </p>
              <button 
                onClick={() => setShowInfo(true)}
                style={{ display: 'flex', alignItems: 'center', gap: '6px', background: 'rgba(212,175,55,0.1)', border: '1px solid rgba(212,175,55,0.3)', color: 'var(--primary)', padding: '6px 10px', borderRadius: '8px', fontSize: '11px', fontWeight: 600, cursor: 'pointer', flexShrink: 0, marginLeft: '12px' }}
              >
                <Info size={14} /> {t('howItWorksBtn')}
              </button>
            </div>
            {VIP_BOTS.map(bot => (
              <BotCard key={bot.id} bot={bot} onSelect={setSelectedBot} />
            ))}
          </motion.div>
        )}

        {/* ── My Bots tab ── */}
        {activeTab === 'mybots' && (
          <motion.div key="mybots" initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -10 }}>
            {activatedBots.length === 0 ? (
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '300px', color: 'var(--text-muted)' }}>
                <Bot size={48} style={{ marginBottom: '16px', opacity: 0.3 }} />
                <p style={{ fontSize: '14px', marginBottom: '8px' }}>{t('noBotsYet')}</p>
                <button onClick={() => setActiveTab('bots')} style={{ background: 'linear-gradient(135deg, #d4af37, #f5d98b)', color: '#000', border: 'none', padding: '10px 24px', borderRadius: '20px', fontWeight: 700, cursor: 'pointer', fontSize: '13px' }}>
                  {t('browseBots')}
                </button>
              </div>
            ) : (
              activatedBots.map((bot, i) => <ActiveBotCard key={bot.activationId || i} bot={bot} />)
            )}
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {selectedBot && (
          <ConfirmModal
            bot={selectedBot}
            balance={balance || 0}
            loading={activating}
            onClose={() => setSelectedBot(null)}
            onConfirm={handleConfirm}
          />
        )}
        
        {showInfo && (
          <InfoModal onClose={() => setShowInfo(false)} />
        )}

        {/* --- Error Bottom Sheet --- */}
        {errorMsg && (
          <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', zIndex: 1000, display: 'flex', alignItems: 'flex-end', backdropFilter: 'blur(4px)' }} onClick={() => setErrorMsg(null)}>
            <motion.div
              initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} transition={{ type: 'spring', damping: 25, stiffness: 300 }}
              onClick={e => e.stopPropagation()}
              style={{ width: '100%', background: 'var(--bg-panel)', borderTop: '1px solid var(--border)', borderRadius: '32px 32px 0 0', padding: '24px 24px 40px', boxShadow: '0 -10px 40px rgba(0,0,0,0.5)' }}
            >
              <div style={{ width: '40px', height: '4px', background: 'rgba(255,255,255,0.2)', borderRadius: '2px', margin: '0 auto 20px' }} />
              <div style={{ display: 'flex', alignItems: 'flex-start', gap: '16px' }}>
                <div style={{ width: '48px', height: '48px', borderRadius: '50%', background: 'rgba(239, 68, 68, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                  <AlertTriangle size={24} color="var(--danger)" />
                </div>
                <div style={{ flex: 1 }}>
                  <h3 style={{ margin: '0 0 8px 0', fontSize: '1.4rem', fontWeight: 700, color: 'var(--text-primary)' }}>Action Failed</h3>
                  <div style={{ margin: 0, color: 'var(--text-secondary)', fontSize: '1rem', lineHeight: '1.5' }}>{errorMsg}</div>
                </div>
              </div>
              <button onClick={() => setErrorMsg(null)} style={{ width: '100%', padding: '16px', borderRadius: '16px', border: 'none', background: 'var(--danger)', color: '#fff', fontSize: '1.05rem', fontWeight: 600, cursor: 'pointer', marginTop: '24px', boxShadow: '0 4px 12px rgba(239,68,68,0.3)' }}>Dismiss</button>
            </motion.div>
          </div>
        )}

        {/* --- Success Bottom Sheet --- */}
        {successData && (
          <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', zIndex: 1000, display: 'flex', alignItems: 'flex-end', backdropFilter: 'blur(4px)' }} onClick={() => { setSuccessData(null); setActiveTab('mybots'); }}>
            <motion.div
              initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} transition={{ type: 'spring', damping: 25, stiffness: 300 }}
              onClick={e => e.stopPropagation()}
              style={{ width: '100%', background: 'var(--bg-panel)', borderTop: '1px solid var(--border)', borderRadius: '32px 32px 0 0', padding: '24px 24px 40px', boxShadow: '0 -10px 40px rgba(0,0,0,0.5)' }}
            >
              <div style={{ width: '40px', height: '4px', background: 'rgba(255,255,255,0.2)', borderRadius: '2px', margin: '0 auto 24px' }} />
              
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', textAlign: 'center', marginBottom: '24px' }}>
                <div style={{ width: '64px', height: '64px', borderRadius: '50%', background: 'rgba(16, 185, 129, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '16px' }}>
                  <CheckCircle2 size={32} color="var(--success)" />
                </div>
                <h3 style={{ margin: '0 0 6px 0', fontSize: '1.4rem', fontWeight: 800, color: '#fff' }}>{successData.title}</h3>
                <p style={{ margin: 0, color: 'var(--text-secondary)', fontSize: '0.95rem' }}>{successData.message}</p>
              </div>

              <div style={{ background: 'var(--bg-dark)', padding: '16px', borderRadius: '16px', marginBottom: '24px', border: '1px dashed rgba(255,255,255,0.1)' }}>
                <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '1px', marginBottom: '16px', fontWeight: 700 }}>Activation Details</p>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
                  {successData.details.map((item, i) => (
                    <div key={i} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.9rem' }}>
                      <span style={{ color: 'var(--text-secondary)' }}>{item.label}</span>
                      <strong style={{ color: item.color || '#fff' }}>{item.value}</strong>
                    </div>
                  ))}
                  <div style={{ height: '1px', background: 'rgba(255,255,255,0.06)', margin: '4px 0' }} />
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.9rem' }}>
                    <span style={{ color: 'var(--text-secondary)' }}>Contract Length</span>
                    <strong style={{ color: '#fff' }}>{t('days365')}</strong>
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.9rem' }}>
                    <span style={{ color: 'var(--text-secondary)' }}>Timestamp</span>
                    <strong style={{ color: '#fff' }}>{new Date().toLocaleString()}</strong>
                  </div>
                </div>
              </div>

              <button onClick={() => { setSuccessData(null); setActiveTab('mybots'); }} style={{ width: '100%', padding: '16px', borderRadius: '16px', border: 'none', background: 'linear-gradient(135deg, #10B981, #059669)', color: '#fff', fontSize: '1.05rem', fontWeight: 700, cursor: 'pointer', boxShadow: '0 4px 15px rgba(16,185,129,0.3)' }}>View Active Bots</button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      <style>{`
        @keyframes pulse { 0%,100%{opacity:1} 50%{opacity:.4} }
        @keyframes spin { 100% { transform: rotate(360deg); } }
      `}</style>
    </motion.div>
  );
};

